import{n as e,t}from"./helpers-0sYvox5E.js";var n=[t({id:`archive-annex-001`,building:`archive-annex`,bullets:[`1.3-K2`],d:1,stem:`A marketing team keeps campaign files in an Amazon S3 bucket. Team members sometimes overwrite a file with the wrong content, and the company wants to restore the earlier content of any file with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Enable S3 Versioning on the bucket and restore the previous object version when needed`,`Each overwrite creates a new object version, so the earlier content can always be restored without any scripts.`],wrong:[[`Run a nightly script on an Amazon EC2 instance that copies every object to a second bucket`,`This relies on custom scripts to build and maintain, and it keeps only the content that existed at the last copy.`],[`Create an S3 Lifecycle rule that moves each object to S3 Glacier Flexible Retrieval after one day`,`A transition changes the storage class of the current object and is not a way to keep the earlier content of an overwritten file.`],[`Turn on S3 Block Public Access settings for the bucket`,`Block Public Access limits public exposure and does not preserve earlier content.`]],slot:0,evidence:[`s3-versioning|Versioning-enabled buckets can help you recover objects from accidental deletion or overwrite.`,`s3-versioning|If you overwrite an object, it results in a new object version in the bucket. You can always restore the previous version.`]}),t({id:`archive-annex-002`,building:`archive-annex`,bullets:[`1.3-K2`],d:1,stem:`A company enabled S3 Versioning on a bucket that stores contract documents. A user then deletes one document with a simple delete request that does not specify a version ID. Which statement BEST describes the result?`,correct:[`Amazon S3 adds a delete marker as the current version and keeps the earlier versions`,`A delete marker is added instead of removing the object permanently, so earlier versions remain recoverable.`],wrong:[[`Amazon S3 permanently removes every version of the document from the bucket right away`,`In a versioning-enabled bucket a simple delete does not remove the object permanently.`],[`Amazon S3 rejects the request because versioning-enabled buckets do not accept delete requests`,`Delete requests are accepted, and S3 handles them by adding a delete marker.`],[`Amazon S3 moves the document to S3 Glacier Deep Archive and keeps no other copy`,`A delete request does not change the storage class of any version.`]],slot:1,evidence:[`s3-versioning|if you delete an object, Amazon S3 inserts a delete marker instead of removing the object permanently.`,`s3-versioning|The delete marker becomes the current object version.`]}),t({id:`archive-annex-003`,building:`archive-annex`,bullets:[`1.3-K2`,`1.3-S5`],d:3,tags:[`trap:dr-strategies`],stem:`A company continuously replicates its order data to a second AWS Region. After a faulty release writes incorrect values into thousands of records, the company realizes that the replication may carry those values to the second Region. The company wants to be able to return the data to its state from before the release and wants to add this protection with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Add scheduled point-in-time backups with AWS Backup under a retention setting`,`Point-in-time backups protect against data corruption in a way that continuous replication alone may not, and a backup plan automates them.`],wrong:[[`Raise the replication frequency so the second Region always has the newest data`,`A faster copy of the same incorrect values does not let the company return to the state before the release.`],[`Promote the copy in the second Region to be the primary database`,`The second Region holds the same replicated data, so this does not undo the incorrect values.`],[`Add a third replica of the data in another Availability Zone of the primary Region`,`Another replica improves availability but copies the same incorrect values and gives no earlier point to recover to.`]],slot:2,evidence:[`dr-options|Continuous data replication protects you against some types of disaster, but it may not protect you against data corruption or destruction unless your strategy also includes versioning of stored data or options for point-in-time recovery.`,`backup-plans|You can assign resources to backup plans, and AWS Backup automatically backs up and retains backups for those resources according to the backup plan.`]}),t({id:`archive-annex-004`,building:`archive-annex`,bullets:[`1.3-K2`],d:2,stem:`A company runs Amazon EC2 instances with Amazon EBS volumes, Amazon RDS databases, Amazon DynamoDB tables, and Amazon EFS file systems. Each team backs up its own resources with separate scripts. The company wants one place to define backup schedules and retention for every one of these services with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Create backup plans in AWS Backup and assign the resources to them`,`AWS Backup centralizes and automates data protection across services and removes the need for custom scripts.`],wrong:[[`Write a shared AWS Lambda function that calls each service snapshot API on a schedule`,`This is another custom script that the company has to build and maintain for every service.`],[`Configure the native backup feature of each service separately and track the schedules in a spreadsheet`,`This keeps backup tasks service-by-service and does not give one place to define schedules and retention.`],[`Store AWS CloudFormation templates for every resource and redeploy them after a failure`,`Templates recreate resources and do not back up the data that the resources hold.`]],slot:3,evidence:[`backup-what-is|AWS Backup is a fully-managed service that makes it easy to centralize and automate data protection across AWS services, in the cloud, and on premises.`,`backup-what-is|It allows you to automate and consolidate backup tasks that were previously performed service-by-service, and removes the need to create custom scripts and manual processes.`,`backup-plans|In AWS Backup, a backup plan is a policy expression that defines when and how you want to back up your AWS resources, such as Amazon DynamoDB tables or Amazon Elastic File System (Amazon EFS) file systems.`]}),t({id:`archive-annex-005`,building:`archive-annex`,bullets:[`1.3-S5`],d:2,stem:`A company has hundreds of resources in one account. Resources that carry the tag backup-tier set to gold need daily backups, and new tagged resources appear every week. The company wants every new tagged resource protected automatically with the LEAST ongoing effort. Which solution meets these requirements?`,correct:[`Assign resources to an AWS Backup plan by using the backup-tier tag`,`AWS Backup integrates with tags, so a backup plan applies to every resource that carries the tag.`],wrong:[[`Start an on-demand backup job by hand each time a tagged resource is created`,`This is a manual step for every new resource and does not protect resources automatically.`],[`Create an AWS Config rule that reports resources that have no recent backup`,`A Config rule evaluates configuration and reports noncompliance, and it does not take backups.`],[`Add the identifier of each new resource to the backup plan after the team creates it`,`This repeats a manual change for every new resource instead of selecting resources by tag.`]],slot:0,evidence:[`backup-what-is|You can use AWS Backup to apply backup plans to your AWS resources in a wide variety of ways, including tagging them.`,`backup-what-is|Integration with AWS tags enables you to quickly apply a backup plan to a group of AWS resources, so that they are backed up in a consistent and compliant manner.`]}),t({id:`archive-annex-006`,postGuide:[`backup-ebs-cold-storage`],building:`archive-annex`,bullets:[`1.3-K3`],d:2,stem:`A company must keep backups of its Amazon EBS volumes for several years to meet retention rules. Backups older than a few weeks are rarely restored, and the company wants to reduce backup storage cost without writing custom code. Which solution meets these requirements MOST cost-effectively?`,correct:[`Use a backup plan with a lifecycle that moves older backups to cold storage`,`A lifecycle policy automatically transitions backups from warm to cold storage, which lowers backup storage cost while retention is met.`],wrong:[[`Keep every backup in warm storage and delete backups by hand when the retention period ends`,`This pays the warm storage rate for rarely used backups and relies on a manual deletion step.`],[`Copy every backup to a second Region and keep both copies for the full retention period`,`A second copy adds storage and does not move any backup to a lower-cost tier.`],[`Apply AWS Backup Vault Lock to the vault and keep all backups in warm storage`,`Vault Lock prevents early deletion and does not lower the cost of storing backups.`]],slot:1,evidence:[`backup-what-is|AWS Backup enables you to meet compliance requirements while minimizing backup storage costs by storing backups in a low-cost cold storage tier.`,`backup-what-is|You can configure lifecycle policies that automatically transition backups from warm storage to cold storage according to a schedule that you define.`,`backup-create-plan|Cold storage for Amazon EBS is Amazon EBS Snapshots Archive.`]}),t({id:`archive-annex-007`,building:`archive-annex`,bullets:[`1.3-K3`],d:2,stem:`A company stores data in several hundred Amazon S3 buckets and does not know which ones hold personal data. The security team wants continuous, broad visibility into where sensitive data might reside across the whole S3 estate without defining each bucket and schedule by hand. Which solution meets these requirements with the LEAST operational effort?`,correct:[`Turn on automated sensitive data discovery in Amazon Macie`,`Automated sensitive data discovery gives broad visibility into where sensitive data might reside in the S3 data estate.`],wrong:[[`Create one Amazon Macie sensitive data discovery job for a single bucket and run it once`,`A job is a deeper, targeted analysis of the buckets that you define, so it does not give broad visibility across the whole estate.`],[`Enable Amazon GuardDuty and review its findings for each bucket`,`GuardDuty analyzes logs for threats and does not classify what data the objects contain.`],[`Deploy an AWS Config rule that checks every bucket for personal data`,`Config rules evaluate configuration settings of resources and do not inspect object contents.`]],slot:2,evidence:[`macie-discovery|Automated sensitive data discovery provides broad visibility into where sensitive data might reside in your Amazon S3 data estate.`,`macie-discovery|Sensitive data discovery jobs provide deeper, more targeted analysis.`]}),t({id:`archive-annex-008`,building:`archive-annex`,bullets:[`1.3-K3`],d:2,tags:[`mock-reserve`],stem:`A company stores documents in Amazon S3 that contain internal customer numbers in the format CUST- followed by eight digits. The built-in Amazon Macie criteria do not detect this pattern, and the company wants Macie to report every object that contains such a number. Which solution meets these requirements with the LEAST effort?`,correct:[`Create a Macie custom data identifier with a regular expression`,`A custom data identifier defines a text pattern to match, which detects data that reflects the company's own scenarios.`],wrong:[[`Add the pattern to a Macie allow list that is used by the discovery job`,`An allow list holds text patterns that Macie ignores, so matching numbers would no longer be reported.`],[`Enable AWS CloudTrail data events for the buckets that hold the documents`,`CloudTrail records API activity and does not inspect the contents of objects.`],[`Run an Amazon Inspector scan against the buckets that hold the documents`,`Inspector scans EC2 instances, container images, and Lambda functions for vulnerabilities, not object contents.`]],slot:3,evidence:[`macie-discovery|Each custom data identifier specifies a regular expression (regex) that defines a text pattern to match and, optionally, character sequences and a proximity rule that refine the results.`,`macie-discovery|Allow lists – These specify text and text patterns that you want Macie to ignore.`,`inspector|Amazon Inspector discovers and scans Amazon EC2 instances, container images in Amazon ECR, and Lambda functions.`]}),t({id:`archive-annex-009`,building:`archive-annex`,bullets:[`1.3-K3`],d:3,stem:`A company keeps customer records in an Amazon RDS for PostgreSQL database and must find out whether the records contain personal data. The security team wants to use Amazon Macie for the analysis and does not want to write a custom scanner. Which solution meets these requirements with the LEAST custom code?`,correct:[`Export a snapshot of the database to Amazon S3 in Apache Parquet format and run a Macie sensitive data discovery job on the exported data`,`Macie is optimized for Amazon S3, and exporting RDS snapshots to S3 lets a job analyze data that is stored elsewhere.`],wrong:[[`Register the endpoint of the DB instance with Macie and start an automated sensitive data discovery run`,`Macie analyzes objects in Amazon S3 general purpose buckets, so it has no way to connect to a database endpoint.`],[`Run an Amazon Inspector scan of the DB instance to look for personal data in the tables`,`Inspector scans workloads for software vulnerabilities and unintended network exposure, not for personal data.`],[`Create an AWS Backup copy of the database and point Macie at the backup vault`,`A backup vault is not an S3 bucket, and Macie analyzes objects in S3.`]],slot:0,evidence:[`macie-discovery|Although Macie is optimized for Amazon S3, you can use it to discover sensitive data in resources that you currently store elsewhere.`,`macie-discovery|For example, export Amazon Relational Database Service or Amazon Aurora snapshots to Amazon S3 in Apache Parquet format.`,`macie-discovery|You can then create a job to analyze the data in Amazon S3.`]}),e({id:`archive-annex-010`,postGuide:[`security-hub-unified`],postGuideKey:[`security-hub-unified`],building:`archive-annex`,bullets:[`1.3-K3`],d:2,stem:`A security team wants Amazon Macie findings to appear in a broader view of the company security posture, and it wants a message sent to an Amazon SNS topic whenever Macie reports sensitive data. Which TWO actions meet these requirements with the LEAST custom development? (Choose two.)`,correct:[[`Configure Macie to publish its findings to AWS Security Hub`,`Macie can also publish findings to Security Hub (documented as AWS Security Hub CSPM), which gives a broader view of security posture.`],[`Create an Amazon EventBridge rule for Macie findings that targets the SNS topic`,`Macie publishes findings to EventBridge as events, and EventBridge can route them to SNS topics.`]],wrong:[[`Create an AWS Config rule that sends noncompliant bucket notifications to the SNS topic`,`Config rules report on resource configuration and do not carry Macie findings.`],[`Turn on S3 server access logging and parse the logs for personal data`,`Access logs record requests and are not Macie findings, and parsing them needs custom code.`],[`Ask AWS CloudTrail to deliver Macie findings directly to the SNS topic`,`CloudTrail records API activity and is not the way Macie findings are routed.`]],slots:[1,3],evidence:[`macie|Macie publishes findings to Amazon EventBridge as events.`,`macie|EventBridge is a serverless event bus service that can route findings data to targets such as AWS Lambda functions and Amazon Simple Notification Service (Amazon SNS) topics.`,`macie|You can configure Macie to also publish findings to AWS Security Hub CSPM.`]}),t({id:`archive-annex-011`,building:`archive-annex`,bullets:[`1.3-K3`],d:2,stem:`A financial services company must store trade confirmations in Amazon S3 so that no user, including the AWS account root user, can delete or overwrite an object version before its seven-year retention period ends. Which solution BEST meets these requirements?`,correct:[`Enable S3 Versioning and S3 Object Lock, and apply a seven-year retention period in compliance mode`,`Compliance mode prevents any user, including the root user, from overwriting or deleting a protected object version, and Object Lock needs versioning.`],wrong:[[`Apply a seven-year retention period in governance mode and grant the BypassGovernanceRetention permission only to administrators`,`In governance mode, users with the special permission can still delete the object or alter its lock settings.`],[`Place an S3 Object Lock legal hold on every object version in the bucket`,`A legal hold has no fixed period and can be placed and removed by any user who has the legal hold permission.`],[`Copy every object to a bucket in a second Region with S3 Cross-Region Replication`,`Replication creates a second copy and does not prevent deletion of an object version in the bucket.`]],slot:1,evidence:[`s3-object-lock|In compliance mode, a protected object version can't be overwritten or deleted by any user, including the root user in your AWS account.`,`s3-object-lock|Object Lock works only in buckets that have S3 Versioning enabled.`,`s3-object-lock|Legal holds can be freely placed and removed by any user who has the s3:PutObjectLegalHold permission.`]}),t({id:`archive-annex-012`,building:`archive-annex`,bullets:[`1.3-K3`],d:2,stem:`A media company stores raw footage in Amazon S3. It wants most users to be unable to delete the footage for one year, but the storage operations team must be able to remove objects early if a project is cancelled. The company also wants to test the retention setting before committing to a stricter one. Which solution BEST meets these requirements?`,correct:[`Use S3 Object Lock in governance mode and grant the bypass permission to the operations team`,`Governance mode protects objects from most users while selected users can still alter retention settings, and it can be used to test settings.`],wrong:[[`Use S3 Object Lock in compliance mode with a one-year retention period for all footage objects`,`In compliance mode no user, including the root user, can delete the object and the retention period cannot be shortened.`],[`Use an S3 Lifecycle rule that expires every object after one year`,`An expiration rule deletes objects at the end of the period and does not stop users from deleting them earlier.`],[`Place a legal hold on each object and give the operations team no further permissions`,`A legal hold has no expiration date and does not provide a one-year retention period.`]],slot:2,evidence:[`s3-object-lock|With governance mode, you protect objects against being deleted by most users, but you can still grant some users permission to alter the retention settings or delete the objects if necessary.`,`s3-object-lock|You can also use governance mode to test retention-period settings before creating a compliance-mode retention period.`,`s3-object-lock|To override or remove governance-mode retention settings, you must have the s3:BypassGovernanceRetention permission`]}),t({id:`archive-annex-013`,building:`archive-annex`,bullets:[`1.3-K3`],d:2,stem:`A company learns that it will be involved in a lawsuit. Legal counsel says that specific objects in an Amazon S3 bucket must stay unchanged until counsel releases them, and nobody can say when that will be. Which solution meets these requirements with the LEAST operational effort?`,correct:[`Place an S3 Object Lock legal hold on the objects in a bucket that has versioning enabled`,`A legal hold has no fixed amount of time and stays in place until it is removed, which fits an open-ended release date.`],wrong:[[`Set a compliance-mode Object Lock retention period of ten years on each relevant object version in the bucket`,`This guesses a fixed period, and a compliance-mode retention period cannot be shortened if counsel releases the objects sooner.`],[`Set a governance-mode retention period of one year and extend it every year`,`Users with special permissions can still delete the objects, and someone must remember to extend the period.`],[`Enable S3 Versioning on the bucket and leave the objects as they are`,`Versioning keeps earlier versions but does not stop an object version from being deleted.`]],slot:3,evidence:[`s3-object-lock|However, a legal hold doesn't have an associated fixed amount of time and remains in effect until removed.`,`s3-object-lock|You can use Legal Hold when you are not sure for how long you want your objects to stay immutable.`,`s3-object-lock|Object Lock works only in buckets that have S3 Versioning enabled.`]}),e({id:`archive-annex-014`,building:`archive-annex`,bullets:[`1.3-S5`],d:3,stem:`A company has an Amazon S3 bucket with S3 Object Lock enabled and wants to replicate its objects to a new bucket in another AWS Region. Which TWO settings must be configured on the destination bucket for replication to work? (Choose two.)`,correct:[[`Turn on S3 Versioning for the destination bucket`,`Both the source bucket and the destination bucket must have versioning enabled.`],[`Turn on S3 Object Lock for the destination bucket`,`If the source bucket has Object Lock enabled, the destination buckets must also have Object Lock enabled.`]],wrong:[[`Configure the destination bucket as a Requester Pays bucket`,`The destination buckets cannot be configured as Requester Pays buckets.`],[`Leave S3 Versioning off for the destination bucket to avoid duplicate versions`,`Replication requires versioning to be enabled on the destination bucket as well as the source.`],[`Add an S3 Lifecycle rule that expires every object in the destination bucket after one day`,`This is not a requirement for replication and would delete the replicas.`]],slots:[0,2],evidence:[`s3-replication-requirements|Both source and destination buckets must have versioning enabled.`,`s3-replication-requirements|If the source bucket has S3 Object Lock enabled, the destination buckets must also have S3 Object Lock enabled.`,`s3-replication-requirements|The destination buckets cannot be configured as Requester Pays buckets.`]}),t({id:`archive-annex-015`,building:`archive-annex`,bullets:[`1.3-S5`],d:1,stem:`A company stores archives in Amazon S3 in one Region. A compliance rule requires a second copy in a different geographic area, farther away than separate Availability Zones, and the copy must be created automatically as objects are written. Which solution is the SIMPLEST that meets these requirements?`,correct:[`Configure S3 Cross-Region Replication to a bucket in another Region`,`Cross-Region Replication copies objects to buckets in different Regions to satisfy requirements for greater distance.`],wrong:[[`Configure S3 Same-Region Replication to a second bucket in the same Region`,`The copy stays in the same Region, so it is not farther away than the Availability Zones.`],[`Rely on the S3 Standard storage class, which already stores objects across multiple Availability Zones`,`Availability Zones in one Region do not satisfy a rule that asks for a greater distance.`],[`Enable S3 Versioning on the bucket so that earlier versions are kept`,`Versions are kept in the same bucket and Region, so there is no second geographic area.`]],slot:0,evidence:[`s3-replication|Although Amazon S3 stores your data across multiple geographically distant Availability Zones by default, compliance requirements might dictate that you store data at even greater distances.`,`s3-replication|To satisfy these requirements, use Cross-Region Replication to replicate data between distant AWS Regions.`]}),t({id:`archive-annex-016`,building:`archive-annex`,bullets:[`1.3-S5`],d:2,stem:`A company configured S3 replication on a bucket last week. Objects uploaded since then are copied, but the millions of objects that were already in the bucket are missing from the destination bucket. The company wants those objects copied with the LEAST effort. Which solution meets this requirement?`,correct:[`Run an S3 Batch Replication job for the existing objects`,`Live replication skips objects that existed before it was set up, and Batch Replication replicates existing objects on demand.`],wrong:[[`Turn on S3 Replication Time Control for the replication rule`,`This controls the time frame for replicating new objects and does not copy objects that already existed.`],[`Delete the replication rule and create it again so that it rescans the bucket`,`Live replication does not replicate objects that existed before replication was set up, however often the rule is created.`],[`Enable S3 Transfer Acceleration on both buckets and upload the objects again`,`This changes the upload path and forces a manual upload of every existing object.`]],slot:1,evidence:[`s3-replication|Live replication doesn't replicate any objects that existed in the bucket before you set up replication.`,`s3-replication|To replicate existing objects from the source bucket to one or more destination buckets on demand, use S3 Batch Replication.`]}),t({id:`archive-annex-017`,building:`archive-annex`,postGuide:[`backup-hourly-frequency`],bullets:[`1.3-S5`],d:2,stem:`A company has a contract that requires new objects in an Amazon S3 bucket to reach a bucket in a second Region within a predictable time frame that is backed by a service-level agreement. Which solution meets this requirement?`,correct:[`Use S3 Cross-Region Replication with S3 Replication Time Control turned on`,`S3 Replication Time Control replicates new objects within 15 minutes and is backed by a service-level agreement.`],wrong:[[`Use S3 Cross-Region Replication without S3 Replication Time Control`,`Standard replication does not come with the predictable, SLA-backed time frame that the contract asks for.`],[`Run an S3 Batch Replication job every hour to copy the new objects to the second Region`,`Batch Replication is an on-demand job, and S3 Replication Time Control does not apply to it.`],[`Schedule an AWS Backup copy of the bucket to the second Region every hour`,`A scheduled backup copy is not live object replication with a replication time commitment.`]],slot:2,evidence:[`s3-replication|S3 RTC replicates 99.99 percent of new objects stored in Amazon S3 within 15 minutes (backed by a service-level agreement).`,`s3-replication|NoteS3 RTC does not apply to Batch Replication.`]}),t({id:`archive-annex-018`,building:`archive-annex`,bullets:[`1.3-S5`],d:2,stem:`A company has 12 AWS accounts in one Region, and each account writes application logs to its own S3 bucket. A regulation does not allow the data to leave the country, so everything must stay in this Region. The company wants the logs consolidated automatically into one bucket in a log archive account. Which solution meets these requirements?`,correct:[`Configure S3 Same-Region Replication from each account bucket to the central bucket`,`Same-Region Replication aggregates logs from several accounts into one in-Region bucket and keeps data in the Region.`],wrong:[[`Configure S3 Cross-Region Replication from each account bucket to a bucket in another Region`,`The data would leave the Region, which the regulation does not allow.`],[`Run an S3 Batch Replication job by hand every night for each account bucket`,`Batch Replication is an on-demand option, so the consolidation would not be automatic.`],[`Enable S3 Transfer Acceleration on the central bucket and upload the logs to it`,`Transfer Acceleration speeds up uploads and does not copy the logs from other buckets.`]],slot:3,evidence:[`s3-replication|Aggregate logs into a single bucket – If you store logs in multiple buckets or across multiple accounts, you can easily replicate logs into a single, in-Region bucket.`,`s3-replication|Same-Region Replication can help you automatically replicate critical data when compliance regulations don't allow the data to leave your country.`]}),t({id:`archive-annex-019`,building:`archive-annex`,bullets:[`1.3-S5`],d:3,stem:`A company replicates objects from a production account to a bucket in a separate security account in another Region. The replicas are rarely read and must be stored in the lowest-cost archive class, and the security account must own the replicas so that production account users cannot access them. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Create a Cross-Region Replication rule that sets the destination storage class to S3 Glacier Deep Archive and changes replica ownership to the destination account`,`Replication can put objects directly into an archive class, and the owner override option gives the destination account ownership.`],wrong:[[`Create a Cross-Region Replication rule to S3 Standard and run an AWS Lambda function that copies each replica into S3 Glacier Deep Archive`,`The copy step is custom code to build and maintain when replication can set the storage class directly.`],[`Create a Same-Region Replication rule that sets the destination storage class to S3 Glacier Deep Archive and changes replica ownership`,`Same-Region Replication copies within one Region, so the replicas would not be in another Region.`],[`Create a Cross-Region Replication rule that sets S3 Glacier Deep Archive as the storage class and leaves the production account as owner of the replicas`,`The production account would still own the replicas, so its users could keep access to them.`]],slot:0,evidence:[`s3-replication|You can use replication to directly put objects into S3 Glacier Flexible Retrieval, S3 Glacier Deep Archive, or another storage class in the destination buckets.`,`s3-replication|Regardless of who owns the source object, you can tell Amazon S3 to change replica ownership to the AWS account that owns the destination bucket.`,`s3-replication|You can use this option to restrict access to object replicas.`]}),t({id:`archive-annex-020`,building:`archive-annex`,bullets:[`1.3-S5`],d:3,stem:`A company has 40 accounts in an AWS Organizations structure. Compliance requires backups of the Amazon RDS databases and Amazon EBS volumes in every account to follow one policy defined in a single place and to be copied into a dedicated backup account. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Use AWS Backup cross-account management to apply backup plans across the organization and copy backups to a vault in the backup account`,`Cross-account management applies backup plans across the accounts of the organization, and backups can be copied to another account in the organization.`],wrong:[[`Create separate backup plans by hand in each account and copy the backups with custom scripts`,`This duplicates the plans in every account and adds scripts, which is the manual effort that cross-account management removes.`],[`Deploy AWS Config conformance packs to every account to take the backups and copy them`,`Conformance packs deploy rules and remediation actions and are not a backup service.`],[`Schedule an AWS Lambda function in each account that shares native snapshots with the backup account`,`This relies on custom code in 40 accounts and gives no single place to define the policy.`]],slot:1,evidence:[`backup-what-is|You can use AWS Backup to manage your backups across all AWS accounts inside your AWS Organizations structure.`,`backup-what-is|With cross-account management, you can automatically use backup policies to apply backup plans across the AWS accounts within your organization.`,`backup-what-is|You can also copy backups to multiple different AWS accounts inside your AWS Organizations management structure.`]}),t({id:`archive-annex-021`,building:`archive-annex`,bullets:[`1.3-K2`,`1.3-S5`],d:1,tags:[`mock-reserve`],stem:`A company runs an Amazon RDS for MySQL database. After an accidental data change, the company wants to be able to restore the database to any point in time during the previous two weeks. Which solution is the SIMPLEST that meets this requirement?`,correct:[`Keep automated backups turned on with a backup retention period of 14 days`,`Automated backups let the company recover to any point in time during the backup retention period.`],wrong:[[`Take one manual DB snapshot every week and keep each snapshot for two weeks`,`A snapshot captures one moment, so the database could not be restored to any point in between.`],[`Create a read replica of the database in another Availability Zone`,`A read replica is a live copy of the data, including any accidental change, and is not a backup to restore from.`],[`Convert the database to a Multi-AZ deployment`,`Multi-AZ improves availability and does not give the company earlier points in time to restore.`]],slot:2,evidence:[`rds-automated-backups|If necessary, you can recover your DB instance to any point in time during the backup retention period.`,`rds-backup-retention|You can set the backup retention period of a DB instance to between 0 and 35 days.`]}),t({id:`archive-annex-022`,building:`archive-annex`,bullets:[`1.3-K2`],d:1,tags:[`mock-reserve`],stem:`An engineer says that Amazon EBS automatically backs up the data on every volume, so the company has no backup process for its Amazon EC2 instances. The company must be able to restore the volumes after a failure. Which action BEST addresses the requirement?`,correct:[`Create an AWS Backup plan that takes scheduled snapshots of the volumes`,`AWS does not back up EBS volume data automatically, and a backup plan creates the snapshots on a schedule.`],wrong:[[`Do nothing, because EBS already backs up the volumes to Amazon S3 on its own`,`AWS does not automatically back up the data stored on EBS volumes.`],[`Turn on S3 Versioning for the bucket that holds the snapshots`,`Snapshots are stored in S3 buckets that you cannot access directly, and no snapshots exist until someone creates them.`],[`Attach each volume to a second instance with EBS Multi-Attach`,`Multi-Attach lets several instances use a volume and does not create a backup of it.`]],slot:3,evidence:[`ebs-snapshots|AWS does not automatically back up the data stored on your EBS volumes.`,`ebs-snapshots|it is your responsibility to create EBS snapshots on a regular basis, or to set up automatic snapshot creation by using Automate backups with Amazon Data Lifecycle Manager or AWS Backup.`,`ebs-snapshots|Snapshots are stored in Amazon S3, in S3 buckets that you can't access directly.`]}),t({id:`archive-annex-023`,building:`archive-annex`,bullets:[`1.3-K3`],d:3,stem:`A company uses AWS Backup to protect Amazon RDS and Amazon EBS resources. A regulator requires that no backup can be deleted by any user, including administrators with full IAM permissions, until a seven-year minimum retention ends. Backup jobs that use a shorter retention period must fail. The company accepts that the lock cannot be removed after a short testing period. Which solution BEST meets these requirements?`,correct:[`Apply AWS Backup Vault Lock in compliance mode with a seven-year minimum retention and a grace time for testing`,`After the grace time expires a compliance-mode vault lock is immutable, and jobs shorter than the minimum retention fail.`],wrong:[[`Apply AWS Backup Vault Lock in governance mode with a seven-year minimum retention`,`A vault lock in governance mode can have the lock removed by users who have sufficient IAM permissions.`],[`Set the backup plan lifecycle to seven years and rely on IAM policies to restrict deletion`,`IAM policies can be changed by privileged users, so nothing enforces retention against administrators.`],[`Copy the backups to a second Region and keep the copies in a vault without a lock`,`A copy in another vault does not stop a user with permissions from deleting backups in either vault.`]],slot:0,evidence:[`backup-vault-lock|Vaults locked in governance mode can have the lock removed by users with sufficient IAM permissions.`,`backup-vault-lock|Once the grace time expires, the vault and its lock are immutable and cannot be changed or deleted by any user or by AWS.`,`backup-vault-lock|If specified, backup and copy jobs to this vault with lifecycle retention periods shorter than the minimum retention period will fail.`]}),e({id:`archive-annex-024`,building:`archive-annex`,bullets:[`1.3-K3`],d:2,stem:`A company must show auditors that its AWS Backup backups follow the backup policy and must prevent anyone, including privileged users, from deleting backups before their retention period ends. Which TWO actions meet these requirements with the LEAST custom work? (Choose two.)`,correct:[[`Turn on AWS Backup Audit Manager with controls that match the backup policy and review its daily reports`,`Audit Manager finds resources that are not compliant with the controls and generates daily reports as evidence.`],[`Apply AWS Backup Vault Lock to the backup vault`,`Vault Lock prevents anyone, including privileged users, from deleting backups or altering their retention period.`]],wrong:[[`Download the company backup reports from AWS Artifact`,`AWS Artifact provides AWS compliance documents, and customers must obtain evidence of their own compliance themselves.`],[`Run an Amazon Macie sensitive data discovery job on the backup vault`,`Macie analyzes objects in S3 for sensitive data and does not report on backup policy compliance.`],[`Enable Amazon GuardDuty in the account that owns the vault`,`GuardDuty detects threats from logs and does not report on backup compliance or enforce retention.`]],slots:[2,4],evidence:[`backup-what-is|AWS Backup Audit Manager can help you locate specific activities and resources that are not yet compliant with the controls that you defined.`,`backup-what-is|It also generates daily reports that you can use to demonstrate evidence of compliance with your controls over time.`,`backup-what-is|You can use AWS Backup Vault Lock to prevent anyone (including you) from deleting backups or altering their retention period.`,`artifact|AWS customers are responsible for developing or obtaining documents that demonstrate the security and compliance of their companies.`]}),e({id:`archive-annex-025`,building:`archive-annex`,bullets:[`1.3-K2`,`1.3-K3`],d:3,stem:`A company stores invoices in an Amazon S3 bucket. It wants to restore the earlier content of any invoice that an employee overwrites, and it also wants every object version to be protected from deletion for 90 days after it is written, without setting a lock on each object. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Enable S3 Versioning on the bucket`,`Each overwrite creates a new object version, so the previous version can be restored.`],[`Enable S3 Object Lock and set a default retention period on the bucket`,`A retention period set on the bucket properties applies to all objects in the bucket automatically.`]],wrong:[[`Add an S3 Lifecycle rule that moves each object to S3 Glacier Flexible Retrieval after one day`,`A transition changes the storage class and does not keep earlier versions or protect against deletion.`],[`Turn on all four S3 Block Public Access settings for the bucket`,`Block Public Access limits public exposure and does not preserve versions or prevent deletion.`],[`Run an Amazon Macie sensitive data discovery job on the bucket every week`,`Macie finds sensitive data and neither restores earlier content nor protects objects from deletion.`]],slots:[0,3],evidence:[`s3-versioning|If you overwrite an object, it results in a new object version in the bucket. You can always restore the previous version.`,`s3-object-lock|You can place a retention period explicitly on an individual object version or on a bucket's properties so that it applies to all objects in the bucket automatically.`,`s3-object-lock|Object Lock works only in buckets that have S3 Versioning enabled.`]}),e({id:`archive-annex-026`,building:`archive-annex`,bullets:[`1.3-S5`],d:2,stem:`A company wants live replication from a bucket in one AWS account to a bucket owned by a different AWS account in another Region. The source bucket does not use S3 Object Lock. Which TWO requirements apply to this setup? (Choose two.)`,correct:[[`Versioning must be enabled on both the source bucket and the destination bucket`,`Replication requires versioning on both buckets.`],[`The destination bucket owner must grant the source bucket owner permission to replicate with a bucket policy`,`In a cross-account setup the destination bucket owner must grant this permission with a bucket policy.`]],wrong:[[`The destination bucket must be configured as a Requester Pays bucket`,`The destination buckets cannot be configured as Requester Pays buckets.`],[`S3 Object Lock must be turned on for the destination bucket`,`This is required only when the source bucket has Object Lock enabled, which is not the case here.`],[`S3 Transfer Acceleration must be enabled on both buckets`,`Transfer Acceleration speeds up transfers to a bucket and is not a requirement for replication.`]],slots:[1,4],evidence:[`s3-replication-requirements|Both source and destination buckets must have versioning enabled.`,`s3-replication-requirements|The owner of the destination buckets must grant the owner of the source bucket permissions to replicate objects with a bucket policy.`,`s3-replication-requirements|The destination buckets cannot be configured as Requester Pays buckets.`]})],r=[t({id:`certificate-office-001`,building:`certificate-office`,bullets:[`1.3-S3`],d:1,stem:`A company runs a public website on Amazon EC2 instances behind an Application Load Balancer. Clients must connect with HTTPS, and the load balancer, not the instances, must do the TLS decryption work so that the application can focus on business logic. Which solution BEST meets these requirements?`,correct:[`Add an HTTPS listener to the load balancer and deploy an ACM certificate on it`,`An HTTPS listener offloads encryption and decryption to the load balancer, and it needs at least one server certificate.`],wrong:[[`Add a TCP listener on port 443 to the Application Load Balancer`,`Listeners on an Application Load Balancer support only the HTTP and HTTPS protocols.`],[`Install the certificate on every instance and keep an HTTP listener on the load balancer`,`The instances, not the load balancer, would then do the encryption work.`],[`Attach a customer managed KMS key to the load balancer to terminate TLS connections`,`A KMS key protects data at rest and does not terminate TLS connections.`]],slot:0,evidence:[`alb-listeners|You can use an HTTPS listener to offload the work of encryption and decryption to your load balancer so that your applications can focus on their business logic.`,`alb-listeners|Listeners support the following protocols and ports: Protocols: HTTP, HTTPS`,`alb-https-listener|To create an HTTPS listener, you must deploy at least one SSL server certificate on your load balancer.`]}),t({id:`certificate-office-002`,building:`certificate-office`,bullets:[`1.3-S3`],d:2,tags:[`placement-eligible`],stem:`A company serves a static website through Amazon CloudFront from an Amazon S3 bucket. The bucket and all other company resources are in eu-west-1. The company will use its own domain name over HTTPS with a public ACM certificate. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Request the public certificate in us-east-1 and attach it to the distribution`,`CloudFront requires its ACM certificate in us-east-1, and it is then distributed to all the locations of the distribution.`],wrong:[[`Request the public certificate in eu-west-1 next to the bucket and attach it to the distribution`,`CloudFront can use an ACM certificate only if it is requested or imported in us-east-1, not in the Region of the bucket.`],[`Request a separate certificate in every Region that has CloudFront edge locations`,`This is unnecessary, because the us-east-1 certificate is distributed to all geographic locations of the distribution.`],[`Request the certificate in eu-west-1 and copy it to the US East (N. Virginia) Region`,`A certificate cannot be copied between Regions, so a new one must be requested or imported there.`]],slot:1,evidence:[`cf-https-requirements|To use an ACM certificate with a CloudFront distribution, make sure you request (or import) the certificate in the US East (N. Virginia) Region (us-east-1).`,`acm-overview|ACM certificates in this region that are associated with a CloudFront distribution are distributed to all the geographic locations configured for that distribution.`,`acm-overview|You cannot copy a certificate between regions.`]}),e({id:`certificate-office-003`,building:`certificate-office`,bullets:[`1.3-S3`],d:3,tags:[`placement-eligible`],stem:`A company serves its application through Amazon CloudFront with an Application Load Balancer in eu-west-1 as the custom origin. Viewers use the HTTPS address www.example.com and the origin domain name is origin.example.com. Traffic must be encrypted between viewers and CloudFront and between CloudFront and the origin, using ACM certificates. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Request an ACM certificate for www.example.com in us-east-1 and associate it with the distribution`,`A certificate for the viewer-facing name must be requested or imported in us-east-1 for CloudFront.`],[`Request an ACM certificate for origin.example.com in eu-west-1, deploy it on an HTTPS listener of the load balancer, and set the origin protocol policy to HTTPS Only`,`The origin certificate lives in the load balancer's Region, and HTTPS Only makes CloudFront use only HTTPS to the origin.`]],wrong:[[`Request one certificate in us-east-1 and deploy it on both the distribution and the load balancer`,`ACM certificates are regional and cannot be copied between Regions, so the us-east-1 certificate cannot be deployed on a load balancer in eu-west-1.`],[`Request the viewer-facing certificate in eu-west-1, because the origin is in that Region`,`The viewer-facing certificate for CloudFront must be in us-east-1 regardless of the Region of the origin.`],[`Leave the origin protocol policy on HTTP Only and rely on the viewer HTTPS setting`,`The hop from CloudFront to the origin would then be unencrypted, which the requirements rule out.`]],slots:[0,3],evidence:[`cf-https-requirements|If you want to require HTTPS between CloudFront and your origin, and you're using a load balancer in Elastic Load Balancing as your origin, you can request or import the certificate in any AWS Region.`,`cf-origin-https|HTTPS Only – CloudFront uses only HTTPS to communicate with your custom origin.`,`acm-overview|Certificates in ACM are regional resources.`,`acm-overview|You cannot copy a certificate between regions.`]}),t({id:`certificate-office-004`,building:`certificate-office`,bullets:[`1.3-S3`],d:3,tags:[`placement-eligible`],stem:`A company hosts a static site in an Amazon S3 bucket configured as a website endpoint, with Amazon CloudFront in front of it. A new compliance rule requires HTTPS between CloudFront and the origin. Which solution meets this requirement with the LEAST operational overhead?`,correct:[`Switch to the standard S3 bucket origin and use the Redirect HTTP to HTTPS viewer policy`,`An S3 origin that supports HTTPS provides its own certificate, and HTTPS to S3 follows the viewer protocol policy.`],wrong:[[`Set the origin protocol policy to HTTPS Only on the existing S3 website endpoint origin`,`Amazon S3 does not support HTTPS for website endpoints, so CloudFront cannot use HTTPS with that origin.`],[`Import a third-party certificate into ACM and select it for the S3 website endpoint`,`The website endpoint cannot serve HTTPS, so no certificate can be installed on it.`],[`Install an ACM certificate on the S3 bucket and keep the website endpoint origin`,`S3 provides the certificate when HTTPS is used, and a website endpoint does not support HTTPS in any case.`]],slot:2,evidence:[`cf-s3-https|If your Amazon S3 bucket is configured as a website endpoint, you can't configure CloudFront to use HTTPS to communicate with your origin because Amazon S3 doesn't support HTTPS connections in that configuration.`,`cf-s3-https|If you want to require HTTPS for communication between CloudFront and Amazon S3, you must change the value of Viewer Protocol Policy to Redirect HTTP to HTTPS or HTTPS Only.`,`cf-s3-https|When you use HTTPS with an Amazon S3 bucket that supports HTTPS communication, Amazon S3 provides the SSL/TLS certificate, so you don't have to.`]}),t({id:`certificate-office-005`,building:`certificate-office`,bullets:[`1.3-S3`],d:2,tags:[`placement-eligible`],stem:`A company serves its site through Amazon CloudFront under its own domain name over HTTPS. Many external links and bookmarks still use the plain HTTP scheme. All viewer traffic to CloudFront must use HTTPS, while viewers who follow HTTP links must still reach the content. Which viewer protocol policy BEST meets these requirements?`,correct:[`Redirect HTTP to HTTPS`,`HTTP GET and HEAD requests are redirected to HTTPS, so HTTP links keep working and the viewer then uses HTTPS.`],wrong:[[`HTTPS Only`,`CloudFront returns HTTP status code 403 to a viewer who sends an HTTP request, so HTTP links would stop working.`],[`Allow both HTTP and HTTPS`,`Viewers could keep using HTTP, so HTTPS would not be enforced for all viewer traffic.`],[`HTTPS Only for the origin protocol policy`,`The origin protocol policy governs CloudFront to the origin and does not control the protocol viewers use.`]],slot:3,evidence:[`cf-viewer-https|Redirect HTTP to HTTPS Viewers can use both protocols. HTTP GET and HEAD requests are automatically redirected to HTTPS requests.`,`cf-viewer-https|HTTPS only Viewers can access your content only if they're using HTTPS. If a viewer sends an HTTP request instead of an HTTPS request, CloudFront returns HTTP status code 403 (Forbidden) and does not return the object.`,`cf-viewer-https|You also can configure one or more cache behaviors to allow both HTTP and HTTPS, so that CloudFront requires HTTPS for some objects but not for others.`]}),t({id:`certificate-office-006`,building:`certificate-office`,bullets:[`1.3-S3`],d:2,tags:[`placement-eligible`],stem:`A company serves its site through Amazon CloudFront under its own domain with an ACM certificate. A group of customers with very old browsers cannot connect, because their clients do not support Server Name Indication (SNI). The company accepts additional monthly cost to serve them. Which solution BEST meets these requirements?`,correct:[`Switch the distribution to Legacy Clients Support for custom SSL client support`,`Legacy Clients Support lets older browsers that do not support SNI connect, with additional monthly charges.`],wrong:[[`Keep SNI-only support and request a wildcard certificate for the domain`,`Clients without SNI support still cannot connect, whatever names the certificate covers.`],[`Set the viewer protocol policy of the distribution to allow both HTTP and HTTPS`,`This weakens the HTTPS requirement and does not let clients without SNI use HTTPS.`],[`Move the ACM certificate from the distribution to the origin load balancer`,`Viewers connect to CloudFront, so the viewer-facing certificate must remain on the distribution.`]],slot:0,evidence:[`cloudfront-settings|Legacy Clients Support – With this setting, older web browsers and clients that don't support SNI can connect to the distribution. However, this setting incurs additional monthly charges.`,`cloudfront-settings|However, some viewers might use older web browsers or clients that don't support SNI, which means they can't connect to the distribution.`]}),t({id:`certificate-office-007`,building:`certificate-office`,bullets:[`1.3-S3`],d:2,tags:[`trap:alb-nlb-gwlb`],stem:`A compliance rule says that traffic from clients to a company's Amazon EC2 instances must stay encrypted all the way to the instances, and that the load balancer must not decrypt it. Clients connect on TCP port 443. Which solution BEST meets these requirements?`,correct:[`A Network Load Balancer with a TCP listener on port 443`,`A TCP listener passes encrypted traffic through to the targets without decrypting it.`],wrong:[[`An Application Load Balancer with an HTTPS listener and an ACM certificate`,`The load balancer terminates the front-end connection and decrypts client requests before sending them to the targets.`],[`An Application Load Balancer with a TCP listener on port 443`,`Listeners on an Application Load Balancer support only the HTTP and HTTPS protocols, not TCP.`],[`An Application Load Balancer with an HTTPS listener and an HTTPS target group`,`The load balancer still decrypts the client connection and then re-encrypts it, which the rule forbids.`]],slot:1,evidence:[`alb-https-listener|If you need to pass encrypted traffic to targets without the load balancer decrypting it, you can create a Network Load Balancer or Classic Load Balancer with a TCP listener on port 443.`,`alb-https-listener|The load balancer uses a server certificate to terminate the front-end connection and then decrypt requests from clients before sending them to the targets.`,`alb-listeners|Listeners support the following protocols and ports: Protocols: HTTP, HTTPS`]}),t({id:`certificate-office-008`,building:`certificate-office`,bullets:[`1.3-S3`],d:2,tags:[`placement-eligible`],stem:`A company serves example.com, www.example.com and images.example.com from one Amazon CloudFront distribution over HTTPS with ACM certificates. Which certificate request meets these requirements with the LEAST operational overhead?`,correct:[`One public certificate in us-east-1 for example.com and *.example.com`,`The wildcard covers the subdomains, the apex name is added as a second name, and one certificate in us-east-1 serves CloudFront.`],wrong:[[`One public certificate in us-east-1 for *.example.com only`,`A wildcard name protects the subdomains but not the bare or apex domain example.com.`],[`One public certificate in us-east-1 for example.com only`,`The apex name alone does not cover www.example.com or images.example.com.`],[`Two certificates, example.com in us-east-1 and *.example.com in eu-west-1`,`This needs two certificates, and the one in eu-west-1 cannot be used by CloudFront.`]],slot:2,evidence:[`acm-public-request|Also note that *.example.com protects only the subdomains of example.com, it does not protect the bare or apex domain (example.com).`,`acm-public-request|This is useful for protecting both a bare or apex domain (such as example.com) and its subdomains such as *.example.com).`,`cf-https-requirements|The certificate must cover the alternate domain name in the subject alternate name (SAN) field of the certificate.`]}),t({id:`certificate-office-009`,building:`certificate-office`,bullets:[`1.3-S7`],d:1,stem:`A company runs a public website behind an Application Load Balancer. The certificate must renew automatically so that an expired certificate never causes an outage, and the company controls its public DNS records. Which solution meets these requirements with the LEAST operational effort?`,correct:[`Request a public ACM certificate with DNS validation and deploy it on the load balancer`,`ACM renews an Amazon-issued certificate automatically when DNS validation is used and it is associated with a service such as Elastic Load Balancing.`],wrong:[[`Import a certificate from a third-party certificate authority into ACM`,`ACM does not provide managed renewal for imported certificates, so the company would have to reimport it before it expires.`],[`Request a public ACM certificate with email validation and answer the validation emails`,`Email validation needs someone to act on validation emails to renew, which is more manual work than DNS validation.`],[`Upload a certificate to the load balancer and set a calendar reminder to replace it`,`The company would renew and replace the certificate by hand each time.`]],slot:3,evidence:[`acm-renewal|ACM will either renew your certificates automatically (if you are using DNS validation), or it will send you email notices when expiration is approaching.`,`acm-renewal|ELIGIBLE if associated with another AWS service, such as Elastic Load Balancing or CloudFront.`,`acm-import|The certificates that you import work the same as those provided by ACM, with one important exception: ACM does not provide managed renewal for imported certificates.`,`acm-email-validation|ACM also sends validation emails to these same addresses to renew the certificate when the certificate is 45 days from expiry.`]}),t({id:`certificate-office-010`,building:`certificate-office`,bullets:[`1.3-S7`],d:2,tags:[`placement-eligible`],stem:`A company imported a certificate from a third-party certificate authority into ACM for its Amazon CloudFront distribution and has missed two renewals. The company wants to stop managing certificate expiry. Which solution meets this requirement with the LEAST operational overhead?`,correct:[`Request a public ACM certificate with DNS validation in us-east-1 and associate it with the distribution`,`An Amazon-issued certificate in use on CloudFront renews automatically with DNS validation, and CloudFront needs it in us-east-1.`],wrong:[[`Turn on managed renewal for the imported certificate in the ACM console`,`Imported certificates are not eligible for ACM managed renewal.`],[`Create an Amazon EventBridge rule that sends an expiry notice and reimport the certificate by hand`,`The company would still renew and reimport the certificate manually, so the burden remains.`],[`Request a public ACM certificate with DNS validation in eu-west-1 and associate it with the distribution`,`CloudFront can use an ACM certificate only if it is requested or imported in us-east-1.`]],slot:0,evidence:[`acm-renewal|NOT ELIGIBLE if imported.`,`acm-import|You are responsible for monitoring the expiration date of your imported certificates and for renewing them before they expire.`,`cf-https-requirements|To use an ACM certificate with a CloudFront distribution, make sure you request (or import) the certificate in the US East (N. Virginia) Region (us-east-1).`]}),t({id:`certificate-office-011`,building:`certificate-office`,bullets:[`1.3-S7`],d:3,tags:[`placement-eligible`],stem:`A company's Amazon CloudFront distribution uses an ACM public certificate that was validated with DNS. After a DNS cleanup, the renewal status of the certificate shows Pending validation. Which action BEST resolves this and keeps renewal automatic?`,correct:[`Re-create the CNAME validation record that ACM provided in the public DNS zone`,`ACM renews automatically while the certificate is in use and its CNAME record remains in place.`],wrong:[[`Delete the certificate from the distribution and associate it again to restart the renewal`,`The certificate stays in Pending validation until the CNAME record exists again; removing and re-adding it does not recreate the record.`],[`Import the same certificate into eu-west-1 so that ACM can renew it there`,`Imported certificates are not eligible for managed renewal, and CloudFront needs its certificate in us-east-1.`],[`Switch the validation of the certificate from DNS to email without creating a new certificate`,`Email validation would need someone to act on emails and does not restore the missing DNS record; ACM renews a DNS-validated certificate automatically when the CNAME record is in place.`]],slot:1,evidence:[`acm-renewal-status|If you used DNS validation, check to make sure your DNS record exists and that your certificate remains in use.`,`acm-dns-validation|ACM automatically renews your certificate as long as the certificate is in use and your CNAME record remains in place.`,`acm-dns-validation|You can stop automatic renewal either by removing the certificate from the AWS service with which it is associated or by deleting the CNAME record.`]}),t({id:`certificate-office-012`,building:`certificate-office`,bullets:[`1.3-S7`],d:1,stem:`A company must rotate the key material of a customer managed symmetric KMS key that encrypts its Amazon S3 data once a year. Applications must not need code changes. Which solution BEST meets these requirements?`,correct:[`Enable automatic key rotation on the existing KMS key`,`AWS KMS generates new key material for the key every year, and applications keep working without code changes.`],wrong:[[`Create a new KMS key each year and update every application to use it`,`The applications would need changes each year to use the new key.`],[`Enable key rotation on the AWS managed key for Amazon S3 in the account`,`Rotation cannot be enabled or disabled for AWS managed keys, and the company does not own that key.`],[`Delete the key and import new key material into a new key every year`,`This destroys the key and forces applications onto a different key.`]],slot:2,evidence:[`kms-rotation|By default, when you enable automatic key rotation for a KMS key, AWS KMS generates new cryptographic material for the KMS key every year.`,`kms-rotation|Because AWS KMS transparently decrypts with the appropriate key material, you can safely use a rotated KMS key in applications and AWS services without code changes.`,`kms-rotation|AWS KMS automatically rotates AWS managed keys every year (approximately 365 days). You cannot enable or disable key rotation for AWS managed keys.`]}),t({id:`certificate-office-013`,building:`certificate-office`,bullets:[`1.3-S7`],d:3,stem:`A company signs documents with an asymmetric RSA KMS key. Policy requires that the key material be rotated every year. Which solution BEST meets this requirement?`,correct:[`Create a new asymmetric KMS key and point the alias that the application uses to it`,`Asymmetric keys are not eligible for automatic rotation, so they are rotated manually by switching to a new key.`],wrong:[[`Enable automatic key rotation on the asymmetric KMS key`,`Automatic rotation is supported only on symmetric encryption KMS keys with key material that AWS KMS generates.`],[`Schedule an Amazon EventBridge rule that calls AWS KMS every year to replace the key material of the existing asymmetric key`,`AWS KMS does not replace the key material of an asymmetric KMS key in place, so no API call performs this rotation.`],[`Move the asymmetric KMS key into a custom key store and enable automatic rotation there`,`Keys in custom key stores are not eligible for automatic rotation either.`]],slot:3,evidence:[`kms-rotation|Automatic key rotation is supported only on symmetric encryption KMS keys with key material that AWS KMS generates (AWS_KMS origin).`,`kms-rotation|Manual rotation is a good choice when you want to rotate KMS keys that are not eligible for automatic or on-demand key rotation, including asymmetric KMS keys, HMAC KMS keys and KMS keys in custom key stores.`]}),e({id:`certificate-office-014`,building:`certificate-office`,bullets:[`1.3-S7`],d:2,stem:`A company turns on automatic rotation for a customer managed symmetric KMS key that encrypts Amazon EBS volumes and Amazon S3 objects. Which TWO statements are true after the key material rotates? (Choose two.)`,correct:[[`AWS KMS decrypts existing ciphertext with the key material that encrypted it`,`AWS KMS automatically chooses the version of the key material that was used to encrypt the data.`],[`The services that use the key keep working without code changes`,`AWS KMS decrypts transparently, so a rotated key can be used in applications and services without code changes.`]],wrong:[[`All existing data keys are re-encrypted immediately under the new key material`,`Key rotation does not rotate the data keys or re-encrypt any data protected by the key.`],[`The KMS key receives a new key ID and ARN`,`The KMS key is the same logical resource, and its properties do not change.`],[`A compromised data key is no longer a risk`,`Key rotation will not mitigate the effect of a compromised data key.`]],slots:[2,4],evidence:[`kms-rotation|When you use the rotated KMS key to decrypt ciphertext, AWS KMS uses the key material that was used to encrypt it.`,`kms-rotation|Because AWS KMS transparently decrypts with the appropriate key material, you can safely use a rotated KMS key in applications and AWS services without code changes.`,`kms-rotation|Key rotation has no effect on the data that the KMS key protects. It does not rotate the data keys that the KMS key generated or re-encrypt any data protected by the KMS key.`,`kms-rotation|The properties of the KMS key do not change`]}),e({id:`certificate-office-015`,building:`certificate-office`,bullets:[`1.3-S7`],d:2,stem:`A company's DNS-validated ACM certificate on an Application Load Balancer stopped renewing automatically after two changes made by different teams. Which TWO changes can stop automatic renewal? (Choose two.)`,correct:[[`The certificate was removed from the load balancer`,`Removing the certificate from the service it is associated with stops automatic renewal.`],[`The CNAME validation record was deleted from DNS`,`Deleting the CNAME record stops automatic renewal.`]],wrong:[[`A new listener rule was added to the load balancer`,`A listener rule changes request routing and has no effect on certificate renewal.`],[`AWS CloudTrail logging was turned on for ACM`,`CloudTrail only records API calls and does not affect renewal.`],[`The same certificate was also associated with a second load balancer in the Region`,`A certificate in use on a service remains eligible for renewal, and adding another association does not stop it.`]],slots:[1,4],evidence:[`acm-dns-validation|You can stop automatic renewal either by removing the certificate from the AWS service with which it is associated or by deleting the CNAME record.`,`acm-renewal|ELIGIBLE if associated with another AWS service, such as Elastic Load Balancing or CloudFront.`]}),t({id:`certificate-office-016`,building:`certificate-office`,bullets:[`1.3-S3`],d:2,tags:[`mock-reserve`],stem:`A company has a REST API in Amazon API Gateway in eu-central-1 and wants the ACM certificate for its custom domain name requested in eu-central-1, the same Region as the API. Which API Gateway custom domain type meets this requirement?`,correct:[`A Regional custom domain name`,`A Regional custom domain name uses an ACM certificate requested or imported in the same Region as the API.`],wrong:[[`An edge-optimized custom domain name`,`An edge-optimized custom domain name needs its ACM certificate in us-east-1.`],[`An edge-optimized custom domain name with its certificate copied from us-east-1`,`A certificate cannot be copied between Regions, so it could not be placed in eu-central-1.`],[`A Regional custom domain name with the certificate requested in us-east-1`,`For a Regional custom domain name the certificate must be in the same Region as the API.`]],slot:0,evidence:[`apigw-edge-cert|To use an ACM certificate with a Regional custom domain name, you must request or import the certificate in the same Region as your API.`,`apigw-edge-cert|To use an ACM certificate with an edge-optimized custom domain name, you must request or import the certificate in the US East (N. Virginia) – us-east-1 Region.`,`acm-overview|You cannot copy a certificate between regions.`]}),t({id:`certificate-office-017`,building:`certificate-office`,bullets:[`1.3-S3`],d:3,tags:[`mock-reserve`],stem:`A company runs the same website behind Application Load Balancers in us-west-2 and eu-west-1, both under www.example.com, and controls its public DNS records. Both load balancers must serve HTTPS with ACM certificates that renew automatically. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Request a certificate for www.example.com in each Region with DNS validation`,`A certificate is needed in each Region, and the same CNAME record validates the domain for any Region.`],wrong:[[`Request one certificate in us-west-2 and copy it to eu-west-1`,`A certificate cannot be copied between Regions.`],[`Request one certificate in us-east-1 and attach it to both load balancers`,`ACM certificates are regional, so each load balancer needs a certificate in its own Region.`],[`Import the same third-party certificate into both Regions and rely on managed renewal`,`Imported certificates are not eligible for ACM managed renewal.`]],slot:1,evidence:[`acm-overview|To use a certificate with Elastic Load Balancing for the same fully qualified domain name (FQDN) or set of FQDNs in more than one AWS region, you must request or import a certificate for each region.`,`acm-dns-validation|Since the CNAME validation token works for any AWS Region, you can re-create the same certificate in multiple Regions.`,`acm-renewal|NOT ELIGIBLE if imported.`]}),t({id:`certificate-office-018`,building:`certificate-office`,bullets:[`1.3-S7`],d:3,tags:[`mock-reserve`],stem:`A company's mobile app pins the public ACM certificate that secures its Application Load Balancer. After ACM renewed the certificate, the app can no longer connect. Which change keeps the app working across future renewals with the LEAST ongoing effort?`,correct:[`Pin the app to all Amazon root certificates instead of the leaf certificate`,`Renewal generates a new key pair, but the Amazon roots stay the same, so renewals do not break the pin.`],wrong:[[`Pin the app to the ARN of the certificate, which stays the same after renewal`,`An ARN is not part of the TLS handshake, and the app would still fail to validate the renewed certificate.`],[`Ask ACM to reuse the same public key when it renews the certificate`,`ACM generates a new public-private key pair to renew a certificate.`],[`Turn off managed renewal and re-request the certificate every few months`,`This adds manual work and a new certificate would still carry a new key pair.`]],slot:2,evidence:[`acm-best-practices|To renew a certificate, ACM generates a new public-private key pair. If your application pins the ACM certificate and the certificate is successfully renewed with a new public key, the application might be unable to connect to your domain.`,`acm-best-practices|If you're using a public certificate, pin your application to all available Amazon root certificates.`]})],i=[t({id:`charter-hall-001`,building:`charter-hall`,bullets:[`1.1-K3`],d:1,stem:`A company runs a web application on Amazon EC2 instances in a single Availability Zone. The company wants the application to keep running if the data center that hosts those instances loses power. Which design change is the SIMPLEST way to meet this requirement?`,correct:[`Run additional instances in a second Availability Zone of the same Region`,`Availability Zones have separate and redundant power infrastructure, so instances in a second zone keep running when the first zone loses power.`],wrong:[[`Add a second subnet in the same Availability Zone and spread the instances across both subnets`,`Both subnets would still sit in the Availability Zone that loses power, so the application would stop.`],[`Replace the instances with a larger instance type in the same Availability Zone`,`A larger instance does not remove the dependency on the power infrastructure of one Availability Zone.`],[`Add more instances in the same Availability Zone and place them in a second security group`,`More instances in the same zone share its power infrastructure, and security groups do not affect power.`]],slot:0,evidence:[`fault-isolation-az|An Availability Zone is one or more discrete data centers with separate and redundant power infrastructure, networking, and connectivity in an AWS Region.`,`global-infra|AWS customers focused on high availability can design their applications to run in multiple AZs to achieve even greater fault-tolerance.`]}),t({id:`charter-hall-002`,building:`charter-hall`,bullets:[`1.1-K3`],d:1,stem:`A new team member asks what an Availability Zone is. Which description is MOST accurate?`,correct:[`One or more discrete data centers with redundant power, networking, and connectivity in an AWS Region`,`This is how AWS defines an Availability Zone: one or more discrete data centers inside a Region.`],wrong:[[`A single physical server rack inside one data center that hosts the instances of one account and cannot be shared`,`A zone is made of one or more data centers, not a single rack, and it is not tied to one account.`],[`A global network location that caches content close to end users and shortens response times`,`That describes a content delivery edge location, not a group of data centers inside a Region.`],[`A geographic area that contains exactly one data center and its own regional service endpoint`,`A Region is the geographic area, and it contains several Availability Zones rather than one data center.`]],slot:1,evidence:[`global-infra|An Availability Zone (AZ) is one or more discrete data centers with redundant power, networking, and connectivity in an AWS Region.`,`global-infra|Each AWS Region consists of a minimum of three, isolated, and physically separate AZs within a geographic area.`]}),t({id:`charter-hall-003`,building:`charter-hall`,bullets:[`1.1-K3`],d:2,stem:`A company is launching an application for customers in Germany. Company policy requires that customer data stay in Europe, and the application needs a specific AWS service. Which approach to choosing a Region is BEST?`,correct:[`Choose a Region in Europe that offers the required service`,`A Region choice should weigh the services and features needed, closeness to users, and legal requirements such as keeping resources in Europe.`],wrong:[[`Choose the Region that has the largest number of Availability Zones, wherever it is located`,`The number of Availability Zones does not address the requirement to keep customer data in Europe.`],[`Choose the Region closest to the company headquarters, wherever the customers are located`,`The headquarters location does not decide customer latency or the requirement to keep data in Europe.`],[`Deploy into whichever Region is the default Region of the AWS CLI profile of the team`,`The default Region is a convenience setting and does not ensure that the data stays in Europe.`]],slot:2,evidence:[`regions-and-azs|select a Region that has the AWS services and features that you need.`,`regions-and-azs|For example, you want to create resources in Europe to be closer to your European customers or to meet legal requirements.`]}),t({id:`charter-hall-004`,building:`charter-hall`,bullets:[`1.1-K3`],d:2,stem:`A company wants to deploy a workload in an AWS Region that was introduced after March 2019. API calls to the Region fail even though the Region exists. Which action resolves the problem with the LEAST effort?`,correct:[`Enable the Region for the AWS account`,`A Region introduced after March 20, 2019 must be enabled before it can be accessed.`],wrong:[[`Create a new AWS account that is dedicated to the Region and move the workload into it`,`A new account is not needed; the existing account can enable the Region, which is far less effort.`],[`Request a service quota increase for the Region from AWS Support before making any more API calls`,`Quotas limit how much of a service can be used and do not enable a Region.`],[`Create an IAM role with administrator access and use it for every API call to the Region`,`Permissions do not enable a Region; the Region must be enabled before it can be accessed.`]],slot:3,evidence:[`regions-and-azs|To use a Region introduced after March 20, 2019, you must enable the Region before you can access it.`]}),e({id:`charter-hall-005`,building:`charter-hall`,bullets:[`1.1-K3`],d:2,stem:`An architect designs a database tier that replicates synchronously between Availability Zones of one Region. Which TWO characteristics of Availability Zones support this design? (Choose two.)`,correct:[[`The zones are close enough to each other for synchronous replication with single-digit millisecond latency`,`AWS states that zones are close enough to use synchronous replication with single-digit millisecond latency.`],[`The zones are meaningfully distant from each other to prevent correlated failures`,`The distance between zones lowers the chance that a single event affects more than one zone.`]],wrong:[[`Generators and cooling equipment are shared across the zones to keep power consistent`,`Common points of failure such as generators and cooling equipment are not shared across zones.`],[`All zones of a Region sit in one data center building that is divided into separate floors`,`A zone is made of one or more discrete data centers, and zones are meaningfully distant from each other.`],[`Traffic between the zones crosses the public internet because no dedicated links connect them`,`Zones are interconnected with high-bandwidth, low-latency networking over fully redundant, dedicated metro fiber.`]],slots:[0,3],evidence:[`fault-isolation-az|Availability Zones in a Region are meaningfully distant from each other, up to 60 miles (~100 km) to prevent correlated failures, but close enough to use synchronous replication with single-digit millisecond latency.`,`fault-isolation-az|Common points of failure, like generators and cooling equipment, are not shared across Availability Zones`,`fault-isolation-az|All Availability Zones in a Region are interconnected with high-bandwidth, low-latency networking, over fully redundant, dedicated metro fiber.`]}),t({id:`charter-hall-006`,building:`charter-hall`,bullets:[`1.1-K3`],d:3,stem:`A company must pick a Region for a new workload. Region X is in the country where the law requires the data to stay and offers every service the workload needs, but it is farther from most users. Region Y is closer to most users and offers every required service, but it is in another country. Region Z is in the required country but lacks one required service. Which choice BEST meets the requirements?`,correct:[`Region X, because it meets the legal and service requirements even though latency is higher`,`Services, legal requirements and latency all matter when choosing a Region, and only Region X meets the legal and service requirements.`],wrong:[[`Region Y, because lower latency to most users outweighs the requirement to keep the data in the country`,`Latency is a reason to choose a Region, but it cannot replace a legal requirement about where the data must stay.`],[`Region Z, because being in the required country is enough and the missing service can be ignored`,`The workload needs that service, so a Region that does not offer it fails the service requirement.`],[`Region Y, because encrypting the data makes the country of the Region irrelevant to the law`,`Encryption does not change a legal requirement that the data stay in a given country.`]],slot:0,evidence:[`regions-and-azs|select a Region that has the AWS services and features that you need.`,`regions-and-azs|you can lower network latency when you select a Region that is close to the majority of your users.`,`regions-and-azs|This information can help you meet your regulatory, compliance, and operational requirements.`]}),t({id:`charter-hall-007`,building:`charter-hall`,bullets:[`1.1-K3`],d:2,stem:`A company with a standard AWS account wants to deploy a workload into the GovCloud (US) Regions by using the console session and IAM roles of that account. Which statement BEST describes what happens?`,correct:[`The account cannot access those Regions; a GovCloud (US) account is needed`,`A GovCloud (US) account provides access to those Regions, which cannot be accessed from a standard AWS account.`],wrong:[[`The account can use the Regions after an administrator enables them, as with any opt-in Region`,`Enabling applies to the Regions of the account type; GovCloud Regions cannot be accessed from a standard AWS account.`],[`The account can use the Regions after an SCP in the organization allows access to the GovCloud Regions`,`An SCP does not grant permissions and cannot make Regions of another account type reachable.`],[`The account can use the Regions through the credentials of an AWS (China) account for all other partitions`,`An AWS (China) account provides access to the Beijing and Ningxia Regions only.`]],slot:1,evidence:[`regions-and-azs|You can't describe or access the Regions of one type of account from another.`,`regions-and-azs|For example, you can't access the AWS GovCloud (US) Regions or the China Regions from an AWS account.`,`regions-and-azs|An Amazon AWS (China) account provides access to the Beijing and Ningxia Regions only.`]}),t({id:`charter-hall-008`,building:`charter-hall`,bullets:[`1.1-K5`],d:1,stem:`A security engineer asks who is responsible for the host operating system and the virtualization layer of the physical servers that run the Amazon EC2 instances of the company. Under the AWS shared responsibility model, which answer is MOST accurate?`,correct:[`The company has no duty for those layers, because AWS operates, manages, and controls them`,`AWS operates, manages and controls the components from the host operating system and virtualization layer down to the physical security of the facilities.`],wrong:[[`The company, because the company chooses the instance type and therefore manages the host that runs it`,`Choosing an instance type does not move the host layer to the customer; AWS operates the host operating system and virtualization layer.`],[`The company, because customers manage every layer above the physical security of the data centers`,`The customer manages the guest operating system and above; AWS manages the host operating system and virtualization layer.`],[`Both equally, and the company approves each patch that AWS applies to the host operating system`,`The host layer is operated and controlled by AWS, so the company does not approve host patches.`]],slot:2,evidence:[`shared-responsibility|This shared model can help relieve the customer’s operational burden as AWS operates, manages and controls the components from the host operating system and virtualization layer down to the physical security of the facilities in which the service operates.`]}),t({id:`charter-hall-009`,building:`charter-hall`,bullets:[`1.1-K5`],d:1,stem:`An auditor asks who is responsible for the physical security of the data center facilities that host the workloads of a company on AWS. Which answer is BEST?`,correct:[`AWS, which operates and controls the components down to the physical security of the facilities`,`AWS operates, manages and controls the components from the host operating system and virtualization layer down to the physical security of the facilities.`],wrong:[[`The company, because customers must secure the facilities that run their own workloads in the cloud`,`Customers do not operate the facilities; AWS controls the components down to their physical security.`],[`The company, but only for the racks that host its production instances in the data centers of the Region`,`Customers do not manage racks; AWS operates the facilities in which the services run.`],[`The company, through the security groups that it attaches to the instances of its workloads`,`Security groups are the customer configuration of a virtual firewall and do not provide physical security.`]],slot:3,evidence:[`shared-responsibility|This shared model can help relieve the customer’s operational burden as AWS operates, manages and controls the components from the host operating system and virtualization layer down to the physical security of the facilities in which the service operates.`]}),t({id:`charter-hall-010`,building:`charter-hall`,bullets:[`1.1-K5`],d:2,stem:`A company stores customer records in Amazon S3 and Amazon DynamoDB. Which task remains the responsibility of the company under the AWS shared responsibility model? Choose the MOST accurate answer.`,correct:[`Managing the data, including its encryption options, and using IAM to apply the appropriate permissions`,`For abstracted services such as Amazon S3 and Amazon DynamoDB, customers manage their data, classify assets, and use IAM tools to apply permissions.`],wrong:[[`Patching the operating system of the servers that run the storage service that holds the records of the company`,`For abstracted services AWS operates the infrastructure layer, the operating system, and the platforms.`],[`Maintaining the hypervisor that runs the nodes that store the records of the company`,`AWS operates the components from the host operating system and virtualization layer down to the facilities.`],[`Replacing failed disks in the data centers that hold the stored objects of the company`,`The physical infrastructure is operated by AWS, so the company does not replace disks.`]],slot:0,evidence:[`shared-responsibility|For abstracted services, such as Amazon S3 and Amazon DynamoDB, AWS operates the infrastructure layer, the operating system, and platforms, and customers access the endpoints to store and retrieve data.`,`shared-responsibility|Customers are responsible for managing their data (including encryption options), classifying their assets, and using IAM tools to apply the appropriate permissions.`]}),t({id:`charter-hall-011`,building:`charter-hall`,bullets:[`1.1-K5`],d:2,stem:`A security review finds that the security group of an Amazon EC2 instance allows SSH from any IP address. Under the shared responsibility model, who must fix this configuration? Choose the BEST answer.`,correct:[`The company, because customers configure the AWS-provided security group firewall of their instances`,`The customer is responsible for the configuration of the AWS-provided firewall, called a security group, on each instance.`],wrong:[[`AWS, because security groups are part of the AWS-managed network infrastructure of the Region and its Availability Zones`,`AWS provides the firewall feature, but the customer is responsible for configuring the security group on each instance.`],[`AWS, because it must protect the infrastructure that runs Amazon EC2 from customer misconfiguration`,`Protecting the infrastructure is AWS responsibility; the rules of a security group are part of the customer configuration.`],[`AWS, because the remediation of every finding of a security review belongs to Security of the Cloud`,`Security in the Cloud is the customer responsibility and includes the configuration of the security groups of its instances.`]],slot:1,evidence:[`shared-responsibility|Customers that deploy an Amazon EC2 instance are responsible for management of the guest operating system (including updates and security patches), any application software or utilities installed by the customer on the instances, and the configuration of the AWS-provided firewall (called a security group) on each instance.`]}),e({id:`charter-hall-012`,building:`charter-hall`,bullets:[`1.1-K5`],d:2,stem:`A company runs a self-managed application on Amazon EC2 instances. Which TWO tasks are the responsibility of the company under the AWS shared responsibility model? (Choose two.)`,correct:[[`Applying security patches to the guest operating system of the instances`,`Customers assume responsibility for the guest operating system, including updates and security patches.`],[`Managing the application software that the company installs on the instances`,`Customers are responsible for any application software or utilities that they install on their instances.`]],wrong:[[`Operating the virtualization layer that runs the instances on the hosts`,`AWS operates and controls the components from the host operating system and virtualization layer.`],[`Controlling physical access to the data centers that house the hosts`,`AWS operates the physical security of the facilities in which the services run.`],[`Maintaining the networking and server hardware that the instances run on`,`The hardware, software, networking, and facilities that run AWS Cloud services are protected by AWS.`]],slots:[1,4],evidence:[`shared-responsibility|Customers that deploy an Amazon EC2 instance are responsible for management of the guest operating system (including updates and security patches), any application software or utilities installed by the customer on the instances, and the configuration of the AWS-provided firewall (called a security group) on each instance.`,`shared-responsibility|This infrastructure is composed of the hardware, software, networking, and facilities that run AWS Cloud services.`]}),t({id:`charter-hall-013`,building:`charter-hall`,bullets:[`1.1-K5`],d:3,stem:`A company hosts a static website on Amazon EC2 instances and manages the operating system and the web server software on them. To reduce its security responsibilities, the company moves the content to Amazon S3. Which responsibility does the move remove from the company?`,correct:[`Patching the operating system and platform software of the servers that serve the content`,`For an abstracted service such as Amazon S3, AWS operates the infrastructure layer, the operating system, and the platforms.`],wrong:[[`Managing who can access the content by applying permissions with IAM tools and bucket policies`,`Customers still use IAM tools to apply the appropriate permissions for abstracted services.`],[`Choosing the encryption options for the stored content that the website serves to visitors`,`Customers remain responsible for managing their data, including its encryption options.`],[`Classifying the content of the website to decide how sensitive each part of it is`,`Customers remain responsible for classifying their assets, whichever service stores them.`]],slot:2,evidence:[`shared-responsibility|For abstracted services, such as Amazon S3 and Amazon DynamoDB, AWS operates the infrastructure layer, the operating system, and platforms, and customers access the endpoints to store and retrieve data.`,`shared-responsibility|Customers are responsible for managing their data (including encryption options), classifying their assets, and using IAM tools to apply the appropriate permissions.`]}),t({id:`charter-hall-014`,building:`charter-hall`,bullets:[`1.1-K5`],d:2,stem:`A company uses Amazon EC2 and asks how patch management is divided between AWS and the customer. Which statement BEST describes the division?`,correct:[`AWS patches and fixes flaws in the infrastructure, and the customer patches its guest operating systems and applications`,`Patch management is a shared control: AWS patches the infrastructure and customers patch their guest OS and applications.`],wrong:[[`AWS patches the guest operating system of the instances, and the customer patches only its own application code`,`Customers are responsible for patching their guest operating systems as well as their applications.`],[`The customer patches the infrastructure under the instances, and AWS patches the applications that the customer installs`,`AWS patches and fixes flaws within the infrastructure, and the customer patches its applications.`],[`AWS handles every kind of patching for the instances, so the customer has no patching duties at all`,`The customer is responsible for patching the guest operating system and applications on its instances.`]],slot:3,evidence:[`shared-responsibility|Patch Management – AWS is responsible for patching and fixing flaws within the infrastructure, but customers are responsible for patching their guest OS and applications.`]}),e({id:`charter-hall-015`,building:`charter-hall`,bullets:[`1.1-K5`],d:3,stem:`A compliance team maps its controls to the AWS shared responsibility model. Which THREE controls are shared controls, in which AWS and the customer each apply a part in their own context? (Choose three.)`,correct:[[`Patch management`,`AWS patches and fixes flaws within the infrastructure, while customers patch their guest OS and applications.`],[`Configuration management`,`AWS maintains the configuration of its infrastructure devices, while the customer configures its own guest operating systems, databases and applications.`],[`Awareness and training`,`AWS trains AWS employees, but a customer must train its own employees.`]],wrong:[[`Physical and environmental controls of the data centers`,`These are inherited controls, which a customer fully inherits from AWS.`],[`Routing and zoning of customer data within specific security environments`,`This is a customer-specific control that is solely the responsibility of the customer.`]],slots:[1,3,4],evidence:[`shared-responsibility|Patch Management – AWS is responsible for patching and fixing flaws within the infrastructure, but customers are responsible for patching their guest OS and applications.`,`shared-responsibility|Configuration Management – AWS maintains the configuration of its infrastructure devices, but a customer is responsible for configuring their own guest operating systems, databases, and applications.`,`shared-responsibility|Awareness & Training - AWS trains AWS employees, but a customer must train their own employees.`]}),t({id:`charter-hall-016`,building:`charter-hall`,bullets:[`1.1-K3`],d:2,tags:[`mock-reserve`],stem:`An architect wants to understand how AWS limits the chance that a faulty service update affects several Availability Zones of a Region at the same time. Which statement is accurate?`,correct:[`AWS separates in time the deployments of service updates to the Availability Zones in the same Region`,`Deployments to Availability Zones in the same Region are separated in time to prevent correlated failure.`],wrong:[[`AWS deploys each service update to all Availability Zones of a Region at once so that they stay identical`,`Deployments to zones in the same Region are separated in time, not made all at once.`],[`AWS applies each update only to Regions that have a single Availability Zone before any other Region`,`The isolation comes from separating deployments to zones in time, not from a single-zone Region.`],[`AWS pauses deployments to every Availability Zone until the customers of the Region approve each update`,`AWS does not wait for customer approval; it separates deployments to zones in time.`]],slot:0,evidence:[`fault-isolation-az|When AWS deploys updates to its services, deployments to Availability Zones in the same Region are separated in time to prevent correlated failure.`]}),t({id:`charter-hall-017`,building:`charter-hall`,bullets:[`1.1-K5`],d:3,tags:[`mock-reserve`],stem:`An auditor asks a company to demonstrate controls over the physical and environmental security of the data centers that host its AWS workloads. The company does not operate those facilities. Which approach is BEST?`,correct:[`Review the third-party audit attestation documents of AWS to determine the controls that the company inherits`,`Physical and environmental controls are inherited, and attestation documents show which inherited controls remain for the customer.`],wrong:[[`Install badge readers and cameras in the AWS data centers that host the workloads of the company`,`Customers do not operate the facilities, and AWS operates the physical security of the facilities.`],[`Configure stricter security group rules to prove that the facilities are physically protected`,`Security group rules are a customer configuration of a virtual firewall and do not evidence physical security.`],[`Classify the controls as customer-specific controls because the workloads belong to the company`,`Physical and environmental controls are inherited from AWS; customer-specific controls depend on the application the customer deploys.`]],slot:1,evidence:[`shared-responsibility|Controls which a customer fully inherits from AWS. Physical and Environmental controls`,`shared-responsibility|Review third-party audit attestation documents to determine inherited controls and what required controls may be remaining for you to implement in your environment.`]}),e({id:`charter-hall-018`,building:`charter-hall`,bullets:[`1.1-K3`],d:3,tags:[`mock-reserve`],stem:`A company is building a workload for customers in Germany. Legal requirements say that customer data must stay in Europe, and the workload must keep running if one Availability Zone fails. Which THREE design decisions meet these requirements? (Choose three.)`,correct:[[`Create the resources in a Region in Europe that offers the services the workload needs`,`The Region choice weighs the services needed and legal requirements, so a European Region that offers the services keeps the data in Europe.`],[`Spread the instances across at least two Availability Zones of that Region`,`Availability Zones are isolated and physically separate, so a workload partitioned across them survives the loss of one zone.`],[`Replicate the data tier synchronously between the Availability Zones of that Region`,`The network between Availability Zones supports synchronous replication, so a zone failure does not lose committed data.`]],wrong:[[`Place a second copy of the workload in a Region outside Europe to be isolated from events in Europe`,`A copy of the customer data outside Europe breaks the legal requirement that the data stay in Europe.`],[`Run all instances in one Availability Zone on the largest instance type that is available`,`A larger instance type does not remove the single Availability Zone as a failure domain, so the workload would stop with that zone.`],[`Spread the instances across two subnets that are in the same Availability Zone`,`A subnet resides in one Availability Zone, so both subnets share the same failure domain and the workload would stop with that zone.`]],slots:[0,3,5],evidence:[`regions-and-azs|select a Region that has the AWS services and features that you need.`,`regions-and-azs|For example, you want to create resources in Europe to be closer to your European customers or to meet legal requirements.`,`global-infra|Each AWS Region consists of a minimum of three, isolated, and physically separate AZs within a geographic area.`,`global-infra|The network performance is sufficient to accomplish synchronous replication between AZs.`]})],a=[t({id:`compliance-registry-001`,building:`compliance-registry`,bullets:[`1.3-K1`],d:2,stem:`A company stores sales data in an Amazon S3 data lake and queries it with Amazon Athena and Amazon Redshift Spectrum. Analysts from each department must see only certain columns and rows. The company wants to define these rules in one central place instead of editing policies for every team. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Use AWS Lake Formation to grant column-level and row-level permissions on the data lake tables`,`Lake Formation is a single place to manage access controls and enforces them at the column, row, and cell levels across the analytics services.`],wrong:[[`Write a bucket policy for each department that allows only certain S3 prefixes`,`A bucket policy controls access to objects and prefixes, and it cannot limit which columns and rows of a table an analyst sees.`],[`Create an IAM policy for each department that lists the S3 objects it may read`,`This repeats policy edits for every team and still works at the object level, not at the column and row level.`],[`Turn on S3 Block Public Access for the data lake bucket and share the bucket with all analysts`,`Block Public Access limits public exposure and does not restrict what authorized analysts can see.`]],slot:0,evidence:[`lake-formation|Lake Formation provides a single place to manage access controls for data in your data lake.`,`lake-formation|Lake Formation permissions are enforced using granular controls at the column, row, and cell-levels across AWS analytics and machine learning services, including Amazon Athena, Amazon Quick, Amazon Redshift Spectrum, Amazon EMR, and AWS Glue.`]}),t({id:`compliance-registry-002`,building:`compliance-registry`,bullets:[`1.3-K1`],d:3,stem:`A data lake catalog contains thousands of tables that are classified as public, internal, or restricted. The company wants each team to receive access by classification instead of by listing every table, and new tables should be covered as soon as they are labeled. Which solution meets these requirements with the LEAST administrative effort?`,correct:[`Define LF-Tags for the classifications, attach them to tables and columns, and grant permissions on the tags`,`LF-Tags replace the policy definitions of thousands of resources with a few logical tags, so access follows the label.`],wrong:[[`Grant each team permissions on every table by name and update the grants whenever a table is added`,`This keeps one grant per table, which does not scale to thousands of tables and misses new tables until someone updates the grants.`],[`Write one IAM policy per table that lists the teams that may read it`,`This creates thousands of separate policy definitions and repeats the work for every new table.`],[`Place each classification in its own S3 bucket and manage access with a bucket policy per bucket`,`Labeling a table does not move its data, so each new table would have to be relocated into the matching bucket before the bucket policy covers it, and the existing lake would have to be reorganized.`]],slot:1,evidence:[`lake-formation|Use Lake Formation attribute-based access control to manage hundreds or even thousands of data permissions by creating custom labels called LF-Tags.`,`lake-formation|LF-Tags make sure that data governance can be scaled easily by replacing the policy definitions of thousands of resources with a few logical tags.`]}),t({id:`compliance-registry-003`,building:`compliance-registry`,bullets:[`1.3-K1`],d:2,stem:`A company wants to share selected tables of its data lake with a partner that has its own AWS account. The partner must receive fine-grained access to only those tables, and the company does not want to copy the data. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Use Lake Formation cross-account sharing to grant the partner access to the selected tables`,`Lake Formation shares data across accounts with fine-grained access to the catalog metadata and the underlying data.`],wrong:[[`Replicate the tables to a bucket in the partner account and let the partner query the copy`,`This creates a copy of the data, which the company wants to avoid, and the copy then has to be kept in sync.`],[`Attach a bucket policy that grants the partner account read access to the entire data lake bucket`,`The partner would see every table in the bucket instead of only the selected ones.`],[`Create IAM users in the company account for the partner staff and share their access keys`,`Sharing long-lived credentials is hard to manage and gives no table-level control without more configuration.`]],slot:2,evidence:[`lake-formation|Lake Formation also allows you to share data internally and externally across multiple AWS accounts, AWS organizations or directly with IAM principals in another account providing fine-grained access to the Data Catalog metadata and underlying data.`]}),t({id:`compliance-registry-004`,postGuide:[`lakeformation-hybrid-access`],postGuideKey:[`lakeformation-hybrid-access`],building:`compliance-registry`,bullets:[`1.3-K1`],d:3,stem:`A company runs a data lake where existing teams read tables through IAM policies and S3 permissions. The company wants to move to Lake Formation permissions one use case at a time without interrupting the permission policies of other users or workloads. Which solution meets these requirements?`,correct:[`Turn on Lake Formation hybrid access mode and set Lake Formation permissions for one group of users at a time`,`Hybrid access mode is an incremental path that sets Lake Formation permissions for specific users without interrupting existing policies.`],wrong:[[`Switch every database to Lake Formation permissions at once during a maintenance window and then fix access problems`,`Switching everything together does not keep the existing permission policies of other users and workloads running without interruption.`],[`Copy all tables into a new data lake that uses Lake Formation permissions and retire the old one after the copy`,`This duplicates the data and forces every workload to move at once, which is not an incremental path.`],[`Keep IAM policies for all current users and use Lake Formation permissions only for users who join after a set date`,`This leaves current users on IAM policies indefinitely and does not move any existing use case to Lake Formation.`]],slot:3,evidence:[`lake-formation|Lake Formation hybrid access mode provides the flexibility to selectively enable Lake Formation permissions for databases and tables in your Data Catalog.`,`lake-formation|With hybrid access mode, you now have an incremental path that allows you to set Lake Formation permissions for a specific set of users without interrupting the permission policies of other existing users or workloads.`]}),t({id:`compliance-registry-005`,postGuide:[`s3-bpa-organizations-policy`],postGuideKey:[`s3-bpa-organizations-policy`],building:`compliance-registry`,bullets:[`1.3-K1`,`1.3-S6`],d:2,stem:`A company has 60 accounts in AWS Organizations. The security team must make sure that no Amazon S3 bucket in any member account can be made public, even if a developer attaches a permissive bucket policy, and it wants to set this once for the whole organization. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Enable S3 Block Public Access at the organization level by using an AWS Organizations policy`,`Organization-level Block Public Access applies to selected accounts automatically and overrides account-level settings.`],wrong:[[`Ask each developer to turn on Block Public Access for every new bucket in the account they work in`,`This depends on every developer remembering a manual step in every account, so nothing is set once for the organization.`],[`Enable Amazon Macie in each account and fix any publicly accessible bucket that it reports`,`Macie reports a bucket that becomes publicly accessible after the fact and does not prevent it from being made public.`],[`Create an AWS Config rule in each account that notifies the team when a bucket policy allows public access`,`A Config rule detects the violation after it exists and must be created account by account.`]],slot:0,evidence:[`s3-block-public-access|Organization-level block public access uses AWS Organizations policies to centrally manage S3 public access controls across your entire organization.`,`s3-block-public-access|When enabled, these policies automatically apply to selected accounts and override individual account-level settings.`]}),t({id:`compliance-registry-006`,building:`compliance-registry`,bullets:[`1.3-K1`],d:1,stem:`A developer attached a bucket policy that grants public read access to an Amazon S3 bucket. The security team then turns on S3 Block Public Access settings for the bucket. Which statement BEST describes the result?`,correct:[`The Block Public Access settings override the policy, so public access to the bucket is limited`,`Block Public Access settings override policies and permissions that would otherwise allow public access.`],wrong:[[`The bucket policy takes precedence because it was written for this specific bucket`,`Block Public Access settings override bucket policies and permissions that allow public access, however specific the policy is.`],[`Amazon S3 deletes the bucket policy as soon as the Block Public Access settings are turned on`,`Block Public Access settings do not alter existing policies or ACLs, they only override their effect.`],[`Only requests that come from other AWS Regions are blocked, and requests from the same Region still succeed`,`The settings are not limited by the Region that a request comes from.`]],slot:1,evidence:[`s3-block-public-access|S3 Block Public Access settings override these policies and permissions so that you can limit public access to these resources.`,`s3-block-public-access|Block public access settings don't alter existing policies or ACLs.`]}),t({id:`compliance-registry-007`,building:`compliance-registry`,bullets:[`1.3-K1`],d:2,tags:[`mock-reserve`],stem:`A company wants the security team to receive a finding whenever an Amazon S3 bucket becomes publicly accessible, from a service that also keeps an inventory of the company S3 buckets. Which service BEST meets these requirements?`,correct:[`Amazon Macie`,`Macie maintains an inventory of S3 general purpose buckets and generates a finding when a bucket becomes publicly accessible.`],wrong:[[`Amazon Inspector`,`Inspector scans EC2 instances, container images, and Lambda functions for vulnerabilities, and it does not report on bucket access.`],[`AWS Shield Advanced`,`Shield Advanced protects applications against DDoS attacks and does not evaluate bucket access settings.`],[`AWS Artifact`,`Artifact provides AWS compliance documents and agreements, not findings about the company buckets.`]],slot:2,evidence:[`macie|If Macie detects a potential issue with the security or privacy of your data, such as a bucket that becomes publicly accessible, Macie generates a finding for you to review and remediate as necessary.`,`macie|When you enable Macie, Macie automatically generates and begins maintaining an inventory of your S3 general purpose buckets.`,`inspector|Amazon Inspector discovers and scans Amazon EC2 instances, container images in Amazon ECR, and Lambda functions.`]}),e({id:`compliance-registry-008`,building:`compliance-registry`,bullets:[`1.3-K1`],d:3,stem:`A company wants Amazon S3 to reject any request that tries to attach a public ACL to a bucket or its objects, and to reject any request that saves a bucket policy granting public access. Existing policies and ACLs may stay as they are for now. Which TWO settings meet these requirements? (Choose two.)`,correct:[[`Turn on the BlockPublicAcls setting`,`With this setting, calls such as PutBucketAcl and PutObjectAcl fail if the ACL is public.`],[`Turn on the BlockPublicPolicy setting`,`With this setting, S3 rejects calls to PutBucketPolicy if the policy allows public access.`]],wrong:[[`Turn on the IgnorePublicAcls setting`,`This setting makes S3 ignore public ACLs but it does not prevent new public ACLs from being set.`],[`Turn on the RestrictPublicBuckets setting`,`This setting restricts access to a bucket that has a public policy and does not reject the call that saves the policy.`],[`Turn on S3 Versioning for the bucket`,`Versioning keeps object versions and does not reject public ACLs or policies.`]],slots:[1,3],evidence:[`s3-block-public-access|BlockPublicAcls Setting this option to TRUE causes the following behavior: PutBucketAcl and PutObjectAcl calls fail if the specified access control list (ACL) is public.`,`s3-block-public-access|BlockPublicPolicy Setting this option to TRUE for a bucket causes Amazon S3 to reject calls to PutBucketPolicy if the specified bucket policy allows public access.`,`s3-block-public-access|Enabling this setting doesn't affect the persistence of any existing ACLs and doesn't prevent new public ACLs from being set.`]}),t({id:`compliance-registry-009`,building:`compliance-registry`,bullets:[`1.3-S1`],d:1,stem:`An auditor asks a company for the SOC reports and ISO certifications of the AWS infrastructure that the company uses. Which option is the BEST way to obtain these documents?`,correct:[`Download them from AWS Artifact`,`AWS Artifact provides on-demand downloads of AWS security and compliance documents and certifications.`],wrong:[[`Create an AWS Config conformance pack in the company account`,`A conformance pack evaluates the configuration of the company resources and does not provide AWS audit reports.`],[`Search the AWS CloudTrail event history for the reports`,`CloudTrail records API activity in the account and does not contain AWS compliance reports.`],[`Run an Amazon Inspector scan and send the findings to the auditor`,`Inspector findings describe vulnerabilities in the company workloads and are not AWS compliance reports.`]],slot:3,evidence:[`artifact|AWS Artifact provides on-demand downloads of AWS security and compliance documents.`,`artifact|AWS Artifact also provides downloads of certifications from accreditation bodies that validate the implementation and operating effectiveness of AWS security controls.`]}),t({id:`compliance-registry-010`,building:`compliance-registry`,bullets:[`1.3-S1`],d:2,stem:`A company has 25 accounts in an AWS Organizations structure. A compliance program requires the company to accept an agreement with AWS that applies to every one of these accounts and to track the status in one place. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Use AWS Artifact to accept and track the agreement for the accounts in the organization`,`AWS Artifact lets you review, accept, and track agreements with AWS for one account and for multiple accounts in an organization.`],wrong:[[`Open an AWS Support case for each account to request and sign the agreement`,`This creates 25 separate manual requests and gives no single place to track the status.`],[`Use service control policies in AWS Organizations to accept the agreement for member accounts`,`Service control policies set the maximum available permissions for accounts and do not accept agreements.`],[`Download the agreement from AWS Config and store the signed copies in an Amazon S3 bucket`,`AWS Config evaluates resource configuration and is not where agreements with AWS are accepted.`]],slot:0,evidence:[`artifact|you can use AWS Artifact to review, accept, and track the status of your agreements with AWS for your AWS account and for multiple AWS accounts in your organization.`,`orgs-scps|SCPs offer central control over the maximum available permissions for the IAM users and IAM roles in your organization.`]}),t({id:`compliance-registry-011`,building:`compliance-registry`,bullets:[`1.3-S1`],d:1,tags:[`mock-reserve`],stem:`A company is evaluating a product from an independent software vendor that is sold on AWS Marketplace. The company wants to review the vendor security and compliance documents. Which service BEST meets this requirement?`,correct:[`AWS Artifact`,`AWS Artifact provides downloads of security and compliance documents for independent software vendors who sell their products on AWS Marketplace.`],wrong:[[`Amazon Macie`,`Macie discovers sensitive data in Amazon S3 and does not provide vendor documents.`],[`AWS Config`,`AWS Config evaluates the configuration of resources in the company account and does not provide vendor documents.`],[`AWS Shield`,`Shield protects applications against DDoS attacks and does not provide vendor documents.`]],slot:1,evidence:[`artifact|With AWS Artifact, you can also download security and compliance documents for independent software vendors (ISVs) who sell their products on AWS Marketplace.`]}),t({id:`compliance-registry-012`,building:`compliance-registry`,bullets:[`1.3-S1`],d:1,stem:`A company wants to be notified automatically when a resource in its account is created or changed in a way that violates the internal configuration standards. Which service BEST meets this requirement?`,correct:[`AWS Config with rules that represent the ideal configuration settings`,`AWS Config continuously evaluates resources as they are created or changed and flags those that violate a rule.`],wrong:[[`AWS CloudTrail event history filtered for configuration-related API calls`,`CloudTrail records API activity, but it does not evaluate resources against configuration rules or flag violations.`],[`AWS Artifact reports for the services in use`,`Artifact provides AWS compliance documents about the AWS services and does not evaluate the company resources.`],[`Amazon Macie with a sensitive data discovery job`,`Macie looks for sensitive data in Amazon S3 and does not check resource configuration.`]],slot:2,evidence:[`config-what-is|You can use AWS Config rules to evaluate the configuration settings of your AWS resources.`,`config-what-is|When AWS Config detects that a resource violates the conditions in one of your rules, AWS Config flags the resource as noncompliant and sends a notification.`,`config-what-is|AWS Config continuously evaluates your resources as they are created, changed, or deleted.`]}),e({id:`compliance-registry-013`,building:`compliance-registry`,bullets:[`1.3-S1`],d:2,stem:`A company with 30 accounts wants to deploy one set of AWS Config rules and remediation actions as a single unit to every account. It also wants to see the compliance data of all accounts and Regions in one account. Which TWO actions meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`Deploy the rules and remediation actions as a conformance pack across the organization`,`A conformance pack is a collection of Config rules and remediation actions that can be deployed as a single entity across an organization.`],[`Create an AWS Config aggregator in a central account`,`An aggregator collects configuration and compliance data from multiple accounts and Regions into a single account and Region.`]],wrong:[[`Create an AWS CloudTrail trail in each account`,`A trail records API activity and does not deploy rules or show compliance data.`],[`Download the AWS compliance reports from AWS Artifact for each account`,`Artifact documents describe AWS controls and do not deploy rules or aggregate compliance data.`],[`Run an Amazon Macie discovery job in each account`,`Macie looks for sensitive data in Amazon S3 and does not deploy rules or aggregate compliance data.`]],slots:[0,4],evidence:[`config-conformance-packs|A conformance pack is a collection of AWS Config rules and remediation actions that can be easily deployed as a single entity in an account and a Region or across an organization in AWS Organizations.`,`config-what-is|An aggregator collects AWS Config configuration and compliance data from multiple AWS accounts and AWS Regions into a single account and Region.`]}),t({id:`compliance-registry-014`,building:`compliance-registry`,bullets:[`1.3-S1`],d:2,stem:`AWS Config has been recording a company account for two years. An auditor now asks which inbound port rules an Amazon EC2 security group allowed on a specific date five months ago. Which solution provides this information with the LEAST effort?`,correct:[`View the recorded configuration history of the security group in AWS Config`,`AWS Config provides the historical configurations of resources, including the port rules that were open at a specific time.`],wrong:[[`Search the AWS CloudTrail event history for the security group changes around that date`,`Event history covers only the past 90 days of management events, so it cannot reach back five months.`],[`Run an Amazon Inspector network scan of the instances today`,`A scan shows the current exposure and cannot show the rules that were in place five months ago.`],[`Download the SOC reports from AWS Artifact for that period`,`Artifact reports describe AWS controls and do not list the rules of a customer security group.`]],slot:3,evidence:[`config-what-is|To demonstrate compliance, you need access to the historical configurations of your resources.`,`config-what-is|You can also use AWS Config to view the configuration of your EC2 security groups, including the port rules that were open at a specific time.`,`cloudtrail-what-is|Event history – The Event history provides a viewable, searchable, downloadable, and immutable record of the past 90 days of management events in an AWS Region.`]}),t({id:`compliance-registry-015`,building:`compliance-registry`,bullets:[`1.3-S1`],d:3,stem:`A regulation requires a company to keep a record of user and API activity from every account in its AWS Organizations structure for seven years. Auditors must be able to run SQL queries on the record, and the company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Create an organization trail that delivers to an Amazon S3 bucket, expire the logs with S3 Lifecycle after seven years, and query them with Amazon Athena`,`An organization trail logs the management account and all member accounts into S3, Lifecycle controls how long the logs are kept, and Athena runs SQL on them.`],wrong:[[`Rely on the AWS CloudTrail event history in each account, which keeps the activity record`,`Event history covers only the past 90 days of management events, which falls short of seven years.`],[`Create a trail in the management account only, deliver it to an S3 bucket, and query the logs with Amazon Athena`,`A trail that is not an organization trail records the activity of its own account, and the requirement covers every account.`],[`Turn on AWS Config in every account and use the configuration history as the activity record`,`Config records resource configurations and does not record user and API activity.`]],slot:0,evidence:[`cloudtrail-org-trail|Organization trails log events for the management account and all member accounts in the organization.`,`cloudtrail-what-is|Trails – Trails capture a record of AWS activities, delivering and storing these events in an Amazon S3 bucket, with optional delivery to CloudWatch Logs and Amazon EventBridge.`,`cloudtrail-what-is|Event history – The Event history provides a viewable, searchable, downloadable, and immutable record of the past 90 days of management events in an AWS Region.`,`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`]}),t({id:`compliance-registry-016`,building:`compliance-registry`,bullets:[`1.3-S1`,`1.3-S6`],d:2,stem:`A broker-dealer must keep electronic records so that they cannot be overwritten or deleted during the retention period, in an environment that is subject to SEC 17a-4, CFTC, and FINRA regulations. The company wants an Amazon S3 feature that has been assessed for use in such environments. Which solution BEST meets this requirement?`,correct:[`Store the records in a bucket with S3 Versioning and S3 Object Lock`,`Object Lock uses a WORM model, works with versioning, and has been assessed for environments that are subject to these regulations.`],wrong:[[`Store the records in a bucket with S3 Versioning only`,`Versioning keeps multiple versions of objects and is not a write-once-read-many model.`],[`Store the records in a bucket with an S3 Lifecycle expiration rule set to the retention period`,`A lifecycle rule deletes expired objects and does not make records write-once-read-many.`],[`Store the records in a bucket that uses S3 Replication to a second Region`,`Replication copies objects to another bucket and does not provide a write-once-read-many model.`]],slot:1,evidence:[`s3-object-lock|S3 Object Lock has been assessed by Cohasset Associates for use in environments that are subject to SEC 17a-4, CFTC, and FINRA regulations.`,`s3-object-lock|Object Lock uses a write-once-read-many (WORM) model to store objects.`,`s3-object-lock|Object Lock works only in buckets that have S3 Versioning enabled.`]}),t({id:`compliance-registry-017`,building:`compliance-registry`,bullets:[`1.3-S1`],d:2,tags:[`mock-reserve`],stem:`A company must show auditors records of which Amazon S3 objects contain sensitive data and of the analysis that was performed to find them. Which solution produces these records with the LEAST operational overhead?`,correct:[`Use Amazon Macie sensitive data findings and sensitive data discovery results`,`Macie produces records of the sensitive data that it finds and of the analysis that it performs.`],wrong:[[`Use the AWS CloudTrail event history for the account and export it for the auditors`,`Event history lists management events and does not record which objects contain sensitive data.`],[`Use the compliance reports in AWS Artifact`,`Artifact documents describe AWS controls and do not describe the contents of the company objects.`],[`Use an AWS Config rule that evaluates each bucket`,`A Config rule evaluates configuration settings and does not inspect object contents.`]],slot:2,evidence:[`macie-discovery|To help you meet and maintain compliance with your data security and privacy requirements, Macie produces records of the sensitive data that it finds and the analysis that it performs`]}),e({id:`compliance-registry-018`,building:`compliance-registry`,bullets:[`1.3-S1`],d:2,stem:`An auditor asks a company for evidence of two things: that the AWS infrastructure meets recognized standards, and that the company own resources continue to meet its configuration rules. Which TWO actions provide this evidence with the LEAST custom work? (Choose two.)`,correct:[[`Download the AWS compliance reports and certifications from AWS Artifact`,`Artifact provides on-demand downloads of AWS security and compliance documents that can be given to auditors.`],[`Evaluate the company resources with AWS Config rules and share the compliance results`,`AWS Config evaluates the configuration settings of resources against the rules that represent the ideal settings.`]],wrong:[[`Use AWS Artifact to evaluate whether the company resources meet the configuration rules`,`Artifact provides AWS documents and does not evaluate customer resources; customers are responsible for documents about their own companies.`],[`Use Amazon Macie reports as the evidence of AWS infrastructure compliance`,`Macie reports on sensitive data in the company S3 buckets and not on the compliance of the AWS infrastructure.`],[`Use the AWS CloudTrail event history as proof that the resources meet the configuration rules`,`Event history records activity and does not evaluate configuration against rules.`]],slots:[2,3],evidence:[`artifact|To demonstrate the security and compliance of the AWS infrastructure and services that you use, you can submit AWS Artifact documents to your auditors or regulators as audit artifacts.`,`artifact|AWS customers are responsible for developing or obtaining documents that demonstrate the security and compliance of their companies.`,`config-rules|Use AWS Config to evaluate the configuration settings of your AWS resources.`]}),t({id:`compliance-registry-019`,building:`compliance-registry`,bullets:[`1.3-S6`],d:2,stem:`A company stores application logs in Amazon S3. The logs are read often for the first 30 days and rarely after that. A regulation requires keeping them for a fixed period, after which they must be deleted. The company wants to meet this with the LEAST operational overhead and the LOWEST storage cost. Which solution meets these requirements?`,correct:[`Create an S3 Lifecycle configuration with transition actions to lower-cost storage classes and an expiration action at the end of the period`,`Transition actions move objects to lower-cost classes, and an expiration action deletes them after the regulatory period.`],wrong:[[`Run a scheduled AWS Lambda function that copies each log to another storage class and deletes old logs`,`This is custom code to build and maintain when S3 Lifecycle performs both actions without code.`],[`Keep the logs in S3 Standard and have an administrator delete them by hand when the period ends`,`This pays the S3 Standard rate for rarely read logs and depends on a manual deletion step.`],[`Enable S3 Object Lock in compliance mode on the bucket with a retention period that equals the period`,`Object Lock prevents deletion during the period and does not move the logs to a lower-cost class.`]],slot:3,evidence:[`s3-lifecycle|There are two types of actions: Transition actions – These actions define when objects transition to another storage class.`,`s3-lifecycle|Expiration actions – These actions define when objects expire.`,`s3-lifecycle|For example, you might to choose to expire objects after they have been stored for a regulatory compliance period.`]}),e({id:`compliance-registry-020`,building:`compliance-registry`,bullets:[`1.3-S6`],d:3,stem:`A bucket with S3 Versioning enabled holds financial exports. After a seven-year retention period, every trace of an export must be removed, including all earlier versions and any leftover delete marker, and the lifecycle configuration must remove the delete marker explicitly. Which THREE actions together meet these requirements? (Choose three.)`,correct:[[`An expiration action for the current versions of the objects after the retention period`,`Expiration applies to the current version of an object, which is the starting point of the removal.`],[`A NoncurrentVersionExpiration action that permanently deletes noncurrent versions`,`Object expiration has no effect on noncurrent versions, so this action removes the earlier versions.`],[`An expiration action that removes expired object delete markers`,`The Expiration action can direct S3 to remove expired object delete markers, so none is left behind.`]],wrong:[[`A transition action to S3 Glacier Deep Archive after the retention period`,`A transition changes the storage class and does not remove any version.`],[`Suspend S3 Versioning on the bucket after the retention period`,`Suspending versioning only stops new versions from accruing; the existing versions and delete markers stay, so nothing is removed.`],[`An action that aborts incomplete multipart uploads after one day`,`This cleans up unfinished uploads and does not remove completed object versions.`]],slots:[1,2,5],evidence:[`s3-lifecycle-expire|Object expiration applies only to an object's current version (it has no impact on noncurrent object versions).`,`s3-lifecycle-expire|You can use the NoncurrentVersionExpiration action element to direct Amazon S3 to permanently delete noncurrent versions of objects.`,`s3-lifecycle-expire|You can also use the Expiration action to direct Amazon S3 to remove any expired object delete markers.`,`s3-versioning|The bucket owner (or any user with appropriate permissions) can suspend versioning to stop accruing object versions.`]}),t({id:`compliance-registry-021`,building:`compliance-registry`,bullets:[`1.3-S6`],d:2,stem:`A security engineer attaches a bucket policy that denies all actions for all principals on a general purpose S3 bucket, hoping to stop deletions. The bucket also has an S3 Lifecycle configuration with an expiration rule. Which statement BEST describes the effect on the lifecycle rule?`,correct:[`The lifecycle rule keeps working, because a bucket policy cannot prevent deletions by a lifecycle rule`,`AWS states that even a bucket policy that denies all actions for all principals does not stop the lifecycle configuration.`],wrong:[[`The deny policy blocks the rule, so no object in the bucket expires until the deny statement is removed`,`A bucket policy cannot prevent deletions or transitions by a lifecycle rule.`],[`The rule runs only for objects that are uploaded after the bucket policy was attached`,`The rules of a lifecycle configuration apply to existing objects as well as to objects that are added later.`],[`The rule moves each expiring object to another bucket instead of deleting it`,`An expiration action makes S3 delete the expired objects on your behalf.`]],slot:0,evidence:[`s3-lifecycle|You can't use a bucket policy to prevent deletions or transitions by an S3 Lifecycle rule.`,`s3-lifecycle|even if your bucket policy denies all actions for all principals, your S3 Lifecycle configuration still functions as normal.`,`s3-lifecycle|When you add a Lifecycle configuration to a bucket, the configuration rules apply to both existing objects and objects that you add later.`]}),t({id:`compliance-registry-022`,building:`compliance-registry`,bullets:[`1.3-S6`],d:1,stem:`A company wants every new object version in an Amazon S3 bucket to be protected from deletion for 180 days automatically, without anyone applying a lock to each object. Which solution meets this requirement with the LEAST effort?`,correct:[`Enable S3 Versioning and Object Lock with a default retention period of 180 days on the bucket`,`A retention period set on the bucket applies to all objects in the bucket automatically, and Object Lock needs versioning.`],wrong:[[`Apply an Object Lock legal hold to each object version by hand after it is uploaded to the bucket`,`This is a manual step for every object, and a legal hold has no retention period.`],[`Add an S3 Lifecycle expiration rule that acts on objects after 180 days`,`An expiration rule deletes objects and does not protect them from deletion.`],[`Enable S3 Versioning only and tell users not to delete object versions for 180 days`,`Versioning alone does not stop a user from deleting a version.`]],slot:1,evidence:[`s3-object-lock|Additionally, you can set a default retention period on an S3 bucket.`,`s3-object-lock|You can place a retention period explicitly on an individual object version or on a bucket's properties so that it applies to all objects in the bucket automatically.`,`s3-object-lock|Object Lock works only in buckets that have S3 Versioning enabled.`]}),t({id:`compliance-registry-023`,building:`compliance-registry`,bullets:[`1.3-S6`],d:3,stem:`A company uses S3 Object Lock for regulated records. Uploaders can choose a retention period for each object, and the compliance team wants to stop anyone from applying a period shorter than five years. The control must be enforced centrally without custom code. Which solution meets these requirements?`,correct:[`Add a bucket policy that uses the s3:object-lock-remaining-retention-days condition key to limit allowed retention periods`,`The condition key in a bucket policy restricts the minimum and maximum retention periods that users may set.`],wrong:[[`Set a five-year default retention period on the bucket and rely on it for every upload`,`An individual retention setting on an object version overrides the retention settings of the bucket, so a shorter period could still be set.`],[`Use governance mode for the retention setting so that users cannot change it`,`Governance mode lets users with special permissions alter the settings, and it does not limit the length of the period that users set.`],[`Attach a permissions boundary that denies the s3:BypassGovernanceRetention permission to uploaders`,`That permission relates to overriding governance-mode settings and does not set a minimum retention period.`]],slot:2,evidence:[`s3-object-lock|You may also restrict the minimum and maximum allowable retention periods with the s3:object-lock-remaining-retention-days condition key in the bucket policy.`,`s3-object-lock|When you PUT an object version that has an explicit individual retention mode and period in a bucket, the object version's individual Object Lock settings override any bucket property retention settings.`]}),e({id:`compliance-registry-024`,building:`compliance-registry`,bullets:[`1.3-S6`],d:3,stem:`A bucket holds regulated records. No user, including the root user, may delete or overwrite an object version during its retention period. The bucket must also never become publicly accessible, even if someone later attaches a permissive bucket policy. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Enable S3 Versioning and S3 Object Lock in compliance mode with a retention period`,`In compliance mode no user, including the root user, can overwrite or delete a protected object version.`],[`Turn on S3 Block Public Access for the bucket`,`Block Public Access settings override policies and permissions that would otherwise allow public access.`]],wrong:[[`Enable S3 Object Lock in governance mode with a retention period`,`In governance mode users with special permissions can alter lock settings or delete the object.`],[`Rely on the default behavior that new buckets do not allow public access`,`Users can later modify bucket policies or permissions to allow public access, so the default alone is not enough.`],[`Run an Amazon Macie sensitive data discovery job on the bucket every week`,`Macie reports on sensitive data and does not prevent deletion or public access.`]],slots:[0,4],evidence:[`s3-object-lock|In compliance mode, a protected object version can't be overwritten or deleted by any user, including the root user in your AWS account.`,`s3-object-lock|In governance mode, users can't overwrite or delete an object version or alter its lock settings unless they have special permissions.`,`s3-block-public-access|By default, new buckets, access points, and objects don't allow public access.`,`s3-block-public-access|However, users can modify bucket policies, access point policies, or object permissions to allow public access.`,`s3-block-public-access|S3 Block Public Access settings override these policies and permissions so that you can limit public access to these resources.`]}),t({id:`compliance-registry-025`,building:`compliance-registry`,bullets:[`1.3-S6`],d:2,stem:`A company stores user session items in an Amazon DynamoDB table. A policy says that each item expires 30 days after creation, and removal within a few days after that is acceptable. The company wants the deletion to happen automatically, without custom code and without consuming write capacity. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Enable time to live on the table and store an expiration timestamp in each item`,`DynamoDB TTL deletes expired items automatically, typically within a few days after expiration, without consuming write throughput.`],wrong:[[`Schedule an AWS Lambda function that scans the table and deletes the old items`,`This is custom code to maintain, and the delete requests consume write capacity.`],[`Switch the table to on-demand capacity mode so that old items are removed over time`,`The capacity mode controls how reads and writes are billed and does not delete any items.`],[`Create an S3 Lifecycle rule on the bucket that holds the table backups`,`A lifecycle rule acts on S3 objects and does not delete items from the live table.`]],slot:3,evidence:[`dynamodb-ttl|Time To Live (TTL) for DynamoDB is a cost-effective method for deleting items that are no longer relevant.`,`dynamodb-ttl|DynamoDB automatically deletes expired items within a few days of their expiration time, without consuming write throughput.`,`dynamodb-ttl|The timestamp must be stored as a Number data type in Unix epoch time format at the seconds granularity.`]}),t({id:`compliance-registry-026`,building:`compliance-registry`,bullets:[`1.3-S6`],d:2,stem:`A company keeps project files in an Amazon EFS file system. Files that have not been accessed for 30 days are still read a few times each quarter. They should move to a lower-cost storage class automatically, stay in the same file system, and need no code. Which solution meets these requirements MOST cost-effectively?`,correct:[`Configure EFS lifecycle management policies that transition files into the Infrequent Access storage class`,`Lifecycle management automatically transitions files between storage classes in place, and IA is cost-optimized for data accessed only a few times each quarter.`],wrong:[[`Copy the old files to Amazon S3 with AWS DataSync and expire them with an S3 Lifecycle rule`,`This moves the files out of the file system, and the requirement is that they stay in the same file system.`],[`Run a nightly script on an Amazon EC2 instance that finds old files and copies them to another file system`,`This is custom code that must be maintained, and EFS lifecycle management does the same without any code.`],[`Use an AWS Backup plan to move the live files of the file system to its cold storage tier`,`Backup cold storage holds backups and does not store the live files of the file system.`]],slot:0,evidence:[`efs-lifecycle|Use lifecycle management to automatically transition data between storage classes according to the lifecycle configuration for the file system.`,`efs-lifecycle|Transition into IA – Instructs lifecycle management when to move files in to the Infrequent Access (IA) storage class, which is cost-optimized for data that is accessed only a few times each quarter.`,`efs-lifecycle|Archive – Instructs lifecycle management when to move files from the Standard or IA storage class in to the Archive storage class, which is cost-optimized for data that is accessed only a few times each year or less.`]})],o=[t({id:`customs-house-001`,building:`customs-house`,bullets:[`1.2-K2`],d:1,tags:[`trap:gateway-vs-interface-endpoints`],stem:`Amazon EC2 instances in private subnets of a VPC copy large numbers of objects to Amazon S3 in the same Region. The traffic currently goes through a NAT gateway and the internet. The company wants the traffic to stay on the AWS network at the LOWEST cost, with no additional hourly charge for the connection. Which solution meets these requirements?`,correct:[`Create a gateway VPC endpoint for Amazon S3 and add it to the route tables of the private subnets`,`A gateway endpoint reaches Amazon S3 without an internet gateway or NAT device, and there is no additional charge for using it.`],wrong:[[`Create an interface VPC endpoint for Amazon S3 in each Availability Zone that has a private subnet`,`It keeps the traffic private, but interface endpoints are billed for hourly usage and data processing, so it is not the lowest cost.`],[`Move the instances to public subnets and give each instance a public IP address`,`AWS charges for all public IPv4 addresses, including those associated with running instances, so this adds a charge that the gateway endpoint does not, and it is not the lowest cost.`],[`Replace the NAT gateway with a larger NAT instance that has more network bandwidth`,`A NAT device still sends the traffic out through the internet, and it adds instances to run.`]],slot:0,evidence:[`vpce-gateway-s3|With a gateway endpoint, you can access Amazon S3 from your VPC, without requiring an internet gateway or NAT device for your VPC, and with no additional cost.`,`vpce-gateway-s3|After you create the gateway endpoint, you can add it as a target in your route table for traffic destined from your VPC to Amazon S3.`,`ec2-addressing|AWS charges for all public IPv4 addresses, including public IPv4 addresses associated with running instances and Elastic IP addresses.`,`vpce-interface|You are billed for hourly usage and data processing charges.`]}),t({id:`customs-house-002`,building:`customs-house`,bullets:[`1.2-S4`],d:1,stem:`A company has 200 remote employees who work from home. They need secure access from their laptops, from any location, to resources in a VPC. The company does not want to deploy and maintain VPN servers. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an AWS Client VPN endpoint and have employees connect with an OpenVPN-based client`,`Client VPN is a managed client-based VPN service for secure access from any location, so no VPN servers have to be run.`],wrong:[[`Create an AWS Site-to-Site VPN connection and configure a customer gateway for every employee's home`,`Site-to-Site VPN connects a whole remote network through a customer gateway device and is not meant for individual laptops.`],[`Order an AWS Direct Connect connection for each employee and attach it to the VPC`,`Direct Connect is a physical link from a network to an AWS location, and it is not a way to connect individual remote users.`],[`Install an OpenVPN server on Amazon EC2 instances in a public subnet and patch the instances`,`It works, but the company would deploy, scale and maintain the VPN servers itself.`]],slot:2,evidence:[`client-vpn|With Client VPN, you can access your resources from any location using an OpenVPN-based VPN client.`,`client-vpn|Managed service — Eliminates the operational burden of deploying and maintaining third-party remote access VPN solutions through complete AWS management.`]}),t({id:`customs-house-003`,building:`customs-house`,bullets:[`1.2-K2`],d:2,tags:[`trap:gateway-vs-interface-endpoints`],stem:`A company's data center is connected to a VPC with AWS Direct Connect. On-premises applications must reach Amazon S3 using private IP addresses in the VPC, and the traffic must not use the public internet. Which solution meets these requirements MOST simply?`,correct:[`Create an interface VPC endpoint for Amazon S3 and have the on-premises applications use it`,`Gateway endpoints do not allow access from on-premises networks, so an interface endpoint is the type to use for this access.`],wrong:[[`Create a gateway VPC endpoint for Amazon S3 and advertise it to the data center over the connection`,`Gateway endpoints do not allow access from on-premises networks.`],[`Route the on-premises requests to Amazon S3 through a NAT gateway in the VPC`,`A NAT gateway sends outbound traffic through the internet gateway, so the traffic would use the public internet.`],[`Add a bucket policy that allows the IP address range of the data center to read the bucket`,`A bucket policy controls who may read the bucket, but it does not change the network path to private IP addresses.`]],slot:1,evidence:[`vpce-gateway-s3|However, gateway endpoints do not allow access from on-premises networks, from peered VPCs in other AWS Regions, or through a transit gateway.`,`vpce-gateway-s3|For those scenarios, you must use an interface endpoint, which is available for an additional cost.`]}),t({id:`customs-house-004`,building:`customs-house`,bullets:[`1.2-S4`],d:2,tags:[`trap:direct-connect-vs-vpn`],stem:`A company must connect its headquarters network to a VPC with an encrypted IPsec connection. The company wants to use its existing internet connection and does not want to order a dedicated physical circuit. Which solution meets these requirements in the SIMPLEST way?`,correct:[`Create an AWS Site-to-Site VPN connection between a customer gateway device and the VPC`,`Site-to-Site VPN creates an IPsec VPN connection between the remote network and the VPC over the internet.`],wrong:[[`Order an AWS Direct Connect dedicated connection and attach it to the VPC`,`Direct Connect uses a dedicated physical connection, which the company does not want to order, and it is not encrypted by default.`],[`Create an AWS Client VPN endpoint and install the client on a server in the headquarters`,`Client VPN serves individual clients rather than linking an entire network to the VPC.`],[`Assign public IP addresses to the instances in the VPC and secure each one with a TLS certificate`,`It exposes the instances to the internet and does not create a connection between the two networks.`]],slot:3,evidence:[`connectivity-vpn|Amazon VPC provides the option of creating an IPsec VPN connection between your remote networks and Amazon VPC over the internet`,`s2s-vpn|VPN tunnel: An encrypted link where data can pass from the customer network to or from AWS.`,`dx-encryption|AWS Direct Connect does not encrypt your traffic that is in transit by default.`]}),t({id:`customs-house-005`,building:`customs-house`,bullets:[`1.2-K2`],d:2,tags:[`trap:peering-tgw-privatelink`],stem:`A company runs a software-as-a-service application on Amazon EC2 instances behind a Network Load Balancer. Hundreds of customers in their own AWS accounts and VPCs, some with overlapping CIDR ranges, must reach the application privately. The company does not want to open network-level access to the rest of its VPC. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create a VPC endpoint service for the load balancer and let each customer create an interface endpoint`,`PrivateLink lets consumers connect to a provider's endpoint service privately, and it suits VPCs with overlapping IP addresses.`],wrong:[[`Create a VPC peering connection between the company's VPC and the VPC of each customer`,`Peering cannot connect VPCs with overlapping CIDR blocks, and it opens network-level routing between the VPCs.`],[`Attach the company's VPC and every customer VPC to a shared AWS Transit Gateway with routes between them`,`It connects whole networks instead of one service, and it does not solve the overlapping CIDR ranges.`],[`Publish the application behind an internet-facing load balancer and protect it with AWS WAF`,`Customers would reach it over the public internet, but the requirement is private access.`]],slot:2,evidence:[`privatelink-concepts|Consumers create VPC endpoints to connect to endpoint services and resources that are hosted by providers.`,`privatelink-concepts|A service provider must specify a load balancer when creating an endpoint service.`,`connectivity-privatelink|Alternatively, AWS PrivateLink is a good solution when the VPCs have overlapped IP addresses.`,`peering-basics|You cannot create a VPC peering connection between VPCs that have matching or overlapping IPv4 or IPv6 CIDR blocks.`]}),t({id:`customs-house-006`,postGuide:[`vpn-large-bandwidth-tunnel`],building:`customs-house`,bullets:[`1.2-S4`],d:2,tags:[`trap:direct-connect-vs-vpn`],stem:`A media company moves several terabytes every day from its data center to AWS. The current VPN over the internet shows variable throughput and latency. The company wants a dedicated connection with a more consistent network experience that does not pass through internet service providers. Which solution meets these requirements BEST?`,correct:[`Provision an AWS Direct Connect connection and create a virtual interface to the VPC`,`Direct Connect links the network to an AWS location, bypassing internet service providers, with a more consistent experience than internet-based connections.`],wrong:[[`Add a second AWS Site-to-Site VPN connection and spread the traffic across both connections`,`Both VPN connections still run over the internet, so the variable throughput and latency remain.`],[`Create an AWS Client VPN endpoint and connect the data center servers as clients`,`Client VPN also runs over the internet and is built for individual users, not for a steady data center transfer.`],[`Place a larger customer gateway device in the data center and enable the Large Bandwidth Tunnel option`,`Higher tunnel bandwidth does not remove the internet path or give a more consistent network experience.`]],slot:0,evidence:[`connectivity-dx|Direct Connect can reduce network costs, increase bandwidth throughput, and provide a more consistent network experience than internet-based connections.`,`dx-what-is|bypassing internet service providers in your network path.`,`connectivity-vpn|Amazon VPC provides the option of creating an IPsec VPN connection between your remote networks and Amazon VPC over the internet`]}),t({id:`customs-house-007`,building:`customs-house`,bullets:[`1.2-K2`],d:2,stem:`Application servers in private subnets use an interface VPC endpoint to call Amazon Kinesis Data Streams. The calls time out. The endpoint network interfaces use only the default security group of the VPC, and the servers belong to a different security group. Which change will fix the problem with the LEAST effort?`,correct:[`Add a security group to the endpoint that allows inbound HTTPS from the servers' security group`,`The endpoint network interfaces are protected by security groups, which must allow the expected traffic from the resources in the VPC.`],wrong:[[`Add a route to the interface endpoint in the route tables of the private subnets`,`Interface endpoints are reached through their network interfaces and private IP addresses, so a route is not what blocks the calls.`],[`Attach an internet gateway to the VPC and give every server a public IP address for the Kinesis calls`,`The servers would no longer use the endpoint, and the traffic would go over the internet.`],[`Replace the interface endpoint with a gateway endpoint for Amazon Kinesis Data Streams`,`Gateway endpoints support only Amazon S3 and DynamoDB, so one cannot be created for this service.`]],slot:3,evidence:[`vpce-interface|Create a security group for the endpoint network interface that allows the expected traffic from the resources in your VPC.`,`vpce-interface|For example, to ensure that the AWS CLI can send HTTPS requests to the AWS service, the security group must allow inbound HTTPS traffic.`,`vpce-gateway|Gateway VPC endpoints provide reliable connectivity to Amazon S3 and DynamoDB without requiring an internet gateway or a NAT device for your VPC.`]}),t({id:`customs-house-008`,postGuide:[`direct-connect-400g`],building:`customs-house`,bullets:[`1.2-S4`],d:2,tags:[`trap:direct-connect-vs-vpn`],stem:`A company uses a 1 Gbps dedicated AWS Direct Connect connection between its data center and AWS. A regulation now requires the traffic to be encrypted in transit, and the company wants to keep using the Direct Connect connection. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create AWS Site-to-Site VPN tunnels on top of the Direct Connect connection`,`Direct Connect is not encrypted by default, and VPN tunnels on top of the connection provide an IPsec-encrypted private connection.`],wrong:[[`Enable MAC security (MACsec) on the existing 1 Gbps dedicated connection`,`MACsec is supported only on 10, 100 and 400 Gbps dedicated connections (at selected locations), so it is not available on a 1 Gbps connection.`],[`Keep the connection as it is, because the private path already encrypts all traffic`,`AWS states that Direct Connect does not encrypt traffic in transit by default; private is not the same as encrypted.`],[`Replace the connection with an AWS Client VPN endpoint for the data center servers`,`It gives up the Direct Connect connection that the company wants to keep, and Client VPN is built for individual users.`]],slot:1,evidence:[`dx-encryption|AWS Direct Connect does not encrypt your traffic that is in transit by default.`,`connectivity-dx|For connections of 1 Gbps or less, you can create VPN tunnels on top of the connection`,`dx-macsec|MACsec is supported on 10 Gbps , 100 Gbps, and 400 Gbps dedicated Direct Connect connections at selected points of presence.`,`dx-encryption|This combination provides an IPsec-encrypted private connection`]}),t({id:`customs-house-009`,building:`customs-house`,bullets:[`1.2-K2`],d:1,stem:`A government contractor's application uses the AWS SDK to call AWS services. A compliance rule requires the API calls to use endpoints that support FIPS 140. Which approach meets this requirement with the LEAST effort?`,correct:[`Configure the SDK to use FIPS endpoints by setting the AWS_USE_FIPS_ENDPOINT variable`,`Some services offer FIPS endpoints, and the SDKs let you choose them with a setting such as AWS_USE_FIPS_ENDPOINT.`],wrong:[[`Switch the SDK to dual-stack endpoints so that the calls use both IPv4 and IPv6`,`Dual-stack endpoints add IPv6 access; they do not make the endpoint support FIPS 140.`],[`Create gateway VPC endpoints for every AWS service that the application calls`,`Gateway endpoints exist only for Amazon S3 and DynamoDB, and they are not FIPS endpoints.`],[`Keep the default Regional endpoints and add a security group that allows only HTTPS to them`,`The default endpoints are standard endpoints, and a security group rule does not change which endpoint is used.`]],slot:0,evidence:[`service-endpoints|Some AWS services offer endpoints that support Federal Information Processing Standard (FIPS) 140 in some Regions.`,`service-endpoints|Set the AWS_USE_FIPS_ENDPOINT environment variable to true`,`service-endpoints|Some AWS services offer dual stack endpoints, so that you can access them using either IPv4 or IPv6 requests.`]}),t({id:`customs-house-010`,postGuide:[`vpn-large-bandwidth-tunnel`],building:`customs-house`,bullets:[`1.2-S4`],d:2,stem:`A company has an AWS Site-to-Site VPN connection to its data center. The network engineer configured only one of the two tunnels on the on-premises firewall. When AWS performed maintenance on that tunnel, connectivity to the VPC dropped. Which action prevents this with the LEAST effort?`,correct:[`Configure the second tunnel of the VPN connection on the on-premises firewall as well`,`Traffic moves automatically to the available tunnel only if both tunnels are configured, which is why AWS says to configure both.`],wrong:[[`Order an AWS Direct Connect connection and remove the VPN connection`,`It is a new physical circuit and a larger project than finishing the configuration of the tunnels that already exist.`],[`Turn on the Large Bandwidth Tunnel option for the tunnel that is already configured`,`It raises the bandwidth per tunnel but does not give a second path when that tunnel is down.`],[`Create a new VPN connection that uses a second virtual private gateway for the same VPC`,`The existing connection already has two tunnels, so the missing piece is configuration, not another gateway.`]],slot:2,evidence:[`vpn-tunnels|It is important to configure both tunnels for redundancy.`,`vpn-tunnels|When one tunnel becomes unavailable (for example, down for maintenance), network traffic is automatically routed to the available tunnel for that specific Site-to-Site VPN connection.`,`s2s-vpn|Each VPN connection includes two VPN tunnels which you can simultaneously use for high availability.`]}),e({id:`customs-house-011`,building:`customs-house`,bullets:[`1.2-K2`],d:3,tags:[`trap:gateway-vs-interface-endpoints`],stem:`A company stores data in Amazon S3 in us-east-1. Amazon EC2 instances in private subnets of a VPC in us-east-1 and servers in an on-premises data center, connected to the VPC by AWS Site-to-Site VPN, must both reach Amazon S3 privately. The company wants the MOST cost-effective design. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a gateway VPC endpoint for Amazon S3 and add it to the route tables of the private subnets`,`A gateway endpoint gives the instances private access to Amazon S3 with no additional charge.`],[`Create an interface VPC endpoint for Amazon S3 and have the on-premises servers use it through the VPN`,`On-premises networks cannot use a gateway endpoint, so they need an interface endpoint.`]],wrong:[[`Use the interface endpoint for the instances in the VPC as well and skip the gateway endpoint`,`It works, but interface endpoints are billed for hourly usage and data processing, whereas the gateway endpoint has no additional charge.`],[`Advertise the prefix list of the gateway endpoint to the data center over the VPN connection`,`Gateway endpoints do not allow access from on-premises networks.`],[`Add a NAT gateway in a public subnet and route the instances and the servers through it`,`It sends the Amazon S3 traffic out through the internet gateway instead of keeping it private.`]],slots:[0,3],evidence:[`vpce-gateway-s3|With a gateway endpoint, you can access Amazon S3 from your VPC, without requiring an internet gateway or NAT device for your VPC, and with no additional cost.`,`vpce-gateway-s3|However, gateway endpoints do not allow access from on-premises networks, from peered VPCs in other AWS Regions, or through a transit gateway.`,`vpce-interface|You are billed for hourly usage and data processing charges.`]}),t({id:`customs-house-012`,building:`customs-house`,bullets:[`1.2-S4`],d:3,tags:[`trap:direct-connect-vs-vpn`],stem:`A company runs a critical workload that depends on its AWS Direct Connect connectivity. The company must protect against the failure of a single device and of a whole Direct Connect location, and it wants the MOST highly available design. Which design meets these requirements?`,correct:[`Order separate connections that end on separate devices in more than one location`,`The maximum resiliency model uses separate connections on separate devices in more than one location for critical workloads.`],wrong:[[`Order two connections that end on separate devices in the same Direct Connect location`,`It survives a device failure, but a failure of that location would still stop both connections.`],[`Order one connection and group it with others in a link aggregation group at the same endpoint`,`A link aggregation group aggregates connections at a single endpoint, so it does not protect against a location failure.`],[`Order one connection with the highest port speed available at a single Direct Connect location`,`A faster port adds bandwidth, but the single device and the single location remain points of failure.`]],slot:3,evidence:[`dx-resiliency|You can achieve maximum resiliency for critical workloads by using separate connections that terminate on separate devices in more than one location`,`dx-resiliency|Development and test: This model provides you a way to achieve development and test resiliency for non-critical workloads, by using separate connections that terminate on separate devices in one location.`,`connectivity-dx|For dedicated connections, you can also use a link aggregation group (LAG) to aggregate multiple connections at a single AWS Direct Connect endpoint.`]}),t({id:`customs-house-013`,building:`customs-house`,bullets:[`1.2-K2`],d:3,stem:`A company stores regulated documents in an Amazon S3 bucket. Compliance requires that the bucket can be accessed only by Amazon EC2 instances in one VPC through the gateway endpoint for Amazon S3, and not from the internet. The instances have private IP addresses. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Add a bucket policy that denies requests that do not come through the gateway endpoint (aws:sourceVpce)`,`A bucket policy can deny requests that do not use a specific endpoint, which limits access to the VPC endpoint.`],wrong:[[`Add a bucket policy that allows only the private IP addresses of the instances, using the aws:SourceIp condition key`,`The aws:SourceIp condition cannot be used for requests to Amazon S3 that traverse a VPC endpoint.`],[`Attach an endpoint policy to the gateway endpoint that allows access to only this bucket`,`An endpoint policy limits what can be reached through the endpoint, but requests from the internet would still reach the bucket.`],[`Turn on the S3 Block Public Access settings for the bucket and keep its default policy`,`Block Public Access prevents public grants, but it does not limit access to one VPC endpoint.`]],slot:1,evidence:[`vpce-gateway-s3|You can use bucket policies to control access to buckets from specific endpoints, VPCs, IP address ranges, and AWS accounts.`,`vpce-gateway-s3|You can create a bucket policy that restricts access to a specific endpoint by using the aws:sourceVpce condition key.`,`vpce-gateway-s3|You can't use the aws:SourceIp condition in an identity policy or a bucket policy for requests to Amazon S3 that traverse a VPC endpoint.`,`vpce-policies|An endpoint policy does not override or replace identity-based policies or resource-based policies.`]}),e({id:`customs-house-014`,building:`customs-house`,bullets:[`1.2-S4`],d:3,tags:[`trap:peering-tgw-privatelink`],stem:`A company has 12 VPCs in one Region and a data center. All VPCs must reach the data center over AWS Site-to-Site VPN, and the company wants to avoid creating a separate VPN connection for each VPC. Which TWO actions meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`Create a transit gateway and attach each of the 12 VPCs to it`,`A transit gateway is a transit hub that interconnects VPCs and on-premises networks.`],[`Create the Site-to-Site VPN connection on the transit gateway instead of on a virtual private gateway`,`A VPN connection can end on a transit gateway, so one connection serves all attached VPCs.`]],wrong:[[`Attach one virtual private gateway to all 12 VPCs and create one VPN connection on it`,`A virtual private gateway can be attached to a single VPC.`],[`Peer the 11 other VPCs with the one VPC that has the VPN connection and route through it`,`VPC peering does not support transitive peering relationships, so traffic cannot pass through the VPC to the data center.`],[`Create an interface VPC endpoint in each VPC that points to the data center`,`Interface endpoints reach AWS services and endpoint services, not an on-premises network.`]],slots:[1,3],evidence:[`s2s-vpn-how|Transit gateway A transit gateway is a transit hub that you can use to interconnect your VPCs and your on-premises networks.`,`s2s-vpn-how|A Site-to-Site VPN connection consists of the following components: A virtual private gateway or a transit gateway A customer gateway device A customer gateway`,`s2s-vpn|Virtual private gateway: A virtual private gateway is the VPN endpoint on the Amazon side of your Site-to-Site VPN connection that can be attached to a single VPC.`,`peering-basics|VPC peering does not support transitive peering relationships.`]}),e({id:`customs-house-015`,building:`customs-house`,bullets:[`1.2-S4`],d:2,stem:`A company has an AWS Direct Connect connection to its data center. On-premises servers must reach Amazon EC2 instances in a single VPC by private IP addresses and must also reach Amazon S3, all over the Direct Connect connection. The VPC does not use a transit gateway, has no interface endpoints, and the company does not want to create any. Which TWO virtual interfaces meet these requirements with the LEAST complexity? (Choose two.)`,correct:[[`A private virtual interface for access to the VPC`,`A private virtual interface enables access to a VPC by using private IP addresses.`],[`A public virtual interface for access to Amazon S3`,`A public virtual interface enables access to public AWS services such as Amazon S3.`]],wrong:[[`A transit virtual interface for access to the VPC`,`A transit virtual interface is for Transit Gateways associated with Direct Connect gateways, and this VPC has none.`],[`A second private virtual interface for access to Amazon S3`,`A private virtual interface reaches the VPC; Amazon S3 over it would need an interface endpoint, which this design does not have, and a second private virtual interface adds nothing.`],[`A Site-to-Site VPN tunnel on the Direct Connect connection for access to the VPC`,`It encrypts the traffic but does not provide the virtual interfaces that give access to the VPC and Amazon S3.`]],slots:[0,4],evidence:[`dx-what-is|A private virtual interface enables access to your VPC.`,`dx-what-is|A public virtual interface enables access to public services, such as Amazon S3.`,`dx-what-is|Transit virtual interface This type of interface is used to access one or more Amazon VPC Transit Gateways associated with Direct Connect gateways.`]}),t({id:`customs-house-016`,building:`customs-house`,bullets:[`1.2-K2`],d:1,tags:[`mock-reserve`],stem:`AWS Lambda functions in private subnets of a VPC reach Amazon DynamoDB through a gateway VPC endpoint that uses the default endpoint policy. The security team wants traffic over this endpoint to reach only the orders table, for every workload in the VPC, without editing each workload's IAM role. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Attach a custom endpoint policy to the gateway endpoint that allows access only to the orders table`,`An endpoint policy controls which principals can use the endpoint to access which resources, and the default policy allows full access.`],wrong:[[`Add outbound rules to the security groups of the functions that allow traffic only to the orders table`,`Security group rules match protocol, port and the service prefix list for the whole service, not individual DynamoDB tables.`],[`Add network ACL rules to the private subnets that allow traffic only to the orders table`,`Network ACL rules match IP address ranges and ports, not individual DynamoDB tables.`],[`Replace the gateway endpoint with an interface endpoint and keep its default endpoint policy`,`The default endpoint policy allows full access, so every table stays reachable, and interface endpoints add hourly and data processing charges.`]],slot:2,evidence:[`vpce-policies|An endpoint policy is a resource-based policy that you attach to a VPC endpoint to control which AWS principals can use the endpoint to access an AWS service.`,`vpce-gateway-ddb|For Policy, select Full access to allow all operations by all principals on all resources over the VPC endpoint.`,`vpce-gateway-ddb|Otherwise, select Custom to attach a VPC endpoint policy that controls the permissions that principals have to perform actions on resources over the VPC endpoint.`,`vpce-interface|You are billed for hourly usage and data processing charges.`]}),t({id:`customs-house-017`,building:`customs-house`,bullets:[`1.2-S4`],d:2,tags:[`mock-reserve`,`trap:direct-connect-vs-vpn`],stem:`A company has a 100 Gbps dedicated AWS Direct Connect connection. The security team wants the data encrypted between the corporate data center and the Direct Connect location without creating VPN tunnels. Which solution meets this requirement with the LEAST effort?`,correct:[`Use a Direct Connect connection that supports MACsec and enable MAC security on it`,`Connections that support MACsec can encrypt data from the corporate data center to the Direct Connect location.`],wrong:[[`Rely on the dedicated connection, because Direct Connect encrypts traffic by default`,`AWS states that Direct Connect does not encrypt traffic in transit by default.`],[`Create an AWS Client VPN endpoint and connect the data center router to it`,`Client VPN is for individual users and builds VPN sessions, which the company wants to avoid.`],[`Create AWS Site-to-Site VPN tunnels on top of the Direct Connect connection`,`It encrypts the traffic, but it creates the VPN tunnels that the company does not want.`]],slot:1,evidence:[`dx-encryption|You can use Direct Connect connections that support MACsec to encrypt your data from your corporate data center to the Direct Connect location.`,`connectivity-dx|For dedicated connections of 10 or 100 Gbps, you can use MAC security (MACsec) as an encryption option.`,`dx-encryption|AWS Direct Connect does not encrypt your traffic that is in transit by default.`]}),e({id:`customs-house-018`,building:`customs-house`,bullets:[`1.2-S4`],d:2,tags:[`mock-reserve`],stem:`A company has one AWS Site-to-Site VPN connection to a virtual private gateway, with a single customer gateway device in its data center. A failure of that device would cut connectivity to the VPC. Which TWO actions will MOST effectively protect against this failure? (Choose two.)`,correct:[[`Add a second customer gateway device in the data center`,`A second device keeps traffic flowing if the first one fails or needs maintenance.`],[`Create a second Site-to-Site VPN connection that uses the same virtual private gateway and the new customer gateway`,`A second VPN connection through the second device protects against loss of connectivity if one device becomes unavailable.`]],wrong:[[`Configure both tunnels of the existing connection with different pre-shared keys`,`The connection already has two tunnels, but both end on the same customer gateway device, which remains a single point of failure.`],[`Create a Client VPN endpoint for the data center network`,`Client VPN connects individual clients and does not give the network a second path.`],[`Add a NAT gateway in each Availability Zone of the VPC`,`A NAT gateway gives private subnets outbound internet access and does not add a path to the data center.`]],slots:[2,4],evidence:[`vpn-redundant|To protect against a loss of connectivity in case your customer gateway device becomes unavailable, you can set up a second Site-to-Site VPN connection to your VPC and virtual private gateway by adding a second customer gateway device.`,`vpn-redundant|Set up a second Site-to-Site VPN connection by using the same virtual private gateway and creating a new customer gateway.`,`vpn-tunnels|Each Site-to-Site VPN connection has two tunnels, with each tunnel using a unique public IP address.`]})],s=[t({id:`embassy-row-001`,building:`embassy-row`,bullets:[`1.1-K1`],d:1,stem:`A company runs dozens of AWS accounts for different teams. The company wants to group the accounts by environment, apply governance policies to each group, and pay with a single payment method. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an organization in AWS Organizations and place the accounts in organizational units`,`AWS Organizations lets you group accounts, apply policies for governance, and use a single payment method for all of the accounts.`],wrong:[[`Create an IAM user group for each team in one account and attach a billing policy to each group`,`IAM groups exist inside a single account, so they cannot group separate accounts, apply governance to them, or combine their payment.`],[`Share the resources of each account with the other accounts by using AWS Resource Access Manager`,`AWS RAM shares resources across accounts but does not group accounts, apply governance policies, or consolidate payment.`],[`Send AWS CloudTrail events from every account to one Amazon S3 bucket in a logging account`,`A central log helps auditing but does not group the accounts, apply policies to them, or simplify billing.`]],slot:0,evidence:[`orgs-intro|Using Organizations, you can create accounts and allocate resources, group accounts to organize your workflows, apply policies for governance, and simplify billing by using a single payment method for all of your accounts.`]}),t({id:`embassy-row-002`,building:`embassy-row`,bullets:[`1.1-K1`],d:1,stem:`A company runs its production application and its development and test environments in a single AWS account. An auditor asks the company to isolate production workloads from development and test workloads as strongly as possible. Which approach provides the MOST isolation?`,correct:[`Move the development and test workloads into separate AWS accounts that are grouped in an organization`,`AWS describes accounts as a hard boundary and recommends account-level separation for isolating production from development and test workloads.`],wrong:[[`Place the development workloads in separate subnets of the production VPC and add network ACL rules between them`,`Subnets and network ACLs separate traffic inside one account, but the workloads still sit inside the same account boundary.`],[`Create one IAM user group per environment in the same account and attach a separate permissions policy to each group`,`Groups separate who can do what, but every environment still runs inside the same account boundary.`],[`Tag every production resource and write IAM policies that deny access to developers who work on other resources`,`Tags and policy conditions are controls inside one account; they are not the hard boundary that separate accounts provide.`]],slot:1,evidence:[`sec-account-separation|In AWS, accounts are a hard boundary.`,`sec-account-separation|For example, account-level separation is strongly recommended for isolating production workloads from development and test workloads.`]}),t({id:`embassy-row-003`,building:`embassy-row`,bullets:[`1.1-K1`],d:2,stem:`A central networking team owns Amazon VPC subnets in a shared-services account of an AWS Organizations organization. Application teams in 40 other member accounts must launch resources into those subnets. The company does not want duplicate subnets in every account. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Share the subnets with the organization by using AWS Resource Access Manager (AWS RAM)`,`AWS RAM lets the networking team create the subnets once and share them with the accounts in the organization, so no duplicate subnets are provisioned.`],wrong:[[`Create a VPC peering connection from the VPC of each member account to the shared-services VPC`,`Peering routes traffic between networks, but it does not let a member account launch its resources into the other account subnets.`],[`Attach a service control policy to the organization root that allows access to the shared-services subnets`,`SCPs do not grant permissions; they only set limits on what the accounts can do.`],[`Create an IAM role in the shared-services account for each team and have the teams launch resources through it`,`The resources would be created in the shared-services account instead of the team accounts, and every team needs its own role to maintain.`]],slot:2,evidence:[`orgs-intro|Ensure that application resources are created on your Amazon Virtual Private Cloud (Amazon VPC) subnets by centrally defining them once and sharing them across your organization using AWS Resource Access Manager (AWS RAM).`,`ram-what-is|This eliminates the need to provision duplicate resources in every account, which reduces operational overhead.`]}),t({id:`embassy-row-004`,building:`embassy-row`,bullets:[`1.1-K1`,`1.1-S5`],d:2,tags:[`placement-eligible`,`trap:iam-roles-vs-resource-policies`],stem:`A shared-services account owns an Amazon S3 bucket that holds static assets, such as images and style sheets, for the websites in every account of the company organization. Every current and future account must be able to read the bucket. The security team does not want to edit the bucket policy whenever an account is added or removed. Which solution meets these requirements with the LEAST ongoing effort?`,correct:[`Add a bucket policy statement that allows s3:GetObject and uses the aws:PrincipalOrgID condition key with the organization ID`,`Policies that use aws:PrincipalOrgID automatically include the correct accounts as accounts are added and removed, so the bucket policy needs no manual updates.`],wrong:[[`Add a bucket policy statement that lists the account ID of every member account in the organization as a principal of the bucket`,`It works today, but every added or removed account requires an edit to the policy, which is the ongoing effort the team wants to avoid.`],[`Create an IAM user in each member account and add every user ARN to the principals of the bucket policy`,`Each new account needs a new user and another edit of the policy, and long-term user credentials add more to manage.`],[`Attach a service control policy to the organization root that allows s3:GetObject on the bucket`,`SCPs do not grant permissions, so the bucket would still need a policy that allows the access.`]],slot:3,evidence:[`iam-global-condition-keys|When you add and remove accounts, policies that include the aws:PrincipalOrgID key automatically include the correct accounts and don't require manual updating.`,`orgs-scps|SCPs do not grant permissions to the IAM users and IAM roles in your organization.`]}),e({id:`embassy-row-005`,building:`embassy-row`,bullets:[`1.1-K1`,`1.1-S3`,`1.1-S5`],d:2,tags:[`trap:iam-roles-vs-resource-policies`],stem:`A company owns an Amazon S3 bucket in account A. Engineers in account B must read objects from the bucket. Which TWO approaches can give the engineers cross-account access? (Choose two.)`,correct:[[`Attach a resource-based policy to the bucket that names the principals of account B`,`A resource-based policy specifies which principal can access the resource, so it can grant access directly to principals in another account.`],[`Create a role in account A that trusts account B and let the engineers assume it`,`A cross-account role has a trust policy that allows IAM principals in another account to assume it, so the role works as a proxy.`]],wrong:[[`Add a Principal element for account B to an identity-based policy of an IAM group in account A`,`The Principal element cannot be used in an identity-based policy, so such a policy cannot name another account.`],[`Attach a service control policy to account A that allows s3:GetObject for account B`,`SCPs do not grant permissions to anyone; they only set the maximum available permissions.`],[`Attach a permissions boundary to the bucket that lists the account B engineers`,`A permissions boundary applies to IAM users and roles, not to a bucket, and it sets a maximum without granting access.`]],slots:[0,3],evidence:[`iam-cross-account|To do this, you can attach a resource policy directly to the resource that you want to share, or use a role as a proxy.`,`s3-bucket-policies|A bucket policy is a resource-based policy that you can use to grant access permissions to your Amazon S3 bucket and the objects in it.`,`iam-el-principal|You cannot use the Principal element in an identity-based policy.`,`orgs-scps|SCPs do not grant permissions to the IAM users and IAM roles in your organization.`]}),t({id:`embassy-row-006`,building:`embassy-row`,bullets:[`1.1-S3`],d:1,stem:`A reporting application in one AWS account must read data in a second AWS account that the company owns. The security team does not want long-term access keys stored in the application. Which solution BEST meets this requirement?`,correct:[`Create an IAM role in the second account and have the application assume it to get temporary credentials`,`The role has no long-term credentials; assuming it returns temporary security credentials that are generated dynamically when requested.`],wrong:[[`Create an IAM user in the second account and store its access keys in the configuration file of the application`,`Access keys are long-term credentials that would be embedded in the application, which the team wants to avoid.`],[`Create an IAM user in the second account and rotate its access keys by hand every quarter`,`Rotation shortens the exposure, but the application still depends on long-term access keys that someone must distribute.`],[`Use the root user access keys of the second account and keep them in an encrypted file`,`Root user keys are long-term credentials, so the application would still hold access keys.`]],slot:0,evidence:[`iam-temp-creds|You do not have to distribute or embed long-term AWS security credentials with an application.`,`iam-temp-creds|Temporary security credentials are not stored with the user but are generated dynamically and provided to the user when requested.`,`iam-roles|a role does not have standard long-term credentials such as a password or access keys associated with it.`]}),t({id:`embassy-row-007`,building:`embassy-row`,bullets:[`1.1-K1`,`1.1-S3`],d:2,stem:`A company has a security account and 12 workload accounts. Auditors sign in to the security account and need temporary read-only access to resources in the workload accounts. The company does not want to create and manage separate IAM users for the auditors in every workload account. Which solution meets these requirements MOST securely?`,correct:[`Create a read-only role in each workload account whose trust policy names the security account, and let the auditors assume it`,`Auditors keep one identity in the security account and switch to the role for temporary access to only the permissions that the role defines.`],wrong:[[`Create an IAM user in every workload account for each auditor and send the initial sign-in details to every auditor in an encrypted email message`,`It creates the duplicate identities and credentials that the company wants to avoid, and shared sign-in details weaken security.`],[`Allow anonymous read access to the resources and limit it with a condition on the office IP address range`,`Anonymous access exposes the resources to everyone who matches the condition and does not tie access to authenticated auditors.`],[`Attach a service control policy to the security account that allows read access to the workload accounts`,`SCPs do not grant permissions, and a policy in the security account cannot give access to resources in another account.`]],slot:1,evidence:[`iam-account-switch|Although you could create separate identities (and passwords) for users who work in both accounts, managing credentials for multiple accounts makes identity management difficult.`,`iam-account-switch|In the role, the administrator defines a trust policy that specifies the development account as a Principal, meaning that authorized users from the development account can use the UpdateApp role.`]}),t({id:`embassy-row-008`,building:`embassy-row`,bullets:[`1.1-S3`],d:2,stem:`A company hires a third-party monitoring vendor whose software must read configuration data in the company AWS account. The vendor serves many customers from its own AWS account. The company wants to prevent another customer of the vendor from tricking the vendor into using the company role. Which solution meets this requirement MOST effectively?`,correct:[`Create a cross-account role whose trust policy requires a unique external ID that the vendor must supply when assuming the role`,`The external ID is the mechanism AWS provides to prevent the confused deputy problem when a third party assumes a role in your account.`],wrong:[[`Create a cross-account role that trusts the whole vendor account and give the vendor only the ARN of that role for use in its software`,`Trusting the whole vendor account with no external ID does not stop another customer of the vendor from causing the vendor to use the role.`],[`Create an IAM user for the vendor and email its access keys to the vendor security contact`,`Access keys are long-term credentials, and sharing them does not address the risk of another customer misusing the vendor.`],[`Attach a service control policy to the company account that names the vendor account`,`SCPs do not grant permissions and do not stop the vendor from being tricked into using the role.`]],slot:2,evidence:[`iam-third-party|The primary function of the external ID is to address and prevent The confused deputy problem.`,`iam-third-party|You should assign a unique external ID to each customer and instruct them to add the external ID to their role's trust policy.`]}),e({id:`embassy-row-009`,building:`embassy-row`,bullets:[`1.1-S3`],d:2,stem:`A company has a development account and a production account. Members of the Developers IAM group in the development account must be able to update objects in an Amazon S3 bucket in the production account by using temporary credentials. Which TWO steps are required? (Choose two.)`,correct:[[`In the production account, create a role with permissions for the bucket and a trust policy that names the development account`,`The trust policy lets principals of the trusted account use the role, and the permissions policy defines what the role may do in the bucket.`],[`In the development account, attach a policy to the Developers group that allows sts:AssumeRole on the role ARN`,`Users in the trusted account must also be granted permission to assume the role through the sts:AssumeRole action.`]],wrong:[[`In the production account, add the Developers group as a principal in the permissions policy of the role`,`A user group cannot be identified as a principal, and the permissions policy of a role defines what the role can do rather than who can assume it.`],[`In the development account, create access keys for the production role and give them to each developer`,`A role has no standard long-term credentials such as access keys; it provides temporary credentials when it is assumed.`],[`In the production account, attach a service control policy that allows the Developers group to assume the role`,`SCPs do not grant permissions, so they cannot give the group the ability to assume the role.`]],slots:[1,4],evidence:[`iam-cross-account-role|To do this, the administrator attaches a policy to the user or a group that grants permission for the sts:AssumeRole action.`,`iam-account-switch|In the role, the administrator defines a trust policy that specifies the development account as a Principal, meaning that authorized users from the development account can use the UpdateApp role.`,`iam-el-principal|You cannot identify a user group as a principal in a policy`]}),t({id:`embassy-row-010`,building:`embassy-row`,bullets:[`1.1-S3`],d:2,stem:`A developer signs in to the AWS Management Console as an IAM user whose policy allows only Amazon S3 read access. The developer then switches to a role in the same account that allows only Amazon EC2 read access. Which statement BEST describes the developer permissions while the role is active?`,correct:[`Only the Amazon EC2 read permissions of the role apply, and the user S3 read permissions are set aside until the developer exits the role`,`Only one set of permissions is active at a time; switching to a role temporarily sets aside the original user permissions.`],wrong:[[`The developer has both Amazon S3 read and Amazon EC2 read permissions because the two sets are combined`,`The permissions of the user and of a role that the user switches to are not cumulative, so the sets are not combined.`],[`The developer keeps only the Amazon S3 read permissions because the permissions of the IAM user always take precedence over the permissions of a role`,`While the role is active the user permissions are set aside, so they do not take precedence over the role permissions.`],[`The developer has no permissions until an administrator attaches the role to the group of the IAM user`,`Once the user is allowed to switch, the role permissions apply as soon as the switch succeeds; no attachment to a group is involved.`]],slot:3,evidence:[`iam-switch-role|The permissions of your user and any roles that you switch to aren't cumulative.`,`iam-switch-role|Only one set of permissions is active at a time.`]}),t({id:`embassy-row-011`,building:`embassy-row`,bullets:[`1.1-S3`],d:3,stem:`A batch job runs under an IAM role in account A. The job uses the credentials of that role to assume a role in account B, whose maximum session duration is set to 12 hours. The job needs about three hours, but its credentials stop working after one hour. Which statement explains this behavior?`,correct:[`Using the credentials of one role to assume another role is role chaining, which limits the session to one hour`,`AWS limits a chained session to one hour, regardless of the maximum session duration set on the individual roles.`],wrong:[[`The trust policy of the role in account B must include an external ID before it can issue longer sessions`,`An external ID is a condition for third-party access and does not change how long a chained session lasts.`],[`AWS ignores the maximum session duration of every role that is assumed from a different AWS account`,`The cause is role chaining; the maximum session duration is not ignored for cross-account roles in general.`],[`Roles can never issue credentials that last longer than one hour, so the job must use IAM user access keys`,`A role can be configured with a maximum session duration; the one-hour limit comes from role chaining.`]],slot:0,evidence:[`iam-switch-role|Using the credentials from one role to assume a different role is called role chaining. When you use role chaining, the session duration is limited to one hour, regardless of the maximum session duration setting configured for individual roles.`]}),t({id:`embassy-row-012`,building:`embassy-row`,bullets:[`1.1-K1`,`1.1-S3`],d:2,stem:`A developer in account A gets an AccessDenied error when calling sts:AssumeRole for a role in account B. The trust policy of the role names account A as the principal, and the permissions policy of the role allows the needed Amazon S3 actions. The IAM user of the developer has an identity-based policy that allows only Amazon S3 actions. Which change fixes the problem with the LEAST privilege?`,correct:[`Add a statement to the identity-based policy of the developer that allows sts:AssumeRole on the role ARN`,`Users in the trusted account must be granted permission to assume the role; the trust policy is only one half of the permissions.`],wrong:[[`Add s3:* with a Resource of * to the permissions policy of the role in account B`,`The call fails before any S3 action is attempted, so broader S3 permissions do not fix it and they widen access.`],[`Attach a service control policy to account A that allows sts:AssumeRole for all roles`,`SCPs do not grant permissions, and allowing all roles would be broader than the single role the developer needs.`],[`Replace the principal in the trust policy with the root user of account B so the role trusts its own account`,`The developer is in account A, so trusting only account B removes the access that the trust policy is meant to give.`]],slot:1,evidence:[`iam-cross-account-role|You must also give individual users in the trusted account permissions to switch to the role in the console, or assume the role programmatically.`,`iam-roles|The trust policy is attached to the role in the trusting account, and is one-half of the permissions.`]}),t({id:`embassy-row-013`,building:`embassy-row`,bullets:[`1.1-S3`,`1.1-S5`],d:3,tags:[`trap:iam-roles-vs-resource-policies`],stem:`An Amazon EC2 application in account A copies objects from an Amazon S3 bucket in account B into an S3 bucket in account A during the same job. The application must keep using the permissions of its own instance role in account A for the destination bucket. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Add a bucket policy to the source bucket that names the instance role of account A, and allow s3:GetObject in the identity-based policy of the role`,`With a resource-based policy the principal keeps its permissions in its own account, which suits copying information to or from the shared resource.`],wrong:[[`Create a role in account B with s3:GetObject on the source bucket and have the application assume that role for the whole copy job, including the writes`,`After the application assumes the role it gives up its account A permissions, so it could no longer write to the destination bucket.`],[`Create an IAM user in account B, store its access keys on the instance, and allow the user to read the source bucket`,`It adds long-term access keys to manage on the instance, which is more overhead than using the instance role.`],[`Make the source bucket public and read it with unsigned requests from the application`,`Every object would be exposed to anyone, so it is not a secure way to share data between two accounts.`]],slot:2,evidence:[`iam-cross-account|When an account accesses a resource through another account using a resource-based policy, the principal still works in the trusted account and does not have to give up their permissions to receive the role permissions.`,`iam-cross-account|This is useful for tasks such as copying information to or from the shared resource in the other account.`,`iam-cross-account-eval|You must also attach an identity-based policy to the identity that acts as the principal in the request.`]}),t({id:`embassy-row-014`,building:`embassy-row`,bullets:[`1.1-S3`,`1.1-S5`],d:3,tags:[`placement-eligible`,`trap:iam-roles-vs-resource-policies`],stem:`A company serves a static website from an Amazon S3 bucket behind Amazon CloudFront in a production account. A CI/CD pipeline in a separate tooling account must write new site files to the bucket and perform several other actions in the production account on each release. The company wants to manage the permissions of the pipeline in one place in the production account and forbids long-term access keys. Which solution meets these requirements MOST securely?`,correct:[`Create a role in the production account that trusts the pipeline role in the tooling account and grants all the release permissions`,`A cross-account role centralizes permission management across multiple services and gives the pipeline temporary credentials instead of access keys.`],wrong:[[`Add a bucket policy that names the pipeline role in the tooling account and allows s3:PutObject on the site bucket for each release of the website`,`A bucket policy covers only the bucket, so it cannot centralize the other production-account permissions that the pipeline needs.`],[`Create an IAM user in the production account for the pipeline and keep its access keys in the pipeline secrets`,`Access keys are long-term credentials, which the company forbids, and the user adds a credential to rotate.`],[`Attach a service control policy to the tooling account that allows writes to the production bucket`,`SCPs do not grant permissions and cannot give access to resources in another account.`]],slot:3,evidence:[`iam-cross-account|Not all AWS services support resource-based policies. For these services, you can use cross-account IAM roles to centralize permission management when providing cross-account access to multiple services.`,`iam-temp-creds|You do not have to distribute or embed long-term AWS security credentials with an application.`]}),t({id:`embassy-row-015`,building:`embassy-row`,bullets:[`1.1-S4`],d:1,stem:`A company is adopting a multi-account strategy and has no landing zone yet. Which solution is the FASTEST way to set up a governed multi-account environment that follows prescriptive best practices?`,correct:[`Set up a landing zone by using AWS Control Tower`,`Control Tower sets up and governs a multi-account environment that follows prescriptive best practices.`],wrong:[[`Create each account by hand in AWS Organizations and configure the baseline of every account separately`,`It can work, but it is slow and has no built-in best-practice setup or ongoing governance controls.`],[`Share a baseline VPC with every account by using AWS Resource Access Manager and tag the accounts`,`AWS RAM shares resources; it does not create accounts, apply best practices, or govern them.`],[`Enable AWS IAM Identity Center and assign permission sets to the accounts that already exist`,`IAM Identity Center manages workforce access to accounts but does not set up a governed multi-account environment.`]],slot:0,evidence:[`control-tower|AWS Control Tower offers a straightforward way to set up and govern an AWS multi-account environment, following prescriptive best practices.`]}),t({id:`embassy-row-016`,building:`embassy-row`,bullets:[`1.1-K1`,`1.1-S4`],d:2,tags:[`trap:scp-boundary-identity`],stem:`A company has 30 accounts in an organization. No account in the Workloads OU may launch resources in Regions other than two approved Regions, and account administrators must not be able to remove the restriction. Which solution meets these requirements?`,correct:[`Attach a service control policy that denies actions outside the approved Regions to the Workloads OU`,`An SCP sets a guardrail for the users and roles in the accounts under the OU, even if an administrator grants broader permissions.`],wrong:[[`Attach an IAM policy that denies actions in the other Regions to every user and role in each of the accounts of the Workloads OU`,`Account administrators could detach or edit those policies, and every account would have to be maintained separately.`],[`Set a permissions boundary that denies the other Regions on every IAM role in each account`,`A boundary is set per user or role, so it must be maintained for every entity and is not one central control.`],[`Create an AWS Config rule in each account that flags resources found in the other Regions`,`A Config rule detects noncompliant resources after they exist; it does not stop the launches.`]],slot:1,evidence:[`sec-account-separation|For example, you can apply an SCP that restricts users from launching resources in Regions that you have not explicitly allowed.`,`orgs-scps|a user or role in the affected account can't use that permission, even if the account administrator attaches the AdministratorAccess IAM policy with */* permissions to the user.`]}),t({id:`embassy-row-017`,building:`embassy-row`,bullets:[`1.1-S4`],d:2,stem:`A security engineer attaches a service control policy that denies launching Amazon EC2 instances to the organization root. Launches fail in the member accounts, but an administrator in the management account can still launch instances. Which statement BEST explains this behavior?`,correct:[`SCPs affect only member accounts and have no effect on users or roles in the management account`,`AWS states that SCPs affect only the member accounts in the organization.`],wrong:[[`The management account always has a FullAWSAccess SCP that overrides any Deny attached to the root`,`FullAWSAccess only allows actions and an allow does not override a deny; the real reason is that SCPs skip the management account.`],[`SCPs take effect in the management account only after the administrator enables a permissions boundary there`,`SCPs do not depend on permissions boundaries, and they never apply to the management account.`],[`SCPs apply only to IAM roles, so IAM users in any account can still launch instances`,`SCPs affect IAM users and roles in member accounts, so the users in member accounts are blocked as well.`]],slot:2,evidence:[`orgs-scps|SCPs affect only member accounts in the organization. They have no effect on users or roles in the management account.`]}),t({id:`embassy-row-018`,building:`embassy-row`,bullets:[`1.1-S4`],d:3,stem:`In an organization, the root and Account B each have an SCP that explicitly allows Amazon DynamoDB actions. The Production OU, which contains Account B, has an SCP that explicitly denies DynamoDB actions. An administrator in Account B attaches an IAM policy that allows dynamodb:* to a role. Which outcome BEST describes a DynamoDB request made by that role?`,correct:[`The request is denied, because a deny in an SCP at any level on the path to the account blocks the action`,`A deny attached at the OU is evaluated for all member accounts under it, regardless of the allows at other levels.`],wrong:[[`The request is allowed, because the SCP that is attached directly to Account B takes precedence over the SCP of the Production OU`,`No level takes precedence over a deny; a deny at any level on the path blocks the permission.`],[`The request is allowed, because the IAM policy in Account B grants the permission to the role`,`An IAM policy cannot grant more than the SCPs allow, and the deny in the SCP of the OU blocks the action.`],[`The request is allowed, because the SCP at the root explicitly allows DynamoDB for every account`,`An allow at the root is only one level of the path and does not override a deny at the OU.`]],slot:3,evidence:[`orgs-scp-eval|For a permission to be denied for a specific account, any SCP from the root through each OU in the direct path to the account (including the target account itself) can deny that permission.`,`orgs-scp-eval|As a result, both Account A and Account B will be denied access to the service as a deny policy attached to any level in the organization is evaluated for all the OUs and member accounts underneath it.`]}),t({id:`embassy-row-019`,building:`embassy-row`,bullets:[`1.1-S4`],d:3,stem:`An administrator detaches the FullAWSAccess SCP from the organization root and attaches a new SCP whose only statement denies organizations:LeaveOrganization. Afterward, users and roles in every member account lose access to all services. Which change restores access while keeping the restriction with the LEAST amount of change?`,correct:[`Add an Allow statement for the needed services to the new SCP so that an allow exists at the root`,`A permission needs an explicit allow at every level, and a deny-only SCP at the root blocks every service.`],wrong:[[`Attach the AdministratorAccess IAM policy to every user and role in the member accounts`,`IAM policies cannot grant what the SCPs do not allow, and the change would be repeated in every account.`],[`Move all member accounts into a new OU directly under the root`,`The new OU still sits under a root that has no allowing SCP, so every action stays blocked.`],[`Attach the new deny SCP to each OU instead of the root`,`Without an allow at the root and at each level, access stays blocked, and there are more attachments to maintain.`]],slot:0,evidence:[`orgs-scp-eval|A Deny-only SCP at the root therefore blocks every service unless an explicit Allow covers it.`,`orgs-scp-eval|If this policy is removed and not replaced at any level of the organization, all OUs and accounts under that level would be blocked from taking any actions.`]}),e({id:`embassy-row-020`,building:`embassy-row`,bullets:[`1.1-S4`],d:2,stem:`A security team will roll out a restrictive SCP in a production organization with many accounts. The team wants the LOWEST risk of locking users out of key services. Which TWO actions should the team take? (Choose two.)`,correct:[[`Create a test OU, move accounts into it a few at a time, and attach the SCP to that OU`,`Testing on a small number of accounts reveals problems before the SCP affects every account, which AWS recommends over attaching it to the root.`],[`Review service last accessed data to find which services the accounts actually use`,`It shows which allowed services are used or unused, so the SCP can be refined without breaking active workloads.`]],wrong:[[`Attach the SCP to the organization root and fix problems as users report them`,`It applies the policy to every account without testing, which risks locking users out.`],[`Attach the SCP to the management account first to test its effect`,`SCPs have no effect on users or roles in the management account, so the test would show nothing.`],[`Detach FullAWSAccess from the root before testing so that only the new SCP applies`,`Removing the allow policy blocks all actions in every account unless another policy allows them.`]],slots:[2,4],evidence:[`orgs-scps|Instead, create an OU that you can move your accounts into one at a time, or at least in small numbers, to ensure that you don't inadvertently lock users out of key services.`,`orgs-scps|You can use this information to identify unused permissions so that you can refine your SCPs to better adhere to the principle of least privilege.`,`orgs-scps|They have no effect on users or roles in the management account.`]}),e({id:`embassy-row-021`,building:`embassy-row`,bullets:[`1.1-S4`],d:2,tags:[`trap:scp-boundary-identity`],stem:`An IAM user in a member account of an organization must be able to launch Amazon EC2 instances. The organization uses SCPs, and no permissions boundary is attached to the user. Which TWO conditions must be true for the request to be allowed? (Choose two.)`,correct:[[`SCPs that allow the action are in effect at the root, at each OU on the path, and at the account`,`For a permission to be allowed there must be an explicit Allow at every level from the root through the account.`],[`An identity-based policy of the user or of a group of the user allows the action`,`SCPs grant nothing, so the user also needs an IAM permission policy that allows the action.`]],wrong:[[`A permissions boundary that allows the action is attached to the user`,`A permissions boundary only limits permissions and is not required; none is attached in this scenario.`],[`The member account is registered as a delegated administrator for AWS Organizations`,`Delegated administration is unrelated to whether the user is allowed to launch instances.`],[`AWS Control Tower manages the account and has enabled a control that allows the action`,`Control Tower is not required for the user to launch instances, and controls help govern accounts rather than grant permissions.`]],slots:[0,3],evidence:[`orgs-scps|A user without any IAM permission policies has no access, even if the applicable SCPs allow all services and all actions.`,`orgs-scp-eval|For a permission to be allowed for a specific account, there must be an explicit Allow statement at every level from the root through each OU in the direct path to the account (including the target account itself).`]}),t({id:`embassy-row-022`,building:`embassy-row`,bullets:[`1.1-S4`],d:2,tags:[`trap:scp-boundary-identity`],stem:`A company lets teams administer their own accounts in a Sandbox OU. Security requires that no IAM user or role in those accounts can use services outside an approved list, even if administrators grant themselves full access. The company wants to manage this restriction in one place. Which solution meets these requirements?`,correct:[`Attach an SCP that allows only the approved services to the Sandbox OU and replace FullAWSAccess there`,`SCPs set the maximum permissions for every user and role in the OU, and an allow list SCP can replace FullAWSAccess.`],wrong:[[`Attach the approved-services policy to every IAM user and role in each Sandbox account as a permissions boundary`,`A boundary is set per entity in each account, so it is not one central control for the whole OU.`],[`Attach an identity-based policy that allows only the approved services to every IAM group in the accounts`,`Identity-based policies grant permissions rather than set a limit, so administrators could still attach broader policies.`],[`Add a bucket policy and a key policy to every shared resource that lists the approved services`,`Resource-based policies say who may access a resource and exist only on resources that support them; they do not limit which services accounts use.`]],slot:1,evidence:[`orgs-scps|An SCP defines a permission guardrail, or sets limits, on the actions that the IAM users and IAM roles in your organization can perform.`,`orgs-scp-eval|You can replace FullAWSAccess with a policy allowing only a set of services so that new AWS services are not allowed unless they are explicitly allowed by updating SCPs.`,`iam-boundaries|A permissions boundary is an advanced feature for using a managed policy to set the maximum permissions that an identity-based policy can grant to an IAM entity.`]}),e({id:`embassy-row-023`,building:`embassy-row`,bullets:[`1.1-S4`],d:2,stem:`A company with many accounts in an organization uses AWS Control Tower. Teams must be able to request new accounts that start from a standard, pre-approved configuration, and central administrators must be able to see where resources drift from policy. Which TWO capabilities meet these requirements? (Choose two.)`,correct:[[`Account Factory configurable account templates`,`Account Factory lets teams provision new accounts quickly from configurable templates with pre-approved account configurations.`],[`Detective controls enabled on the organizational units`,`Detective controls provide continuous detection of policy non-conformance, which the dashboard shows by account and OU.`]],wrong:[[`A service control policy that grants each team permission to create accounts`,`SCPs do not grant permissions, so they cannot give teams the ability to create accounts.`],[`Preventive controls enabled on the organizational units`,`A preventive control disallows actions that lead to policy violations, but it does not help teams request accounts or show administrators where resources drift from policy.`],[`An AWS RAM resource share that gives each team the permissions of the management account`,`AWS RAM shares resources with other accounts; it does not provision accounts or detect drift.`]],slots:[1,3],evidence:[`control-tower|AWS Control Tower enables end users on your distributed teams to provision new AWS accounts quickly, by means of configurable account templates in Account Factory.`,`control-tower|Use the dashboard to see provisioned accounts across your enterprise, controls enabled for policy enforcement, controls enabled for continuous detection of policy non-conformance, and noncompliant resources organized by accounts and OUs.`,`control-tower-controls|AWS Control Tower implements preventive, detective, and proactive controls that help you govern your resources and monitor compliance across groups of AWS accounts.`]}),t({id:`embassy-row-024`,building:`embassy-row`,bullets:[`1.1-S4`],d:2,tags:[`placement-eligible`,`trap:scp-boundary-identity`],stem:`A company hosts public websites from Amazon S3 buckets behind Amazon CloudFront distributions in accounts under a Production OU. Security requires that no one in those accounts, including account administrators and the root user, can delete the distributions. Which solution meets this requirement with the LEAST operational overhead?`,correct:[`Attach an SCP that denies cloudfront:DeleteDistribution to the Production OU`,`SCPs restrict all users and roles in the attached accounts, including the member account root user, and one attachment covers every account under the OU.`],wrong:[[`Attach an IAM policy that denies cloudfront:DeleteDistribution to each administrator in each account`,`The policy would have to be created and maintained separately in every account, and it does not restrict the account root user.`],[`Set a permissions boundary that denies cloudfront:DeleteDistribution on each IAM role in each account`,`A boundary is attached per IAM role, so every account needs separate maintenance and the root user is not covered.`],[`Create an AWS Config rule that flags an account when a distribution has been deleted`,`A Config rule reports a problem after the deletion happened; it does not prevent the deletion.`]],slot:2,evidence:[`orgs-scps|SCPs affect all users and roles in attached accounts, including the root user.`,`orgs-scps|An SCP restricts permissions for IAM users and roles in member accounts, including the member account's root user.`]}),t({id:`embassy-row-025`,building:`embassy-row`,bullets:[`1.1-S4`],d:2,tags:[`placement-eligible`],stem:`A company serves websites through Amazon CloudFront from private Amazon S3 buckets in accounts under a Websites OU, and it uses AWS Control Tower. The security team must be able to determine whether any account in the OU allows public read access to its S3 buckets, without writing custom code. Which solution meets this requirement with the LEAST effort?`,correct:[`Enable the detective control that detects whether public read access to S3 buckets is allowed on the Websites OU`,`A control applies to the whole OU, and a detective control determines whether public read access to S3 buckets would be permitted in any account under it.`],wrong:[[`Write an AWS Lambda function in each account that scans the bucket policies every hour and emails the findings to the security team`,`It needs custom code in every account, which the team wants to avoid.`],[`Attach an SCP to the management account that allows only private buckets in the Websites OU`,`SCPs have no effect on the management account, and an SCP limits permissions rather than reporting on existing buckets.`],[`Review the bucket permissions of every account in the console each week and record the results`,`It is a manual process in each account, which is more effort than enabling one control on the OU.`]],slot:3,evidence:[`control-tower-controls|if you enable the detective control Detect Whether Public Read Access to Amazon S3 Buckets is Allowed on an OU, you can determine whether an entity (such as a user) would be permitted to have read access over the internet to any Amazon S3 buckets, for any accounts under that OU.`,`control-tower-controls|A control applies to an entire organizational unit (OU), and every AWS account within the OU is affected by the control.`]}),t({id:`embassy-row-026`,building:`embassy-row`,bullets:[`1.1-S5`],d:1,stem:`A company wants to state, on an Amazon SQS queue itself, which principals from other AWS accounts may send messages to the queue. Which type of policy BEST fits this requirement?`,correct:[`A resource-based policy attached to the queue`,`A resource-based policy is attached to a resource and specifies which principal can access that resource.`],wrong:[[`An identity-based policy attached to an IAM user in each account`,`Identity-based policies state what an identity can do and are attached to users, groups or roles, not to the queue.`],[`A permissions boundary attached to the queue`,`A permissions boundary applies to IAM users and roles and only limits their maximum permissions.`],[`A service control policy attached to the organization root`,`SCPs set maximum permissions for users and roles in an organization and are not attached to a queue.`]],slot:0,evidence:[`iam-identity-vs-resource|Resource-based policies are attached to a resource.`,`iam-identity-vs-resource|you can attach resource-based policies to Amazon S3 buckets, Amazon SQS queues, VPC endpoints, AWS Key Management Service encryption keys, Amazon DynamoDB tables and streams`,`iam-cross-account|Unlike an identity-based policy for a role, a resource-based policy specifies who (which principal) can access that resource.`]}),t({id:`embassy-row-027`,building:`embassy-row`,bullets:[`1.1-S5`],d:1,stem:`An administrator adds a Principal element for another AWS account to a policy that is attached to an IAM role, hoping to let that account read an Amazon S3 bucket. IAM rejects the policy. Which statement BEST explains why and what to do instead?`,correct:[`The Principal element is not allowed in identity-based policies, so attach a bucket policy that names the other account`,`Only resource-based policies use the Principal element, so the other account must be named in the bucket policy.`],wrong:[[`The policy exceeded the size limit of IAM, so split the statement into two smaller policies on the role`,`Policy size is not the reason; an identity-based policy cannot use the Principal element at all.`],[`The Principal element works only with IAM user groups, so add the other account to a group in the same account`,`A user group cannot be identified as a principal, because groups relate to permissions, not authentication.`],[`The role must be deleted first, so recreate it with the Principal element in its permissions policy`,`Recreating the role does not help, because the permissions policy of a role cannot contain a Principal element.`]],slot:1,evidence:[`iam-el-principal|You cannot use the Principal element in an identity-based policy.`,`iam-el-principal|You must use the Principal element in resource-based policies.`,`iam-el-principal|You cannot identify a user group as a principal in a policy`]}),t({id:`embassy-row-028`,building:`embassy-row`,bullets:[`1.1-S5`],d:3,tags:[`placement-eligible`],stem:`A company serves a static website from a private Amazon S3 bucket through Amazon CloudFront. S3 Block Public Access is on, and the bucket policy has one statement that lets an ETL role write objects. The distribution has an origin access identity (OAI) associated with its origin, but visitors receive 403 errors. The company must keep the ETL role working and keep the bucket private. Which solution meets these requirements with the LEAST change?`,correct:[`Add a bucket policy statement that lets the OAI read objects, and keep the existing statement for the ETL role`,`A resource policy statement naming the OAI lets CloudFront read the objects, and the bucket stays private for everyone else.`],wrong:[[`Replace the bucket policy with one statement that lets the OAI read objects`,`It removes the statement for the ETL role, so the ETL role loses access.`],[`Turn off Block Public Access and add a public-read statement to the bucket policy`,`It makes the bucket readable by anyone, which breaks the requirement to keep it private.`],[`Attach an IAM role to the CloudFront distribution and allow that role in the bucket policy`,`A CloudFront distribution does not assume an IAM role to read an S3 origin, so the role would never be used.`]],slot:2,evidence:[`s3-bucket-policy-examples|The following example bucket policy grants a CloudFront origin access identity (OAI) permission to get (read) all objects in your S3 bucket.`,`s3-bucket-policy-examples|You can use a CloudFront OAI to allow users to access objects in your bucket through CloudFront but not directly through Amazon S3.`]}),t({id:`embassy-row-029`,building:`embassy-row`,bullets:[`1.1-S5`],d:2,tags:[`placement-eligible`],stem:`A company hosts a static website from an Amazon S3 bucket that is configured as a website endpoint, and it fronts the bucket with Amazon CloudFront. The company now wants the bucket to be private so that only CloudFront can read the objects. Which solution meets this requirement?`,correct:[`Use the regular S3 bucket endpoint as the origin, associate an origin access identity (OAI), and allow the OAI in the bucket policy`,`An OAI works with a regular S3 bucket origin, and the bucket policy lets only that identity read the objects while the bucket stays private.`],wrong:[[`Keep the website endpoint as a custom origin and associate an origin access identity (OAI) with the origin`,`A bucket configured as a website endpoint is a custom origin, which does not send authenticated requests with an OAI.`],[`Keep the website endpoint as the origin and turn on S3 Block Public Access`,`The website endpoint serves anonymous requests, so blocking public access would make CloudFront fail to read the objects.`],[`Keep the bucket public and rely on the CloudFront domain name being hard to guess`,`The bucket would stay readable by anyone who finds it, so it is not private.`]],slot:3,evidence:[`cf-s3-origins|You can use an Amazon S3 bucket that's configured as a website endpoint as a custom origin with CloudFront.`,`s3-bucket-policy-examples|You can use a CloudFront OAI to allow users to access objects in your bucket through CloudFront but not directly through Amazon S3.`]}),e({id:`embassy-row-030`,postGuide:[`cloudfront-oac`],postGuideKey:[`cloudfront-oac`],building:`embassy-row`,bullets:[`1.1-S5`],d:3,tags:[`placement-eligible`],stem:`A company lets customers upload files with PUT requests through an Amazon CloudFront distribution to a private Amazon S3 bucket. The company wants to use origin access control (OAC), and the traffic between CloudFront and Amazon S3 must always use HTTPS. The bucket's S3 Object Ownership setting must also be compatible with OAC. Which THREE actions meet these requirements? (Choose three.)`,correct:[[`Choose the Sign requests setting on the origin access control`,`Communication between CloudFront and Amazon S3 is always through HTTPS only when the OAC is set to always sign requests.`],[`Add a bucket policy statement that lets the CloudFront service principal use s3:GetObject and s3:PutObject for the distribution`,`The bucket policy for OAC can allow read and write access for the distribution, so uploads work while the bucket stays private.`],[`Keep S3 Object Ownership set to Bucket owner enforced`,`OAC with an Amazon S3 bucket origin requires the Bucket owner enforced setting for Object Ownership.`]],wrong:[[`Choose the Do not sign requests setting so that CloudFront forwards the viewer request unchanged`,`CloudFront then uses the protocol from the viewer protocol policy instead of always using HTTPS, and the requests are not signed by the OAC.`],[`Enable static website hosting on the bucket and use the website endpoint as the origin`,`A bucket configured as a website endpoint cannot use origin access control.`],[`Attach a service control policy that allows CloudFront to write to the bucket`,`SCPs do not grant permissions to anything, so they cannot let CloudFront write to the bucket.`]],slots:[0,2,5],evidence:[`cf-oac|When you use OAC to secure your Amazon S3 origin, communication between CloudFront and Amazon S3 is always through HTTPS, but only when you choose to always sign requests.`,`cf-oac|Example S3 bucket policy that allows read and write access for a CloudFront distribution with OAC enabled`,`cf-oac|When you use CloudFront OAC with Amazon S3 bucket origins, you must set Amazon S3 Object Ownership to Bucket owner enforced, the default for new Amazon S3 buckets.`]}),t({id:`embassy-row-031`,building:`embassy-row`,bullets:[`1.1-S5`],d:3,tags:[`placement-eligible`],stem:`A company serves a static website from a private Amazon S3 bucket through Amazon CloudFront. Visitors must be able to read the objects only through CloudFront and not directly through Amazon S3. A developer proposes a bucket policy that allows any principal when the aws:Referer condition key matches the website domain. Which approach BEST meets the requirement?`,correct:[`Associate an origin access identity (OAI) with the origin and allow only that OAI to read objects in the bucket policy`,`Only the OAI is allowed to read, so requests that go directly to Amazon S3 are not allowed.`],wrong:[[`Use the proposed bucket policy that allows any principal when aws:Referer matches the domain`,`A request that carries the expected referer header can read the objects directly from Amazon S3, so access is not limited to CloudFront.`],[`Allow the AWS account root user in the bucket policy and share its credentials with CloudFront`,`CloudFront does not sign requests with shared credentials, and sharing root credentials is unsafe.`],[`Make the bucket public and enable S3 server access logging to catch direct requests`,`Logging records requests but does not stop them, and the bucket would not be private.`]],slot:0,evidence:[`s3-bucket-policy-examples|You can use a CloudFront OAI to allow users to access objects in your bucket through CloudFront but not directly through Amazon S3.`,`s3-bucket-policy-examples|We recommend that you use caution when using the aws:Referer condition key.`]}),t({id:`embassy-row-032`,building:`embassy-row`,bullets:[`1.1-K1`],d:2,tags:[`mock-reserve`],stem:`A company needs a single record of the API activity in every member account of its organization, stored centrally, that member accounts cannot turn off or modify. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an organization trail in AWS CloudTrail from the management account`,`An organization trail logs events for the management account and all member accounts, and the resulting log cannot be turned off or modified by member accounts.`],wrong:[[`Ask each account owner to create a trail that delivers events to a central Amazon S3 bucket`,`Each owner could stop or change a trail in their own account, and the setup is repeated in every account.`],[`Use the CloudTrail Event history of each account and export the results every month`,`Event history is kept per account and covers a limited period, and the export is manual work.`],[`Create an AWS Config aggregator in the management account for all member accounts`,`AWS Config records the configuration of resources, not a log of the API calls that were made.`]],slot:1,evidence:[`cloudtrail-org-trail|Organization trails log events for the management account and all member accounts in the organization.`,`orgs-intro|You can activate AWS CloudTrail across accounts, which creates a log of all activity in your cloud environment that cannot be turned off or modified by member accounts.`]}),t({id:`embassy-row-033`,building:`embassy-row`,bullets:[`1.1-S3`],d:2,tags:[`mock-reserve`],stem:`Security requires that only users who signed in with multi-factor authentication (MFA) can assume a sensitive production role from another account. The company wants to enforce this on the role itself. Which solution meets this requirement?`,correct:[`Add MFA protection to the role so that only users who sign in with an MFA device can assume it`,`MFA protection configured on the role requires an MFA sign-in before the role can be assumed.`],wrong:[[`Require MFA only when users sign in to the console of the development account`,`It does not enforce MFA on the role itself, so a session created without MFA could still assume the role.`],[`Attach a service control policy that grants sts:AssumeRole only to users who used MFA`,`SCPs do not grant permissions, so they cannot grant sts:AssumeRole to anyone.`],[`Add the serial number of the MFA device to the permissions policy of the role as a resource`,`The permissions policy defines what the role can do; it does not control who can assume the role.`]],slot:2,evidence:[`iam-account-switch|You can add multi-factor authentication (MFA) protection to the role so that only users who sign in with an MFA device can assume the role.`]}),t({id:`embassy-row-034`,building:`embassy-row`,bullets:[`1.1-S4`],d:1,tags:[`mock-reserve`],stem:`The organization of a company was created with only the consolidated billing features. A security engineer cannot use service control policies. Which action makes SCPs available with the LEAST effort?`,correct:[`Enable all features in the organization`,`SCPs are available only in an organization that has all features enabled.`],wrong:[[`Attach the FullAWSAccess SCP to the organization root`,`FullAWSAccess is itself an SCP, so it cannot be attached while SCPs are not available in the organization.`],[`Create a permissions boundary for the IAM users in each member account`,`Permissions boundaries are an IAM feature for single users and roles and do not replace SCPs.`],[`Register a delegated administrator account for the organization`,`A delegated administrator manages supported services and does not turn on SCPs.`]],slot:3,evidence:[`orgs-scps|SCPs aren't available if your organization has enabled only the consolidated billing features.`,`orgs-scps|SCPs are available only in an organization that has all features enabled.`]}),e({id:`embassy-row-035`,building:`embassy-row`,bullets:[`1.1-S5`],d:3,tags:[`mock-reserve`],stem:`An AWS Lambda function in a shared-services account must be invokable by IAM roles in every account of the company organization, with the LEAST maintenance of the function policy. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Add a resource-based policy to the function that allows lambda:InvokeFunction and uses the aws:PrincipalOrgID condition key`,`A resource-based policy can grant organizations access to a function, and the condition key keeps the accounts current without manual updates.`],[`Allow lambda:InvokeFunction on the function ARN in an identity-based policy of the roles in the invoking accounts`,`In cross-account access the principal also needs an Allow in its identity-based policy.`]],wrong:[[`Attach a service control policy to the organization root that grants lambda:InvokeFunction on the function`,`SCPs do not grant permissions, so they cannot allow the invocation.`],[`List the account ID of every member account as a principal in the resource-based policy of the function`,`It requires editing the policy whenever an account is added or removed, which adds the maintenance the company wants to avoid.`],[`Create a copy of the function in every account of the organization`,`It duplicates the function instead of sharing it and multiplies the deployments to maintain.`]],slots:[2,4],evidence:[`lambda-resource-policy|With resource-based permissions policies, you can grant other AWS accounts, users, organizations, and AWS services access to your Lambda Event Functions.`,`iam-cross-account|In cross account access, a principal needs an Allow in the identity policy and the resource-based policy.`,`iam-global-condition-keys|When you add and remove accounts, policies that include the aws:PrincipalOrgID key automatically include the correct accounts and don't require manual updating.`]})],c=[t({id:`federation-bridge-001`,building:`federation-bridge`,bullets:[`1.1-K2`],d:1,stem:`A company uses AWS Organizations with 12 AWS accounts. The company has no corporate identity provider or directory, and about 40 employees need access to the accounts they are assigned. The company wants to create and manage the employees in one place and let them sign in to all assigned accounts with the LEAST administrative effort. Which solution meets these requirements?`,correct:[`Enable AWS IAM Identity Center and create the employees in its built-in identity store`,`IAM Identity Center is recommended for centralized access management of human users across accounts, and users can be created and managed directly in it.`],wrong:[[`Create an IAM SAML identity provider and the matching IAM roles separately in each of the 12 accounts`,`A SAML identity provider needs an external identity provider that the company does not have, and the setup would be repeated in all 12 accounts.`],[`Create an IAM user for every employee in each account and require a password change at first sign-in`,`It creates many identities with long-term credentials in 12 places instead of managing the employees in one place.`],[`Create an Amazon Cognito user pool and have employees sign in to the AWS Management Console through it`,`Amazon Cognito authenticates the users of mobile and web apps and is not the way to manage workforce access to AWS accounts.`]],slot:0,evidence:[`iam-idp-federation|For centralized access management of human users, we recommend that you use IAM Identity Center to manage access to your accounts and permissions within those accounts.`,`sso-what-is|You can connect your existing identity provider and synchronize users and groups from your directory, or create and manage your users directly in IAM Identity Center.`,`iam-idp-federation|Amazon Cognito is designed for developers who want to authenticate and authorize users in their mobile and web apps.`]}),t({id:`federation-bridge-002`,building:`federation-bridge`,bullets:[`1.1-S6`],d:1,stem:`A company keeps all employee accounts in a corporate directory. Until now, the cloud team created a separate IAM user with a long-term password for each employee who needs AWS access. Which approach BEST follows AWS guidance for human users?`,correct:[`Federate the corporate directory with AWS so that employees sign in with it and assume IAM roles`,`AWS recommends that human users use federation with an identity provider, which gives them temporary credentials instead of separate IAM users.`],wrong:[[`Keep the IAM users and require each employee to change the password every 90 days`,`Each employee would still hold a separate IAM user with long-term credentials, whereas federation with the directory is recommended.`],[`Create one shared IAM user for each department and give the credentials to the whole team`,`Shared credentials are still long-term IAM user credentials, and the corporate directory is not used at all.`],[`Create access keys for each employee and store the keys in the corporate directory`,`Access keys are long-term credentials that must be distributed and rotated, which federation avoids.`]],slot:1,evidence:[`iam-users|IAM best practices recommend that you require human users to use federation with an identity provider to access AWS using temporary credentials instead of using IAM users with long-term credentials.`,`iam-idp-federation|This is useful if your organization already has its own identity system, such as a corporate user directory.`]}),t({id:`federation-bridge-003`,building:`federation-bridge`,bullets:[`1.1-K2`],d:2,stem:`A company is building a mobile app for the general public. Users sign in with their existing Google or Apple accounts, and the app must then upload photos directly to an Amazon S3 bucket by using temporary, limited-privilege AWS credentials. Which solution meets these requirements with the LEAST custom code?`,correct:[`Use Amazon Cognito with an identity pool that exchanges the sign-in token for temporary AWS credentials`,`An identity pool exchanges a trusted token from a social provider for temporary, limited-privilege credentials that the app can use with Amazon S3.`],wrong:[[`Use AWS IAM Identity Center and add each app user to a group that has an Amazon S3 permission set`,`IAM Identity Center connects workforce users to AWS accounts and applications and is not meant for the public users of an app.`],[`Create an IAM user for each person who signs up and embed that user's access keys in the app`,`Long-term keys embedded in a public app are the opposite of temporary credentials, and it creates one IAM user per customer.`],[`Create an IAM SAML identity provider and an IAM role that every app user assumes through a custom broker`,`It needs custom brokering code, whereas Amazon Cognito already exchanges social sign-in tokens for temporary credentials.`]],slot:2,evidence:[`cognito-what-is|An identity pool exchanges a trusted token (from a user pool, a social provider, or a SAML or OIDC provider) for temporary, limited-privilege AWS credentials so that your app can call services like Amazon S3 and Amazon DynamoDB on the user's behalf.`,`iam-idp-federation|Amazon Cognito is designed for developers who want to authenticate and authorize users in their mobile and web apps.`]}),t({id:`federation-bridge-004`,building:`federation-bridge`,bullets:[`1.1-K2`],d:2,stem:`A company set up SAML 2.0 federation in a single AWS account. Federated employees authenticate successfully with the identity provider but receive an error when they try to assume the IAM role. The permissions policy of the role is correct, but its trust policy names only the account root as the trusted principal. What is the SIMPLEST fix?`,correct:[`Change the trust policy so that it names the IAM SAML provider as the Principal`,`The trust policy of a role for SAML federation specifies the SAML provider as the Principal, which lets the federated users assume the role.`],wrong:[[`Add sts:AssumeRole to the permissions policy of the role for the federated employees`,`The permissions policy defines what users may do once they have assumed the role, not who is allowed to assume it.`],[`Create an IAM user for each federated employee and add the users to the trust policy`,`It brings back an IAM user for everyone, which federation with the identity provider is meant to avoid.`],[`Create access keys for the role and give the keys to the identity provider administrator`,`A role has no long-term credentials; assuming it provides temporary security credentials for the role session.`]],slot:3,evidence:[`iam-saml|When you create the trust policy for the role, you specify the SAML provider that you created earlier as the Principal.`,`iam-saml|The roles that you create in IAM define what SAML federated principals from your organization are allowed to do in AWS.`,`iam-roles|Instead, when you assume a role, it provides you with temporary security credentials for your role session.`]}),t({id:`federation-bridge-005`,building:`federation-bridge`,bullets:[`1.1-S6`],d:2,stem:`A company runs its employee directory on Microsoft Active Directory in its data center. Compatible AWS applications must let employees sign in with their existing Active Directory credentials. The company does not need Active Directory features inside AWS and does not want to synchronize the directory or host federation infrastructure. Which solution is the SIMPLEST?`,correct:[`Deploy AD Connector to proxy sign-in requests to the on-premises domain controllers`,`AD Connector forwards sign-in requests to the existing directory and removes the need for directory synchronization or federation infrastructure.`],wrong:[[`Deploy AWS Managed Microsoft AD and create a new set of user accounts in the cloud directory`,`It creates a second directory to maintain, and actual Active Directory features in AWS are not needed here.`],[`Deploy Simple AD and re-create the employee accounts as new identities in the cloud directory`,`Simple AD is a standalone directory in which identities are created again, so the existing accounts are not used.`],[`Deploy AD FS servers on Amazon EC2 and configure an IAM SAML provider for the applications`,`Hosting AD FS is the federation infrastructure that the company wants to avoid.`]],slot:0,evidence:[`ds-what-is|Use AD Connector if you only need to allow your on-premises users to log in to AWS applications and services with their Active Directory credentials.`,`ds-what-is|AD Connector also eliminates the need of directory synchronization or the cost and complexity of hosting a federation infrastructure.`,`ds-what-is|Simple AD is a standalone directory in the cloud, where you create and manage user identities and manage access to applications.`]}),t({id:`federation-bridge-006`,building:`federation-bridge`,bullets:[`1.1-S6`],d:2,stem:`A company is migrating Windows-based applications to AWS. The workload uses Amazon EC2 Windows instances and Amazon RDS for SQL Server, and the team needs a directory that runs actual Microsoft Active Directory in the AWS Cloud. Which directory option BEST meets these requirements?`,correct:[`Create an AWS Managed Microsoft AD directory and join the Windows workloads to its domain`,`AWS Managed Microsoft AD provides actual Active Directory features and supports Windows workloads, including Amazon RDS for SQL Server.`],wrong:[[`Create an AD Connector directory that proxies requests to a self-managed Active Directory domain`,`AD Connector is a proxy service and is not compatible with RDS SQL Server.`],[`Create a Simple AD directory and join the Windows workloads to its domain in the cloud`,`Simple AD is not compatible with RDS SQL Server and offers only basic Active Directory features.`],[`Create an Amazon Cognito user pool and register the Windows instances as members of the pool`,`A user pool is a user directory for sign-in to apps and APIs and is not a Windows domain that servers can join.`]],slot:1,evidence:[`ds-what-is|AWS Managed Microsoft AD is your best choice if you need actual Active Directory features to support AWS applications or Windows workloads, including Amazon Relational Database Service for Microsoft SQL Server.`,`ds-what-is|AD Connector is not compatible with RDS SQL Server.`,`ds-what-is|Simple AD is not compatible with RDS SQL Server.`]}),t({id:`federation-bridge-007`,building:`federation-bridge`,bullets:[`1.1-K2`],d:2,stem:`A company federated its SAML 2.0 identity provider separately with each of 8 AWS accounts by creating an IAM SAML provider and roles in every account. Whenever the certificate of the identity provider changes, administrators must update all 8 accounts. The accounts belong to one AWS Organizations organization. Which change MOST reduces this effort?`,correct:[`Connect the identity provider once to an IAM Identity Center organization instance and assign access to the accounts`,`With IAM Identity Center you federate once and have only one certificate to manage for a SAML 2.0 identity provider.`],wrong:[[`Create the IAM SAML provider in one account and reference it from the roles in the other 7 accounts`,`A SAML provider used in a role trust policy must be in the same account as the role, so this cannot work.`],[`Replace the SAML providers with an OIDC provider that is created separately in each of the 8 accounts`,`Each account would still have its own provider entity, so the federation setup stays repeated 8 times.`],[`Create an Amazon Cognito identity pool in each account and add the identity provider to every pool`,`It still repeats the federation setup in every account and targets app users rather than workforce access.`]],slot:2,evidence:[`sso-what-is|With IAM Identity Center, you only federate once, and you have only one certificate to manage when using a SAML 2.0 identity provider.`,`iam-saml|SAML IDPs used in a role trust policy must be in the same account that the role is in.`]}),t({id:`federation-bridge-008`,building:`federation-bridge`,bullets:[`1.1-K2`],d:1,stem:`A company lets employees sign in to AWS through a SAML 2.0 identity provider. A developer asks what an application receives from AWS when its call to AssumeRoleWithSAML succeeds. Which statement BEST describes the response?`,correct:[`A set of temporary security credentials for the role that was assumed`,`The API returns temporary security credentials that the application uses to make signed requests to AWS.`],wrong:[[`A new IAM user that AWS creates for the employee, together with a long-term password`,`Federation exists so that no IAM user has to be created for each person in the organization.`],[`A permanent pair of access keys that AWS stores for the employee in the account`,`The response carries temporary security credentials, not permanent access keys.`],[`A copy of the directory password of the employee that AWS keeps for later sign-ins`,`The identity provider authenticates the employee, and AWS receives a SAML assertion rather than the password.`]],slot:3,evidence:[`iam-saml|If the request is successful, the API returns a set of temporary security credentials, which your application can use to make signed requests to AWS.`,`iam-saml|This feature enables federated single sign-on (SSO), so users can log into the AWS Management Console or call AWS API operations without you having to create an IAM user for everyone in your organization.`]}),t({id:`federation-bridge-009`,building:`federation-bridge`,bullets:[`1.1-S6`],d:2,stem:`Employees of a company are managed in a corporate directory, and each employee also has a separate IAM user. When people leave, the identity team removes them from the directory, and their IAM users stay active for weeks until the cloud team notices. Which solution MOST reduces this risk with the LEAST ongoing effort?`,correct:[`Federate the directory with AWS and remove the IAM users so that access follows the directory accounts`,`Federated users sign in through the identity provider, so there are no separate long-term IAM users left to find and delete.`],wrong:[[`Write a nightly script that compares both lists and deletes the IAM users that are missing from the directory`,`It keeps long-term IAM users and adds custom code to maintain, whereas federation removes the need for separate users.`],[`Require MFA on every IAM user in addition to the password the employee already uses`,`MFA adds a second factor at sign-in, but the IAM user of a leaver would still exist and could still be used.`],[`Rotate the access keys of every IAM user in the account every 30 days with a scheduled job`,`Rotation does not deactivate users who left, and the IAM users stay separate from the directory.`]],slot:0,evidence:[`iam-users|IAM best practices recommend that you require human users to use federation with an identity provider to access AWS using temporary credentials instead of using IAM users with long-term credentials.`,`iam-idp-federation|With an identity provider (IdP), you can manage your user identities outside of AWS and give these external user identities permissions to use AWS resources in your account.`]}),t({id:`federation-bridge-010`,building:`federation-bridge`,bullets:[`1.1-K2`,`1.1-S6`],d:3,stem:`The employees of a company are spread across two Active Directory forests in its data centers. The company wants to give all employees single sign-on to the AWS accounts of its organization by using AWS IAM Identity Center with their existing Active Directory credentials, and wants to avoid copying users into a new identity store. Which solution meets these requirements?`,correct:[`Create an AWS Managed Microsoft AD directory with trusts to both forests and connect it to IAM Identity Center`,`AWS Managed Microsoft AD supports multiple forests, and IAM Identity Center can work with users from any domain connected through an AD trust.`],wrong:[[`Create two AD Connector directories, one for each forest, and connect both of them to IAM Identity Center`,`Only one AD Connector directory or one AWS Managed Microsoft AD directory can be connected at a time.`],[`Create a Simple AD directory in the cloud and connect it to IAM Identity Center as the identity source`,`IAM Identity Center does not support Simple AD as a connected directory, and Simple AD does not support trust relationships.`],[`Create the users manually in the IAM Identity Center directory and ask each employee to set a new password`,`It copies the users into a new identity store and does not use the existing Active Directory credentials.`]],slot:1,evidence:[`sso-ad|You can connect only one AD Connector directory or one directory in AWS Managed Microsoft AD at a time.`,`sso-ad|If you need to support multiple domains or forests, use AWS Managed Microsoft AD.`,`sso-ad|When you use AWS Managed Microsoft AD as your identity source, IAM Identity Center can work with users from AWS Managed Microsoft AD or from any domain connected through an AD trust.`,`ds-what-is|Simple AD does not support multi-factor authentication (MFA), trust relationships, DNS dynamic update, schema extensions, communication over LDAPS, PowerShell AD cmdlets, or FSMO role transfer.`]}),t({id:`federation-bridge-011`,building:`federation-bridge`,bullets:[`1.1-S6`,`1.1-K2`],d:3,stem:`A company has one on-premises Active Directory domain and 15 AWS accounts in an AWS Organizations organization. Employees must reach the accounts with their Active Directory credentials by using AWS IAM Identity Center. The company does not want to run AD FS servers or create a new set of user accounts in AWS. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an AD Connector directory in the management account and use it as the identity source for IAM Identity Center`,`AD Connector reaches the existing directory without federation infrastructure, and it can serve as the Active Directory source for IAM Identity Center.`],wrong:[[`Deploy AD FS on Amazon EC2 and create an IAM SAML provider with matching roles in each of the 15 accounts`,`It hosts the federation infrastructure that the company wants to avoid and repeats the setup in all 15 accounts.`],[`Create an AWS Managed Microsoft AD directory and re-create all employee accounts inside the new directory`,`It requires re-creating every employee account in a new directory, and the existing Active Directory accounts are not used.`],[`Connect a Simple AD directory to IAM Identity Center and synchronize the employee accounts into it`,`IAM Identity Center does not support Simple AD as a connected directory.`]],slot:2,evidence:[`sso-ad|You must have an existing AD Connector or AWS Managed Microsoft AD directory set up in AWS Directory Service, and it must reside within your AWS Organizations management account.`,`ds-what-is|AD Connector also eliminates the need of directory synchronization or the cost and complexity of hosting a federation infrastructure.`,`sso-ad|IAM Identity Center does not support SAMBA 4-based Simple AD as a connected directory.`]}),t({id:`federation-bridge-012`,building:`federation-bridge`,bullets:[`1.1-K2`],d:2,stem:`A startup is developing a SaaS application for thousands of customers. Customers must be able to sign up and sign in with an email address or with their social media accounts, and the startup does not want to operate a user directory itself. Which service is the BEST fit?`,correct:[`An Amazon Cognito user pool that stores and authenticates the customers`,`Amazon Cognito provides a scalable directory to manage and authenticate subscribers and works with social media identities.`],wrong:[[`AWS IAM Identity Center with its built-in identity store for the customers`,`IAM Identity Center connects workforce users to AWS and is not a directory for customers of an application.`],[`AWS Managed Microsoft AD with a separate domain trust for each customer`,`It provides actual Active Directory for AD-aware workloads, not a high-scale directory for subscribers.`],[`A separate IAM user for each customer, created automatically at sign-up`,`IAM users carry long-term credentials, and IAM is not designed as a customer directory.`]],slot:3,evidence:[`ds-what-is|Use Amazon Cognito if you develop high-scale SaaS applications and need a scalable directory to manage and authenticate your subscribers and that works with social media identities.`,`sso-what-is|AWS IAM Identity Center is the AWS solution for connecting your workforce users to AWS managed applications`]}),e({id:`federation-bridge-013`,building:`federation-bridge`,bullets:[`1.1-K2`],d:2,stem:`A company uses AWS IAM Identity Center with 30 member accounts in AWS Organizations. The company wants its Finance group to have the same job-function permissions in every account where the group works, and wants to change those permissions in one place later, with the LEAST effort. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a permission set that defines the job-function permissions`,`Permission sets centrally create permissions for common job functions and provision them across AWS accounts.`],[`Assign the Finance group to the permission set in each account where the group works`,`Permission sets are assigned to users and groups, so the group gets the same permissions in every assigned account.`]],wrong:[[`Create identical IAM roles by hand in each of the 30 accounts and edit every role when the permissions change`,`The roles would have to be created and kept consistent by hand in all 30 accounts, which is the effort the company wants to avoid.`],[`Attach a service control policy to the organization root that grants the Finance permissions`,`SCPs do not grant permissions, so they cannot give the group its job-function permissions.`],[`Attach a permissions boundary to each Finance user so that the boundary grants the job-function permissions`,`A permissions boundary sets the maximum permissions that an identity-based policy can grant and does not grant permissions itself.`]],slots:[0,3],evidence:[`sso-what-is|You can also use IAM Identity Center permission sets to centrally create permissions for common job functions such as admin, provision them across AWS accounts, and assign them to users and groups.`,`orgs-scps|SCPs do not grant permissions to the IAM users and IAM roles in your organization.`,`iam-boundaries|A permissions boundary is an advanced feature for using a managed policy to set the maximum permissions that an identity-based policy can grant to an IAM entity.`]}),e({id:`federation-bridge-014`,building:`federation-bridge`,bullets:[`1.1-S6`],d:3,stem:`A company is moving a Windows application to AWS. The application servers on Amazon EC2 and an Amazon RDS for SQL Server database must use Active Directory, and employees must keep using the credentials from the Active Directory in the company's data center without copying the accounts into AWS. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create an AWS Managed Microsoft AD directory in AWS for the servers and the database`,`AWS Managed Microsoft AD supports Windows workloads, including Amazon RDS for SQL Server.`],[`Create a trust relationship between the AWS Managed Microsoft AD directory and the on-premises Active Directory`,`A trust lets AWS Managed Microsoft AD use credentials from the Active Directory that runs on premises.`]],wrong:[[`Create an AD Connector directory that points to the on-premises domain controllers`,`AD Connector is a proxy service and is not compatible with RDS SQL Server.`],[`Create a Simple AD directory and re-create the employee accounts inside it`,`Simple AD is not compatible with RDS SQL Server and does not support trust relationships.`],[`Use the built-in identity store of IAM Identity Center as the domain for the servers and database`,`IAM Identity Center provides workforce sign-in to AWS accounts and applications, not an Active Directory domain for servers.`]],slots:[1,4],evidence:[`ds-what-is|All compatible applications work with user credentials that you store in AWS Managed Microsoft AD, or you can connect to your existing AD infrastructure with a trust and use credentials from an Active Directory running on-premises or on EC2 Windows.`,`ds-what-is|AWS Managed Microsoft AD is your best choice if you need actual Active Directory features to support AWS applications or Windows workloads, including Amazon Relational Database Service for Microsoft SQL Server.`,`ds-what-is|AD Connector is not compatible with RDS SQL Server.`]}),e({id:`federation-bridge-015`,building:`federation-bridge`,bullets:[`1.1-K2`],d:1,stem:`An administrator is setting up AWS IAM Identity Center for workforce access. Which TWO can IAM Identity Center use as the identity source for users and groups? (Choose two.)`,correct:[[`An external SAML 2.0 identity provider`,`IAM Identity Center can use an external identity provider as the source of users and groups.`],[`A directory in AWS Managed Microsoft AD`,`IAM Identity Center can connect a directory in AWS Managed Microsoft AD by using AWS Directory Service.`]],wrong:[[`A Simple AD directory in AWS Directory Service`,`IAM Identity Center does not support Simple AD as a connected directory.`],[`An Amazon Cognito user pool for the employees`,`It is not one of the identity sources that IAM Identity Center lists: Active Directory, an external identity provider or its own directory.`],[`The IAM users of the management account`,`It is not one of the identity sources that IAM Identity Center lists: Active Directory, an external identity provider or its own directory.`]],slots:[0,2],evidence:[`iam-idp-federation|You can use Active Directory, an external identity provider (IdP), or an IAM Identity Center directory as the identity source for users and groups to assign access to your AWS resources.`,`sso-ad|With AWS IAM Identity Center, you can connect a self-managed directory in Active Directory (AD) or a directory in AWS Managed Microsoft AD by using AWS Directory Service.`,`sso-ad|IAM Identity Center does not support SAMBA 4-based Simple AD as a connected directory.`]}),t({id:`federation-bridge-016`,building:`federation-bridge`,bullets:[`1.1-K2`],d:3,stem:`A company with a single AWS account uses SAML 2.0 federation. Employees in the Finance group need read-only access to Amazon S3 reports, and employees in the Engineering group must manage Amazon EC2 instances. Both groups sign in through the same identity provider, and the company wants the identity provider to decide which permissions each person gets. Which solution BEST meets these requirements?`,correct:[`Create two IAM roles that trust the SAML provider and map each identity provider group to its role in the assertions`,`Assertions map users or groups to IAM roles, and the permissions of each role define what that group may do in AWS.`],wrong:[[`Create one IAM role with both sets of permissions and let every employee from the identity provider assume it`,`Finance employees would gain EC2 management and Engineering employees would gain S3 access, which exceeds what each group needs.`],[`Create an IAM user for each employee and add the Finance and Engineering users to two separate IAM groups`,`It uses IAM users with long-term credentials, and the identity provider no longer decides the permissions.`],[`Create two IAM roles that trust the account root and let employees switch roles after they sign in with a shared IAM user`,`It relies on a shared IAM user, and the identity provider does not decide which role each person gets.`]],slot:0,evidence:[`iam-saml|In your organization's IdP, you define assertions that map users or groups in your organization to the IAM roles.`,`iam-saml|Note that different users and groups in your organization might map to different IAM roles.`,`iam-saml|The roles that you create in IAM define what SAML federated principals from your organization are allowed to do in AWS.`]}),t({id:`federation-bridge-017`,building:`federation-bridge`,bullets:[`1.1-S6`],d:3,tags:[`mock-reserve`],stem:`A company needs a directory in AWS for Linux applications that require LDAP and for a few Windows servers. The company has no directory on premises. Later it plans to give the same users single sign-on to its AWS accounts through AWS IAM Identity Center and wants to avoid replacing the directory at that point. Which directory option BEST meets these requirements?`,correct:[`Create an AWS Managed Microsoft AD directory in AWS Directory Service`,`It supplies LDAP support for Linux applications and actual Active Directory for Windows, and IAM Identity Center can connect to it.`],wrong:[[`Create a Simple AD directory in AWS Directory Service because it is the lowest-scale option`,`IAM Identity Center does not support Simple AD as a connected directory, so the directory would have to be replaced later.`],[`Create an AD Connector directory in AWS Directory Service for the servers and applications`,`AD Connector is a proxy to an existing on-premises Active Directory, and the company has none to connect to.`],[`Create an Amazon Cognito user pool and let the Linux and Windows servers authenticate against it`,`A user pool authenticates users of apps and APIs and is not an LDAP or Windows domain directory.`]],slot:1,evidence:[`ds-what-is|It's also best if you want a standalone Active Directory in the AWS Cloud that supports Office 365 or you need an LDAP directory to support your Linux applications.`,`sso-ad|IAM Identity Center does not support SAMBA 4-based Simple AD as a connected directory.`,`ds-what-is|AD Connector is a proxy service that provides an easy way to connect compatible AWS applications, such as Amazon WorkSpaces, Amazon Quick, and Amazon EC2 for Windows Server instances, to your existing on-premises Microsoft Active Directory.`]}),e({id:`federation-bridge-018`,building:`federation-bridge`,bullets:[`1.1-K2`],d:2,tags:[`mock-reserve`],stem:`A company wants its employees to sign in to the AWS Management Console with a corporate SAML 2.0 identity provider in one AWS account, without an IAM user for each employee. Which TWO configuration steps are required in AWS? (Choose two.)`,correct:[[`Create a SAML identity provider in IAM by using the metadata document from the identity provider`,`The metadata describes the identity provider to IAM and carries the keys AWS uses to validate the authentication responses.`],[`Create an IAM role whose trust policy names the SAML provider as the principal`,`The trust relationship between the organization and AWS is established by naming the SAML provider as the principal of the role.`]],wrong:[[`Create an IAM user for every employee and store the SAML assertion as that user's console password`,`Federation exists so that an IAM user does not have to be created for everyone in the organization.`],[`Create an AWS Managed Microsoft AD directory and join the identity provider to its domain`,`A directory is not required for SAML federation, which relies on the identity provider and IAM roles.`],[`Create an Amazon Cognito user pool and register the console sign-in URL as its callback address`,`Console access through SAML federation uses an IAM SAML provider and roles, not a Cognito user pool.`]],slots:[1,3],evidence:[`iam-saml|Using your organization's IdP, you generate an equivalent SAML metadata XML file that can describe your IdP as an IAM identity provider in AWS.`,`iam-saml|In the role's trust policy, you set the SAML provider as the principal, which establishes a trust relationship between your organization and AWS.`,`iam-saml|This feature enables federated single sign-on (SSO), so users can log into the AWS Management Console or call AWS API operations without you having to create an IAM user for everyone in your organization.`]}),t({id:`federation-bridge-019`,building:`federation-bridge`,bullets:[`1.1-S6`],d:2,tags:[`mock-reserve`],stem:`A company wants to join new Amazon EC2 Windows instances to its existing on-premises Active Directory domain. The company does not need Active Directory features in AWS and wants the SIMPLEST setup for these instances. Which solution meets these requirements?`,correct:[`Use AD Connector and join the instances to the on-premises domain with seamless domain join`,`AD Connector lets EC2 Windows instances join the on-premises Active Directory domain through seamless domain join.`],wrong:[[`Create an AWS Managed Microsoft AD directory and join the instances to its new cloud domain`,`It creates a separate domain rather than using the existing on-premises domain, and it provides more than is needed.`],[`Install domain controllers on new EC2 instances and replicate the on-premises domain to them`,`The company would have to operate its own domain controllers, which is more work than a proxy service.`],[`Use the built-in identity store of IAM Identity Center and join the instances to that store`,`IAM Identity Center connects workforce users to AWS and is not an Active Directory domain that instances can join.`]],slot:2,evidence:[`ds-what-is|You can also join your EC2 Windows instances to your on-premises Active Directory domain through AD Connector using seamless domain join.`,`ds-what-is|AD Connector is your best choice when you want to use your existing on-premises directory with compatible AWS services.`]})],l=[t({id:`gatehouse-001`,building:`gatehouse`,bullets:[`1.2-K3`],d:1,tags:[`trap:sg-vs-nacl`],stem:`A company runs a public web application on Amazon EC2 instances in a VPC. Security staff identify one IPv4 address range that sends malicious requests. That range must be blocked at the subnet while every other internet user stays allowed. Which solution meets these requirements MOST simply?`,correct:[`Add an inbound deny rule for the address range to the network ACL of the subnet`,`A network ACL can allow or deny traffic at the subnet level, so a deny rule blocks that range and everything else stays allowed.`],wrong:[[`Add an inbound deny rule for the address range to the security group of the instances`,`A security group can hold allow rules only, so it cannot express a deny rule.`],[`Remove the route to the internet gateway from the route table of the subnet`,`That would cut off every internet user, not only the malicious range.`],[`Edit the security group so that it allows only the addresses of known legitimate users`,`The site must stay open to all other internet users, and a security group cannot deny the range explicitly.`]],slot:0,evidence:[`vpc-sg-rules|You can specify allow rules, but not deny rules.`,`vpc-nacls|Each rule can either allow or deny traffic.`]}),t({id:`gatehouse-002`,building:`gatehouse`,bullets:[`1.2-K3`],d:2,tags:[`trap:sg-vs-nacl`],stem:`A solutions architect removes every outbound rule from the security group of an Amazon EC2 web server. The group keeps one inbound rule that allows TCP port 443 from 0.0.0.0/0. Clients on the internet must still receive responses to their HTTPS requests. What should the architect do to meet this requirement with the LEAST effort?`,correct:[`Make no change, because the stateful security group lets the responses leave on its own`,`Responses to allowed inbound traffic are allowed to leave the instance regardless of the outbound rules.`],wrong:[[`Add an outbound rule that allows TCP port 443 to 0.0.0.0/0 so that responses can reach clients`,`The response goes back to the port the client chose, and no outbound rule is needed for it to leave a stateful security group.`],[`Add an outbound rule that allows TCP ports 1024-65535 to 0.0.0.0/0 for the client ephemeral ports`,`This extra rule is not needed, because the security group already lets responses to allowed inbound traffic leave.`],[`Add an outbound rule that allows all traffic to the VPC CIDR block only`,`It would not cover clients on the internet and it is not needed for responses to allowed requests.`]],slot:1,evidence:[`vpc-security-groups|Responses to allowed inbound traffic are allowed to leave the instance, regardless of the outbound rules.`]}),e({id:`gatehouse-003`,building:`gatehouse`,bullets:[`1.2-K3`],d:3,tags:[`trap:sg-vs-nacl`],stem:`A company hosts a public HTTPS website on Amazon EC2 instances in one subnet. An architect associates a new custom network ACL with the subnet and must add the rules that let the site work for clients on many operating systems while keeping the rule set small. Which TWO rules form the SIMPLEST rule set that meets these requirements? (Choose two.)`,correct:[[`Inbound rule: allow TCP port 443 from 0.0.0.0/0`,`It admits the HTTPS requests; the initial rules of a custom network ACL block all inbound traffic.`],[`Outbound rule: allow TCP ports 1024-65535 to 0.0.0.0/0`,`A network ACL is stateless, so the responses need an outbound rule, and the client chooses the ephemeral port that the response goes to.`]],wrong:[[`Inbound rule: allow TCP ports 1024-65535 from 0.0.0.0/0`,`This admits return traffic for requests that start inside the subnet, and the website only answers requests.`],[`Outbound rule: allow TCP port 443 to 0.0.0.0/0`,`Responses go to the ephemeral port of the client and not to port 443.`],[`Inbound rule: allow all traffic from the CIDR block of the subnet`,`It does not admit clients from the internet.`]],slots:[0,3],evidence:[`vpc-create-nacl|The initial rules for a custom network ACL block all inbound and outbound traffic.`,`vpc-custom-nacl|For every rule that you add, there must be an inbound or outbound rule that allows response traffic.`,`vpc-custom-nacl|In practice, to cover the different types of clients that might initiate traffic to public-facing instances in your VPC, you can open ephemeral ports 1024-65535.`]}),t({id:`gatehouse-004`,building:`gatehouse`,bullets:[`1.2-K3`],d:3,tags:[`trap:sg-vs-nacl`],stem:`The network ACL of a public subnet has inbound rule 100, which allows TCP port 443 from 0.0.0.0/0, and rule 200, which allows TCP port 80 from 0.0.0.0/0. The company must now block HTTPS requests that come from 198.51.100.0/24 while keeping port 443 open to all other sources. Which change meets this requirement with the LEAST effort?`,correct:[`Add an inbound rule numbered 90 that denies TCP port 443 from 198.51.100.0/24`,`Rules are evaluated from the lowest number, so the deny rule matches before rule 100 allows the traffic.`],wrong:[[`Add an inbound rule numbered 150 that denies TCP port 443 from 198.51.100.0/24`,`Rule 100 matches first and is applied, and no further rules are evaluated, so the deny rule is never reached.`],[`Add an inbound deny rule for 198.51.100.0/24 to the security group of the instances`,`A security group can hold allow rules only and cannot deny traffic.`],[`Associate a second network ACL that holds the deny rule with the same subnet`,`A subnet can be associated with only one network ACL, so this replaces rules 100 and 200.`]],slot:2,evidence:[`vpc-nacls|We evaluate the rules in order, starting with the lowest numbered rule, when deciding whether allow or deny traffic.`,`vpc-nacls|If the traffic matches a rule, the rule is applied and we do not evaluate any additional rules.`,`vpc-nacls|However, a subnet can be associated with only one network ACL at a time.`]}),t({id:`gatehouse-005`,building:`gatehouse`,bullets:[`1.2-K3`],d:2,tags:[`trap:sg-vs-nacl`],stem:`A solutions architect creates a custom network ACL for the database subnet of a VPC and associates it with the subnet. The security groups are unchanged, yet the application servers can no longer connect to the database on TCP port 5432. What is the MOST likely cause?`,correct:[`The initial rules of a custom network ACL block all inbound and outbound traffic`,`A new custom network ACL denies everything by default, so allow rules for the database port and its responses are required.`],wrong:[[`A security group must be recreated whenever a new network ACL is associated with its subnet`,`The two are independent controls, and associating a network ACL does not change a security group.`],[`The route table of the subnet must be replaced with the main route table of the VPC`,`Route tables direct traffic and have no effect on the rules of a network ACL.`],[`A network ACL takes effect only after it is associated with the entire VPC instead of a subnet`,`A network ACL is associated with subnets, and the association here already exists.`]],slot:3,evidence:[`vpc-create-nacl|The initial rules for a custom network ACL block all inbound and outbound traffic.`]}),e({id:`gatehouse-006`,building:`gatehouse`,bullets:[`1.2-K3`],d:2,tags:[`trap:sg-vs-nacl`],stem:`A three-tier application in a VPC has an Application Load Balancer, application servers that listen on TCP port 8080, and a database that listens on TCP port 5432. Each tier has its own security group. The application servers scale in and out, so their IP addresses change often. Each tier must accept traffic ONLY from the tier in front of it. Which TWO inbound rules meet these requirements with the LEAST ongoing effort? (Choose two.)`,correct:[[`Application server group: allow TCP port 8080 with the load balancer security group as the source`,`The rule applies to every instance in the referenced group, so it keeps working as the load balancer changes.`],[`Database group: allow TCP port 5432 with the application server security group as the source`,`The rule follows the application servers as they scale, so only that tier reaches the database.`]],wrong:[[`Application server group: allow TCP port 8080 from the CIDR block of the VPC`,`Every resource in the VPC could reach the application servers, not only the load balancer.`],[`Database group: allow TCP port 5432 from 0.0.0.0/0`,`Any source on the internet could try to reach the database.`],[`Application server group: allow TCP port 8080 from 0.0.0.0/0`,`Any source on the internet could bypass the load balancer.`]],slots:[1,4],evidence:[`vpc-sg-rules|When you specify a security group as the source or destination for a rule, the rule affects all instances that are associated with the security groups.`,`vpc-sg-rules|Add rules to the security group for the database servers to allow database requests from the web servers. The source is the security group for the web servers.`]}),t({id:`gatehouse-007`,building:`gatehouse`,bullets:[`1.2-K3`],d:1,stem:`Administrators must connect with SSH to Linux instances from the corporate network, which uses the public range 198.51.100.0/24. Which security group configuration is the MOST secure way to meet this requirement?`,correct:[`An inbound rule that allows only TCP port 22 from 198.51.100.0/24`,`It limits both the port and the source to what the administrators need.`],wrong:[[`An inbound rule that allows TCP port 22 from 0.0.0.0/0`,`It lets anyone on the internet try to connect over SSH.`],[`An inbound rule that allows TCP ports 0-65535 from 198.51.100.0/24`,`It opens a large port range when only port 22 is needed.`],[`An inbound rule that allows all traffic from 0.0.0.0/0 and ::/0`,`It lets anyone on the internet use any port and protocol.`]],slot:0,evidence:[`vpc-security-groups|When you add inbound rules for ports 22 (SSH) or 3389 (RDP) so that you can access your EC2 instances, authorize only specific IP address ranges.`,`vpc-security-groups|Do not open large port ranges.`]}),t({id:`gatehouse-008`,building:`gatehouse`,bullets:[`1.2-K3`],d:2,tags:[`trap:sg-vs-nacl`],stem:`An engineer adds a rule to the network ACL of the subnet that holds the backend Amazon EC2 instances of a load balancer. The rule denies all traffic whose source is that subnet's own CIDR block. Soon after, the load balancer reports every target as unhealthy. Which statement BEST explains the failure?`,correct:[`The deny rule stops the load balancer from carrying out health checks on the instances`,`A deny rule for the subnet CIDR block blocks the health check traffic that the load balancer sends to its targets.`],wrong:[[`The security groups of the instances cannot be used together with a custom network ACL`,`Security groups and network ACLs work together, so this does not explain the failure.`],[`A network ACL deny rule applies only to outbound traffic from the instances`,`A network ACL has inbound rules and outbound rules and a deny rule applies to the traffic it matches.`],[`Backend instances must be in a subnet that has no network ACL associated with it`,`Every subnet is associated with a network ACL, so this cannot be the cause.`]],slot:1,evidence:[`vpc-custom-nacl|With Elastic Load Balancing, if the subnet for your backend instances has a network ACL in which you've added a deny rule for all traffic with a source of either 0.0.0.0/0 or the subnet's CIDR, your load balancer can't carry out health checks on the instances.`]}),t({id:`gatehouse-009`,building:`gatehouse`,bullets:[`1.2-S1`],d:1,stem:`Application instances in a private subnet must download operating system updates from the internet. The instances must not accept connections that are initiated from the internet. Which solution is the MOST secure way to meet these requirements?`,correct:[`Create a NAT gateway in a public subnet and route the private subnet traffic for 0.0.0.0/0 to it`,`The instances can connect to services outside the VPC, and external services cannot initiate a connection with them.`],wrong:[[`Route the private subnet traffic for 0.0.0.0/0 straight to an internet gateway and assign public IPv4 addresses`,`Resources on the internet could then initiate connections to the instances.`],[`Create an egress-only internet gateway and route 0.0.0.0/0 to it`,`An egress-only internet gateway is for IPv6 traffic only and does not serve IPv4 updates.`],[`Move the instances to a public subnet and allow all outbound traffic in the security group`,`A public subnet with public addresses can be reached from the internet, which the company does not want.`]],slot:2,evidence:[`vpc-nat-gateway|You can use a NAT gateway so that instances in a private subnet can connect to services outside your VPC but external services can't initiate a connection with those instances.`,`vpc-egress-only-igw|To enable outbound-only internet communication over IPv4, use a NAT gateway instead.`]}),t({id:`gatehouse-010`,building:`gatehouse`,bullets:[`1.2-S1`],d:2,stem:`Application servers run in private subnets in three Availability Zones, and all of them route outbound traffic to a single NAT gateway in Availability Zone A. During an event in Availability Zone A, the servers in the other zones lost internet access. Which change provides the HIGHEST availability for outbound access?`,correct:[`Create a NAT gateway in every Availability Zone and route each subnet to the local one`,`A zone failure then affects only the resources in that zone, and each zone keeps its own path to the internet.`],wrong:[[`Associate a second Elastic IP address with the existing NAT gateway`,`The NAT gateway is still created in a single Availability Zone, so a zone failure still removes it.`],[`Create a second NAT gateway in Availability Zone A and split the subnets between the two`,`Both gateways are still in the failed zone, so the other zones would still lose access.`],[`Replace the NAT gateway with a new one in Availability Zone B and route all of the subnets to it`,`It would still be one NAT gateway in one Availability Zone, so a failure of that zone removes outbound access for the subnets in the other zones.`]],slot:3,evidence:[`vpc-nat-basics|If you have resources in multiple Availability Zones and they share one NAT gateway, and if the NAT gateway's Availability Zone is down, resources in the other Availability Zones lose internet access.`,`vpc-nat-basics|To improve resiliency, create a NAT gateway in each Availability Zone, and configure your routing to ensure that resources use the NAT gateway in the same Availability Zone.`]}),t({id:`gatehouse-011`,building:`gatehouse`,bullets:[`1.2-S1`],d:2,tags:[`trap:nat-gateway-vs-instance`],stem:`A company needs outbound internet access for instances in private subnets. The operations team does not want to patch the NAT software or write failover scripts. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`A NAT gateway in a public subnet`,`AWS manages a NAT gateway, so there is no maintenance, and it requires less effort to administer.`],wrong:[[`A NAT instance in a public subnet with a script for failover`,`The team would patch the instance and maintain the failover script, which is the work it wants to avoid.`],[`An Amazon EC2 bastion host in a public subnet with port forwarding`,`The team would have to configure and patch the host, and a bastion host is not a managed NAT service.`],[`An internet gateway route with public IPv4 addresses on the instances`,`It exposes the instances to inbound connections from the internet.`]],slot:0,evidence:[`vpc-nat-comparison|We recommend that you use NAT gateways because they provide better availability and bandwidth and require less effort on your part to administer.`,`vpc-nat-comparison|Managed by AWS. You do not need to perform any maintenance.`]}),t({id:`gatehouse-012`,building:`gatehouse`,bullets:[`1.2-S1`],d:3,tags:[`trap:nat-gateway-vs-instance`],stem:`A company routes the outbound traffic of its private subnets through a NAT gateway. A new policy says that instances may send only HTTPS traffic to the internet, and the company wants to keep the managed NAT gateway. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Limit the outbound rules of the security groups of the instances to TCP port 443`,`Security groups attach to the instances behind the NAT gateway, so they can control the outbound traffic of those instances.`],wrong:[[`Associate a security group that allows only TCP port 443 with the NAT gateway`,`You cannot associate a security group with a NAT gateway.`],[`Replace the NAT gateway with a NAT instance only so that a security group can be attached`,`The company wants to keep the managed NAT gateway, and this adds maintenance work.`],[`Create an egress-only internet gateway with a rule for TCP port 443`,`An egress-only internet gateway is for IPv6 traffic only and cannot take a security group.`]],slot:1,evidence:[`vpc-nat-basics|You can't associate a security group with a NAT gateway. You can associate security groups with your instances to control inbound and outbound traffic.`,`vpc-egress-only-igw|You can't associate a security group with an egress-only internet gateway to control the traffic that is allowed to reach or leave the egress-only internet gateway.`]}),t({id:`gatehouse-013`,building:`gatehouse`,bullets:[`1.2-S1`],d:2,stem:`An architect creates a public NAT gateway in a private subnet and adds a route for 0.0.0.0/0 to it in the route table of the application subnet. The application instances still cannot reach the internet. What is the SIMPLEST way to fix this?`,correct:[`Create the public NAT gateway in a public subnet that routes to the internet gateway`,`A public NAT gateway belongs in a public subnet, and its traffic is routed on to the internet gateway of the VPC.`],wrong:[[`Attach a security group that allows outbound HTTPS to the NAT gateway`,`You cannot associate a security group with a NAT gateway, and the problem is where the gateway sits.`],[`Give every application instance an Elastic IP address instead of using the NAT gateway`,`That makes the instances reachable from the internet and does not fix the gateway placement.`],[`Add a route for 0.0.0.0/0 to the local target in the application route table`,`The local route only covers traffic inside the VPC, so it cannot reach the internet.`]],slot:2,evidence:[`vpc-nat-gateway|You create a public NAT gateway in a public subnet and must associate an Elastic IP address with the NAT gateway at creation. You route traffic from the NAT gateway to the internet gateway for the VPC.`]}),t({id:`gatehouse-014`,building:`gatehouse`,bullets:[`1.2-S1`],d:3,tags:[`trap:gateway-vs-interface-endpoints`],stem:`Application servers in private subnets send large volumes of data to Amazon S3 through a NAT gateway. The company wants this traffic to avoid the internet and the NAT gateway, at the LOWEST cost and with no change to the servers. Which solution meets these requirements?`,correct:[`Create a gateway VPC endpoint for Amazon S3 and add it to the private route tables`,`A gateway endpoint reaches S3 without an internet gateway or NAT device, and there is no additional charge for it.`],wrong:[[`Create an interface VPC endpoint for Amazon S3 in each Availability Zone`,`An interface endpoint is not the lowest cost option, because the gateway endpoint for S3 has no additional charge.`],[`Create another NAT gateway in each Availability Zone for the S3 traffic to share the load`,`Traffic would still pass through NAT gateways and their data processing.`],[`Move the servers to a public subnet and send the S3 traffic through the internet gateway`,`The traffic would travel over the internet and the servers would be exposed to inbound connections.`]],slot:3,evidence:[`vpce-gateway|Gateway VPC endpoints provide reliable connectivity to Amazon S3 and DynamoDB without requiring an internet gateway or a NAT device for your VPC.`,`vpce-gateway|There is no additional charge for using gateway endpoints.`,`vpc-route-options|You can also create more specific routes to other targets to avoid unnecessary data processing charges for using a NAT gateway, or to route certain traffic privately.`]}),e({id:`gatehouse-015`,building:`gatehouse`,bullets:[`1.2-S1`],d:2,stem:`A company launches an Amazon EC2 web server in a new subnet of a nondefault VPC, and the server must be reachable from the internet over IPv4. An internet gateway is attached to the VPC. Which TWO additional steps are required? (Choose two.)`,correct:[[`Add a route for 0.0.0.0/0 that targets the internet gateway to the route table of the subnet`,`The subnet then has a direct route to the internet gateway, which makes it a public subnet.`],[`Give the instance a public IPv4 address or an Elastic IP address`,`For IPv4 communication over the internet gateway, the instance needs a public IPv4 address.`]],wrong:[[`Create a NAT gateway in the subnet and route 0.0.0.0/0 to it`,`A NAT gateway serves outbound-only connections from private subnets and does not make the server reachable.`],[`Create an egress-only internet gateway and add a route for ::/0 to it`,`It is for outbound IPv6 traffic only and prevents the internet from initiating connections.`],[`Create a VPC peering connection to the default VPC and route through it`,`Peering connects VPCs and does not provide a path to the internet.`]],slots:[2,4],evidence:[`vpc-route-options|To do this, create and attach an internet gateway to your VPC, and then add a route with a destination of 0.0.0.0/0 for IPv4 traffic or ::/0 for IPv6 traffic, and a target of the internet gateway ID (igw-xxxxxxxxxxxxxxxxx).`,`vpc-igw|To enable communication over the internet for IPv4, your instance must have a public IPv4 address.`]}),t({id:`gatehouse-016`,building:`gatehouse`,bullets:[`1.2-S1`],d:2,stem:`A subnet route table has three routes: 10.0.0.0/16 to local, 172.31.0.0/16 to a VPC peering connection, and 0.0.0.0/0 to an internet gateway. An instance in the subnet sends a packet to 172.31.4.20. Where does the VPC send the packet?`,correct:[`To the VPC peering connection, because that route is the most specific match`,`AWS directs traffic using the most specific route that matches, known as the longest prefix match.`],wrong:[[`To the internet gateway, because 0.0.0.0/0 is the default route for all traffic`,`The default route is used only when no more specific route matches.`],[`To the local target, because every packet from the subnet is first delivered inside the VPC`,`The local route covers only destinations within 10.0.0.0/16, and 172.31.4.20 is outside it.`],[`To the internet gateway first, with the peering connection used if that route fails`,`The route table has no fallback order between targets and the most specific route wins.`]],slot:0,evidence:[`vpc-route-priority|In general, we direct traffic using the most specific route that matches the traffic. This is known as the longest prefix match.`,`vpc-route-priority|Any traffic from the subnet that's destined for the 172.31.0.0/16 IP address range uses the peering connection, because this route is more specific than the route for internet gateway.`]}),t({id:`gatehouse-017`,building:`gatehouse`,bullets:[`1.2-S2`],d:1,stem:`A team asks how to tell a public subnet from a private subnet in a VPC. Which characteristic defines a public subnet?`,correct:[`Its route table has a direct route to an internet gateway`,`The route table makes a subnet public, and resources in a public subnet can access the public internet.`],wrong:[[`Its CIDR block belongs to a public IP address range`,`Routing, not the address range, decides the subnet type.`],[`Its network ACL allows all inbound and outbound traffic`,`A network ACL filters traffic and does not decide whether a subnet has a route to the internet.`],[`It hosts at least one NAT gateway`,`A NAT gateway often sits in a public subnet, but its presence does not define the subnet type.`]],slot:1,evidence:[`vpc-subnets|Public subnet – The subnet has a direct route to an internet gateway. Resources in a public subnet can access the public internet.`,`vpc-subnets|Private subnet – The subnet does not have a direct route to an internet gateway.`]}),e({id:`gatehouse-018`,building:`gatehouse`,bullets:[`1.2-S2`],d:2,stem:`A company runs a database on Amazon EC2 instances. The database must be reachable only from the application servers of the same VPC and never from the internet. Which TWO actions meet these requirements in the MOST secure way? (Choose two.)`,correct:[[`Launch the database instances in private subnets that have no direct route to an internet gateway`,`A private subnet does not have a direct route to an internet gateway, so the internet cannot reach the instances.`],[`Allow the database port in the database security group only from the security group of the application servers`,`A security group rule can name another security group as its source, which limits access to that tier.`]],wrong:[[`Launch the database instances in a public subnet and assign Elastic IP addresses`,`A public subnet with public addresses can be reached from the internet.`],[`Allow the database port from 0.0.0.0/0 in the security group and rely on database passwords`,`It leaves the database open to every source on the internet.`],[`Create an egress-only internet gateway and route all IPv4 traffic through it`,`An egress-only internet gateway handles IPv6 traffic only and is not a way to isolate a tier.`]],slots:[0,2],evidence:[`vpc-subnets|Private subnet – The subnet does not have a direct route to an internet gateway.`,`vpc-sg-rules|When you specify a security group as the source or destination for a rule, the rule affects all instances that are associated with the security groups.`]}),t({id:`gatehouse-019`,building:`gatehouse`,bullets:[`1.2-S2`],d:1,stem:`A company deploys a web tier on Amazon EC2 instances that must keep running if one Availability Zone fails. How should the architect lay out the subnets for this tier to achieve the HIGHEST availability?`,correct:[`Create at least one subnet for the tier in each Availability Zone it uses`,`A subnet resides entirely within one Availability Zone and cannot span zones.`],wrong:[[`Create one subnet in one Availability Zone and use EC2 Auto Scaling to replace failed instances in it`,`The subnet and every replacement instance stay in one Availability Zone, so a failure of that zone stops the whole tier.`],[`Create one subnet and let the VPC place its addresses across zones`,`Each subnet is tied to a single zone when it is created.`],[`Create one subnet and add a second CIDR block for the other zone`,`Adding an address range does not move the subnet to another zone.`]],slot:2,evidence:[`vpc-subnets|Each subnet must reside entirely within one Availability Zone and cannot span zones.`,`vpc-subnets|By launching AWS resources in separate Availability Zones, you can protect your applications from the failure of a single Availability Zone.`]}),t({id:`gatehouse-020`,building:`gatehouse`,bullets:[`1.2-S2`],d:3,tags:[`trap:sg-vs-nacl`],stem:`A security team requires that SMB (TCP port 445) is never reachable from the internet for any resource in the workload subnets, even if an engineer launches an instance with an overly permissive security group. The team wants a single control with the LEAST ongoing effort. Which solution meets these requirements?`,correct:[`Add an inbound deny rule for TCP port 445 to the network ACL of the workload subnets`,`A network ACL applies to the whole subnet and can deny traffic, so it works as a guard rail for every instance.`],wrong:[[`Add an inbound deny rule for TCP port 445 to the default security group`,`A security group cannot deny, and instances can be launched with other groups.`],[`Review the security group of every new instance by hand before it is launched`,`It depends on a manual step for each instance, which is the ongoing effort the team wants to avoid.`],[`Remove the allow rule for TCP port 445 from the security group of each current instance`,`It covers only current instances and not instances launched later with a permissive group.`]],slot:3,evidence:[`vpc-infra-security|Network ACLs can be effective as a secondary control (for example, to deny a specific subset of traffic) or as high-level subnet guard rails.`,`vpc-infra-security|Also, because network ACLs apply to an entire subnet, they can be used as defense-in-depth in case an instance is ever launched without the correct security group.`]}),t({id:`gatehouse-021`,building:`gatehouse`,bullets:[`1.2-S2`],d:2,stem:`A subnet is associated with network ACL A. An administrator then associates network ACL B with the same subnet. What is the result?`,correct:[`Network ACL A is no longer associated, and only network ACL B controls the subnet`,`A subnet can be associated with only one network ACL at a time, and a new association removes the previous one.`],wrong:[[`Both network ACLs are evaluated, with the lower rule number winning across them`,`Only one network ACL applies to a subnet at a time, so there is no combined evaluation.`],[`The association fails until network ACL A is deleted`,`The new association is accepted and replaces the old one.`],[`Network ACL B is stored, and network ACL A stays in force until the subnet is restarted`,`Subnets are not restarted, and the association changes directly.`]],slot:0,evidence:[`vpc-nacls|You can associate a network ACL with multiple subnets. However, a subnet can be associated with only one network ACL at a time. When you associate a network ACL with a subnet, the previous association is removed.`]}),e({id:`gatehouse-022`,building:`gatehouse`,bullets:[`1.2-S1`,`1.2-S2`],d:3,stem:`A company designs a VPC across two Availability Zones for a web application. Only the load balancer may accept connections from the internet. The application servers need outbound internet access for updates, and the database servers must have no path to the internet. Which THREE actions create the MOST secure design that meets these requirements? (Choose three.)`,correct:[[`Place the Application Load Balancer in public subnets, one in each Availability Zone`,`Public subnets route to an internet gateway, which the internet-facing load balancer needs.`],[`Place the application servers in private subnets and route 0.0.0.0/0 to a NAT gateway in a public subnet`,`The servers can connect out for updates, and external services cannot initiate a connection with them.`],[`Place the database servers in private subnets whose route tables have no route to an internet gateway or NAT gateway`,`Without such a route, the database tier has no path to the internet.`]],wrong:[[`Place the application servers in public subnets with Elastic IP addresses`,`This would make the servers reachable from the internet, not only the load balancer.`],[`Place the database servers in private subnets and route 0.0.0.0/0 to the NAT gateway`,`A route to the NAT gateway gives the database servers a path to the internet.`],[`Place the application servers in private subnets and route 0.0.0.0/0 to an egress-only internet gateway`,`An egress-only internet gateway handles IPv6 traffic only and does not serve IPv4 updates.`]],slots:[1,3,5],evidence:[`vpc-subnets|Public subnet – The subnet has a direct route to an internet gateway.`,`vpc-route-options|Then add a route for the private subnet's route table that routes IPv4 internet traffic (0.0.0.0/0) to the NAT device.`,`vpc-egress-only-igw|An egress-only internet gateway is for use with IPv6 traffic only.`]}),t({id:`gatehouse-023`,building:`gatehouse`,bullets:[`1.2-S2`],d:2,stem:`An Amazon EC2 instance in a private subnet has a public IPv4 address, but users on the internet still cannot connect to it. The security group allows the traffic. Which reason BEST explains this?`,correct:[`The route table of the subnet has no route to an internet gateway`,`With no route to an internet gateway, instances cannot communicate with the internet even when they have public IP addresses.`],wrong:[[`The instance needs a NAT gateway to accept inbound connections from the internet`,`A NAT gateway serves outbound connections and does not accept inbound ones.`],[`Public IPv4 addresses work only in subnets that have a custom network ACL associated`,`Addressing does not depend on the type of network ACL, and every subnet has one.`],[`The security group must also be attached to the internet gateway`,`A security group is associated with resources such as instances and not with an internet gateway.`]],slot:1,evidence:[`vpc-igw|Because there is no route to the internet gateway, instances in the private subnet can't communicate with the internet, even if they have public IP addresses.`]}),t({id:`gatehouse-024`,building:`gatehouse`,bullets:[`1.2-K3`],d:2,tags:[`mock-reserve`],stem:`An Amazon EC2 instance is associated with two security groups. The first group allows TCP port 443 from 0.0.0.0/0, and the second allows TCP port 22 from 198.51.100.0/24. Which traffic can reach the instance?`,correct:[`HTTPS from any source and SSH from 198.51.100.0/24, because the rules are combined`,`The rules from each security group are aggregated into one set that decides whether to allow access.`],wrong:[[`Only traffic that both groups allow, so no inbound traffic is accepted`,`Rules are aggregated rather than intersected, so each allow rule still applies.`],[`Only the rules of the security group that was associated with the instance first, not the second`,`All associated groups apply, not just the first one.`],[`HTTPS from any source only, because SSH rules apply only to a single group`,`A resource can have several groups, and the SSH rule in the second group still applies.`]],slot:2,evidence:[`vpc-sg-rules|When you associate multiple security groups with a resource, the rules from each security group are aggregated to form a single set of rules that are used to determine whether to allow access.`]}),t({id:`gatehouse-025`,building:`gatehouse`,bullets:[`1.2-S1`],d:3,tags:[`mock-reserve`,`trap:nat-gateway-vs-instance`],stem:`A company runs workloads in private subnets in three Availability Zones. All of them route outbound internet traffic to one NAT gateway in a public subnet in a single zone. The company wants outbound internet access to survive the failure of one Availability Zone. Each zone must use its own NAT gateway with its own Elastic IP address, so that the company can allowlist the addresses with partners zone by zone. Which solution meets these requirements?`,correct:[`Create a NAT gateway in each zone and route each private subnet to the gateway in its own zone`,`A NAT gateway in each zone keeps the zones independent, so the loss of one zone does not remove internet access for the others.`],wrong:[[`Create a second NAT gateway in the same public subnet and route half of the private subnets to it`,`Both gateways are in the same Availability Zone, so a failure of that zone still removes internet access for all workloads.`],[`Run NAT instances in an Auto Scaling group in each Availability Zone`,`The team would patch the instances and maintain failover, and the requirement is for a NAT gateway with its own Elastic IP address in each zone.`],[`Create a private NAT gateway in one Availability Zone and route all zones to it`,`A private NAT gateway is for private connectivity and does not provide internet access, and it sits in a single zone.`]],slot:3,evidence:[`vpc-nat-basics|If you have resources in multiple Availability Zones and they share one NAT gateway, and if the NAT gateway's Availability Zone is down, resources in the other Availability Zones lose internet access.`,`vpc-nat-comparison|Create a NAT gateway in each Availability Zone to ensure zone-independent architecture.`]}),t({id:`gatehouse-026`,building:`gatehouse`,bullets:[`1.2-S1`],d:2,tags:[`mock-reserve`],stem:`A VPC has both IPv4 and IPv6 CIDR blocks. Instances in a private subnet use IPv6 addresses and must download updates from the internet, while the internet must not be able to start an IPv6 connection to them. Which solution is the SIMPLEST that meets these requirements?`,correct:[`An egress-only internet gateway with a route for ::/0 in the subnet route table`,`It allows outbound IPv6 communication and prevents the internet from initiating an IPv6 connection.`],wrong:[[`An internet gateway with a route for ::/0 in the subnet route table`,`IPv6 addresses are public by default, so the internet could initiate connections to the instances.`],[`A public NAT gateway with an Elastic IP address and a route for ::/0`,`A NAT gateway performs NAT64 for IPv6 workloads that reach IPv4 resources; it does not provide outbound-only IPv6-to-IPv6 access, which is what the instances need and what the egress-only internet gateway provides.`],[`A security group rule that denies all inbound IPv6 traffic on the instances`,`A security group cannot hold deny rules, and it provides no outbound path.`]],slot:0,evidence:[`vpc-egress-only-igw|An egress-only internet gateway is a horizontally scaled, redundant, and highly available VPC component that allows outbound communication over IPv6 from instances in your VPC to the internet, and prevents the internet from initiating an IPv6 connection with your instances.`]}),t({id:`gatehouse-027`,building:`gatehouse`,bullets:[`1.2-S2`],d:2,tags:[`mock-reserve`],stem:`A company connects an on-premises network to a VPC with an AWS Site-to-Site VPN connection through a virtual private gateway. A reporting tier in the VPC must be reachable only from the on-premises network and must have no path to the internet. Which subnet design is the SIMPLEST way to meet these requirements?`,correct:[`A subnet that routes to the virtual private gateway and has no internet gateway route`,`This is a VPN-only subnet, which reaches the VPN connection and has no route to an internet gateway.`],wrong:[[`A public subnet whose route table sends 0.0.0.0/0 to an internet gateway for the tier`,`It gives the tier a direct route to the internet gateway.`],[`A subnet with a route to an internet gateway and the VPN routes disabled`,`It still has a route to the internet gateway, and the tier could not use the VPN.`],[`A public subnet that also hosts a NAT gateway for the reporting tier`,`A public subnet has a route to the internet gateway, which is not allowed here.`]],slot:1,evidence:[`vpc-subnets|VPN-only subnet – The subnet has a route to a Site-to-Site VPN connection through a virtual private gateway. The subnet does not have a route to an internet gateway.`]})],u=[t({id:`identity-keep-001`,building:`identity-keep`,bullets:[`1.1-K4`],d:1,stem:`A company's data analysts need to download report files from a single prefix in one Amazon S3 bucket. An administrator is writing the IAM policy for the analysts. Which policy BEST follows the principle of least privilege?`,correct:[`A policy that allows only s3:GetObject on the objects under that prefix`,`It grants only the action the analysts need on the specific resources they use, which is what least privilege means.`],wrong:[[`A policy that allows s3:* on every bucket in the account`,`It grants far more actions and far more resources than the analysts need for downloading reports.`],[`A policy that allows s3:GetObject and s3:PutObject on the whole bucket`,`Uploading is not required, and the whole bucket is wider than the single prefix the analysts use.`],[`The AWS managed AmazonS3FullAccess policy attached to the analysts`,`It gives full access to Amazon S3, which is much broader than reading files from one prefix.`]],slot:0,evidence:[`iam-best-practices|When you set permissions with IAM policies, grant only the permissions required to perform a task.`,`iam-best-practices|You do this by defining the actions that can be taken on specific resources under specific conditions, also known as least-privilege permissions.`]}),t({id:`identity-keep-002`,building:`identity-keep`,bullets:[`1.1-S1`],d:1,stem:`A startup created its AWS account a month ago, and the founder still signs in as the account root user for all daily work. The founder wants to follow AWS guidance to MOST improve the security of the account. What should the founder do?`,correct:[`Create an administrative user for daily work and keep the root user for root-only tasks`,`AWS recommends an administrative user for everyday tasks and root user sign-in only for tasks that require root-level permissions.`],wrong:[[`Keep using the root user for daily work, but change its password every 30 days and log each sign-in`,`The root user has complete access to the account, so using it daily stays risky no matter how often the password changes.`],[`Create access keys for the root user and run all daily work from the AWS CLI instead of the console`,`AWS strongly recommends not creating access keys for the root user because it has full access to everything.`],[`Share the root user credentials with two more administrators so that the risk is spread across the team`,`More people holding the most powerful credentials increases exposure instead of reducing the use of the root user.`]],slot:1,evidence:[`iam-root-best-practices|Instead of accessing the root user, create an administrative user for everyday tasks.`,`iam-root-user|Use the root user only to perform the tasks that require root-level permissions.`]}),t({id:`identity-keep-003`,building:`identity-keep`,bullets:[`1.1-S2`],d:1,stem:`A company hires several new developers each quarter. All developers need the same permissions to a set of AWS services, and the administrators want to manage those permissions in one place with the LEAST effort. Which solution meets these requirements?`,correct:[`Create an IAM user group with the permissions policy and add each developer to it`,`Every user in the group receives the policy permissions, and a new developer only has to be added to the group.`],wrong:[[`Attach the same permissions policy to every developer IAM user one by one as each person joins`,`Each new hire needs another attachment, and a permission change has to be repeated user by user.`],[`Create one shared IAM user with the permissions policy and give its credentials to every developer`,`Sharing one identity gives no individual identity per developer and does not use a group to manage permissions.`],[`Create an IAM role for each developer and give each role its own inline policy`,`An inline policy is tied to a single identity, so every change has to be repeated for each role.`]],slot:2,evidence:[`iam-groups|User groups let you specify permissions for multiple users, which can make it easier to manage the permissions for those users.`,`iam-groups|If a new user joins your organization and needs administrator privileges you can assign the appropriate permissions by adding the user to the Admins user group.`]}),t({id:`identity-keep-004`,building:`identity-keep`,bullets:[`1.1-S1`],d:1,stem:`A security policy requires every IAM user in an AWS account to choose a console password that meets a minimum complexity. An administrator wants to enforce this for all IAM users with the SIMPLEST approach. What should the administrator do?`,correct:[`Set a password policy for the account`,`A password policy enforces a minimum password complexity for the IAM users of the account.`],wrong:[[`Require MFA for every IAM user in the account`,`MFA adds a second factor at sign-in but sets no rule about how complex the password must be.`],[`Attach a permissions boundary to every IAM user in the account`,`A permissions boundary limits the maximum permissions of an identity and has no effect on password rules.`],[`Put all IAM users in a group that has an inline policy attached`,`A group policy grants or denies permissions and does not enforce password complexity.`]],slot:3,evidence:[`iam-users|Set a password policy to enforce a minimum password complexity.`,`iam-users|Create and change the passwords that permit access to the AWS Management Console.`]}),t({id:`identity-keep-005`,building:`identity-keep`,bullets:[`1.1-K4`],d:2,stem:`A company has 300 employees who need console and CLI access to workloads in five AWS accounts. The company wants people to use temporary credentials and to manage access from one place with the LEAST administrative effort. Which solution BEST meets these requirements?`,correct:[`Use AWS IAM Identity Center to manage workforce access to the accounts`,`AWS recommends IAM Identity Center for centralized access management, and federated users receive temporary credentials.`],wrong:[[`Create an IAM user for each employee in every account and require MFA`,`It creates about 1,500 identities with long-term credentials that are managed account by account.`],[`Create one shared IAM user per account and distribute its access keys`,`Shared long-term access keys are not temporary credentials and give no individual identity per employee.`],[`Create employee IAM users in one account and copy their access keys into the other four`,`The employees keep long-term credentials, and the keys must be copied and maintained in every account.`]],slot:0,evidence:[`iam-best-practices|Require your human users to use temporary credentials when accessing AWS.`,`iam-best-practices|For centralized access management, we recommend that you use AWS IAM Identity Center (IAM Identity Center) to manage access to your accounts and permissions within those accounts.`]}),t({id:`identity-keep-006`,building:`identity-keep`,bullets:[`1.1-S1`,`1.1-K4`],d:2,stem:`A nightly script on an Amazon EC2 instance copies files to an Amazon S3 bucket. The script signs its requests with access keys that belong to the account root user. Which change MOST improves security with the LEAST disruption to the script?`,correct:[`Delete the root access keys and attach an IAM role with S3 permissions to the instance`,`The role gives the instance temporary credentials, and no root access keys remain to be stolen.`],wrong:[[`Rotate the root access keys every 90 days and keep them in an encrypted file`,`Root access keys would still exist, and the root user has full access to the account.`],[`Store the root access keys in AWS Secrets Manager and have the script read them`,`The script still uses root access keys, which AWS strongly recommends not to create.`],[`Create an IAM user with AdministratorAccess and store its access keys in the script configuration file`,`It replaces root keys with long-term keys that have far more permissions than copying files needs.`]],slot:1,evidence:[`iam-root-best-practices|We strongly recommend that you do not create access keys for your root user because the root user has full access to all AWS services and resources in the account, including billing information.`,`iam-best-practices|When you're building on an AWS compute service, such as Amazon EC2 or Lambda, AWS delivers the temporary credentials of an IAM role to that compute resource.`]}),e({id:`identity-keep-007`,building:`identity-keep`,bullets:[`1.1-S1`],d:2,stem:`A company requires IAM users with administrator permissions to use MFA, and administrator actions must be denied when the user has not signed in with MFA. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Assign a unique MFA device to each administrator IAM user`,`Each administrator then has a second factor, and every MFA device assigned to a user must be unique.`],[`Attach a policy to the administrators that denies actions unless aws:MultiFactorAuthPresent is true`,`A policy must include the aws:MultiFactorAuthPresent condition key to enforce the use of MFA.`]],wrong:[[`Assign one hardware TOTP token to the whole administrator team to share`,`Each MFA device assigned to a user must be unique, so a token cannot be shared between users.`],[`Require a longer password for each administrator and rotate it every 30 days`,`Password rules are not MFA, and they do not deny actions when MFA was not used.`],[`Enable MFA for the account root user only`,`It protects the root user but does not require MFA for the administrator IAM users.`]],slots:[0,3],evidence:[`iam-mfa|Each MFA device assigned to a user must be unique.`,`iam-mfa-require-api|A policy must include the aws:MultiFactorAuthPresent condition key to enforce the use of MFA.`]}),t({id:`identity-keep-008`,building:`identity-keep`,bullets:[`1.1-K4`],d:2,stem:`An IAM policy lets several users read and write objects in an Amazon S3 bucket. The security team now requires these permissions to apply only when the requests are sent using TLS. Which solution meets this requirement with the LEAST change to the policy design?`,correct:[`Add a Condition element to the policy statement that requires requests to use TLS`,`A condition makes the statement apply only when the request meets it, such as being sent using TLS.`],wrong:[[`Add a Principal element to the policy that names TLS as the allowed protocol`,`An identity-based policy cannot use the Principal element, which identifies who, not the protocol.`],[`Attach a permissions boundary that lists the same S3 actions as the policy`,`A boundary caps the maximum permissions of an identity and does not check how a request was sent.`],[`Move the users into an IAM group and attach the policy to the group instead`,`Grouping changes how permissions are assigned but adds no check on the protocol of the request.`]],slot:2,evidence:[`iam-best-practices|That way, you can grant access to actions and resources, but only if the access request meets specific conditions.`,`iam-best-practices|For example, you can write a policy condition to specify that all requests must be sent using TLS.`,`iam-el-principal|You cannot use the Principal element in an identity-based policy.`]}),t({id:`identity-keep-009`,building:`identity-keep`,bullets:[`1.1-K4`],d:2,stem:`A security team wants to be told continuously when a resource in its AWS account, such as an Amazon S3 bucket or an IAM role, can be accessed publicly or from another AWS account. The team wants the LEAST operational effort. Which service should the team use?`,correct:[`IAM Access Analyzer`,`It monitors supported resource types continuously and generates a finding for resources that allow public or cross-account access.`],wrong:[[`Amazon Inspector`,`Amazon Inspector scans workloads for software vulnerabilities and does not report who can access a resource.`],[`AWS CloudTrail Event history`,`It is a record of past management events, not an analysis of which principals a resource allows.`],[`Amazon GuardDuty`,`GuardDuty is a threat detection service and does not analyze the access that resource policies grant.`]],slot:3,evidence:[`iam-best-practices|IAM Access Analyzer also monitors supported resource types continuously and generates a finding for resources that allow public or cross-account access.`,`iam-best-practices|Before you grant permissions for public or cross-account access in AWS, we recommend that you verify if such access is required.`]}),e({id:`identity-keep-010`,building:`identity-keep`,bullets:[`1.1-K4`],d:1,stem:`A company is reviewing how it uses IAM before a security audit. Which THREE actions are the BEST fit with AWS security best practices? (Choose three.)`,correct:[[`Give applications that run on Amazon EC2 instances an IAM role instead of IAM user access keys`,`AWS delivers the temporary credentials of the role to the instance, so no long-lived keys are distributed.`],[`Let workforce users sign in through an identity provider and receive temporary credentials`,`AWS recommends federated access for human users, which provides temporary credentials.`],[`Require MFA for every IAM user and for the root user`,`AWS says to require MFA wherever an IAM user or root user is needed.`]],wrong:[[`Create one IAM user with long-term access keys that all developers share`,`Long-term shared keys are the opposite of temporary credentials and give no individual identity.`],[`Embed access keys in the application source code so deployments need no setup`,`Long-lived keys in code are exactly what IAM roles for workloads are meant to avoid.`],[`Create access keys for the root user so administrators can use the AWS CLI`,`AWS strongly recommends not creating access keys for the root user.`]],slots:[1,2,4],evidence:[`iam-best-practices|Applications written using an AWS SDK will discover and use these temporary credentials to access AWS resources, and there is no need to distribute long lived credentials for an IAM user to your workloads running on AWS.`,`iam-best-practices|You can use an identity provider for your human users to provide federated access to AWS accounts by assuming roles, which provide temporary credentials.`,`iam-best-practices|However, for scenarios in which you need an IAM user or root user in your account, require MFA for additional security.`]}),t({id:`identity-keep-011`,building:`identity-keep`,bullets:[`1.1-S2`],d:2,tags:[`trap:iam-roles-vs-resource-policies`],stem:`A company wants all members of the IAM user group Analysts, in the same AWS account, to read objects in an Amazon S3 bucket. An administrator wrote a bucket policy that names the Analysts group as the Principal, and it does not work. Which fix is the SIMPLEST?`,correct:[`Attach an identity-based policy that allows reading the bucket to the Analysts group`,`Group members receive the policy permissions, and in one account an allow from an identity-based policy is enough.`],wrong:[[`Rewrite the bucket policy to name the ARN of every analyst IAM user as a principal`,`It can work, but the bucket policy must be edited whenever someone joins or leaves, which is more effort.`],[`Create an IAM role that trusts the Analysts group as a principal and have analysts assume it`,`A group cannot be identified as a principal in a policy, because groups relate to permissions, not authentication.`],[`Attach the existing bucket policy to the Analysts group instead of to the S3 bucket itself`,`A resource-based policy is attached to a resource, not to a group, so this is not possible.`]],slot:0,evidence:[`iam-groups|You cannot identify a user group as a Principal in a policy (such as a resource-based policy) because groups relate to permissions, not authentication, and principals are authenticated IAM entities.`,`iam-eval-logic|If an action is allowed by an identity-based policy, a resource-based policy, or both, then AWS allows the action.`]}),t({id:`identity-keep-012`,building:`identity-keep`,bullets:[`1.1-S2`],d:2,stem:`Members of the IAM group Contractors get s3:* on all buckets from the AWS managed AmazonS3FullAccess policy. A new rule says contractors must never be able to delete objects in the audit-logs bucket, even if another policy allows it. What is the SIMPLEST way to meet this rule?`,correct:[`Attach a policy to the group that explicitly denies s3:DeleteObject on audit-logs`,`An explicit deny in any of the policies overrides the allow, so no other policy can restore the delete permission.`],wrong:[[`Edit AmazonS3FullAccess to remove s3:DeleteObject for the audit-logs bucket`,`The permissions of an AWS managed policy cannot be changed.`],[`Attach a second policy to the group that allows only the other S3 actions on audit-logs`,`Policies are combined with a logical OR, so the existing s3:* allow still permits deleting.`],[`Attach a permissions boundary that blocks s3:DeleteObject to the Contractors group`,`A permissions boundary can be set only for a user or a role, not for a group.`]],slot:1,evidence:[`iam-policy-eval-basics|An explicit deny in any of the policies overrides the allow.`,`iam-managed-inline|You cannot change the permissions defined in AWS managed policies.`,`iam-policies|If multiple policies apply to a request, AWS applies a logical OR across all of those policies when evaluating them.`,`iam-policies|Use a managed policy as the permissions boundary for an IAM entity (user or role).`]}),e({id:`identity-keep-013`,building:`identity-keep`,bullets:[`1.1-S2`],d:2,stem:`A company has a Developers team and a QA team, and some engineers work on both. The company wants to manage the permissions of each team in one place with the LEAST effort. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create one IAM user group per team and attach each team's permissions policy to its group`,`Permissions are specified once on the group and apply to every user in it.`],[`Add the engineers who work on both teams to both groups`,`A user can belong to multiple user groups, so these engineers receive the permissions of each team.`]],wrong:[[`Create an Everyone group and nest the Developers and QA groups inside it`,`User groups can't be nested; they can contain only users, not other IAM groups.`],[`Attach the same inline policy to every engineer individually`,`An inline policy keeps a strict one-to-one relationship with an identity, so each change must be repeated per engineer.`],[`Create one shared IAM user for each team and give out its credentials`,`A shared user removes individual identities and does not manage permissions per engineer.`]],slots:[2,4],evidence:[`iam-groups|You can attach an identity-based policy to a user group so that all of the users in the user group receive the policy's permissions.`,`iam-groups|A user group can contain many users, and a user can belong to multiple user groups.`,`iam-groups|User groups can't be nested; they can contain only users, not other IAM groups.`]}),e({id:`identity-keep-014`,building:`identity-keep`,bullets:[`1.1-S1`],d:3,stem:`A standalone AWS account uses the CTO's personal email address for the root user, and the CTO alone holds the root password and the only MFA device. The company wants to reduce delays when AWS contacts the account owner and to make sure no single person can sign in as the root user. Which TWO actions meet these requirements MOST securely? (Choose two.)`,correct:[[`Change the root email address to one that the business manages and that forwards to a group of users`,`A business-managed group address avoids delays if individuals are away or have left the company.`],[`Give the root password and the MFA device to two different groups of administrators`,`With multi-person approval, no one person can access both the password and the MFA.`]],wrong:[[`Create access keys for the root user and share them with the security team`,`AWS strongly recommends not creating access keys for the root user, and sharing them widens exposure.`],[`Give every member of the IT staff the root password and a copy of the MFA device`,`It lets any single person sign in as the root user, which the company wants to prevent.`],[`Remove MFA from the root user once the password is stored in a password manager`,`MFA is a required second factor for the root user, so removing it weakens protection.`]],slots:[0,2],evidence:[`iam-root-best-practices|Use an email address that is managed by your business and forwards received messages directly to a group of users.`,`iam-root-best-practices|Consider using multi-person approval to make sure that no one person can access both MFA and password for the root user.`,`iam-mfa|MFA is enforced for all account types for their root user.`]}),t({id:`identity-keep-015`,building:`identity-keep`,bullets:[`1.1-S1`],d:2,stem:`A company wants its security team to get an email each time the AWS account root user is used. The company wants an alert at the time of use rather than a periodic report, with the LEAST ongoing effort. Which solution meets these requirements?`,correct:[`Create an Amazon EventBridge rule for root user activity that publishes to an Amazon SNS topic`,`The rule reacts when the root user is used, and the SNS topic notifies the team.`],wrong:[[`Download the IAM credential report every week and have the team review the root user row`,`Reviewing a report is a manual, periodic task and not an alert at the time of use.`],[`Create an AWS Config rule that checks whether the root user has MFA enabled and flags drift`,`Config rules monitor root user compliance, such as MFA, and do not notify on each use of the root user.`],[`Turn on the AWS Trusted Advisor security check for MFA on the root account and review it daily`,`The check shows whether MFA is enabled and does not alert when the root user signs in or acts.`]],slot:2,evidence:[`iam-root-best-practices|If you want to set up notifications to alert you of approved root user actions, you can leverage Amazon EventBridge along with Amazon SNS to write an EventBridge rule to track root user usage for the specific action and notify you using an Amazon SNS topic.`,`iam-root-best-practices|AWS Config provides rules to monitor compliance with root user best practices.`,`iam-root-best-practices|Trusted Advisor provides a security check so you know if MFA isn't enabled on the root user account.`]}),t({id:`identity-keep-016`,building:`identity-keep`,bullets:[`1.1-K4`],d:2,tags:[`placement-eligible`],stem:`A company's order-processing AWS Lambda function reads and writes items in a single Amazon DynamoDB table named Orders. A developer wants to attach the AWS managed policy AmazonDynamoDBFullAccess to the function's execution role because it is fast to set up. Which approach follows AWS guidance MOST closely?`,correct:[`Attach a customer managed policy that allows only the needed actions on the Orders table`,`It reduces permissions to what the function needs on the specific table, as AWS recommends over broad managed policies.`],wrong:[[`Attach AmazonDynamoDBFullAccess, because AWS managed policies already provide least privilege`,`AWS managed policies might not grant least privilege because they are available for use by all AWS customers.`],[`Attach AdministratorAccess so that the function never fails with an access denied error`,`It grants every permission in the account, which is the opposite of granting only what the function needs.`],[`Store an IAM user's table-scoped access keys in the function's environment variables`,`It uses long-term keys, whereas Lambda supplies temporary credentials through the execution role.`]],slot:3,evidence:[`iam-best-practices|Keep in mind that AWS managed policies might not grant least-privilege permissions for your specific use cases because they are available for use by all AWS customers.`,`iam-best-practices|As a result, we recommend that you reduce permissions further by defining customer managed policies that are specific to your use cases.`]}),t({id:`identity-keep-017`,building:`identity-keep`,bullets:[`1.1-K4`],d:3,tags:[`placement-eligible`],stem:`An AWS Lambda function writes to an Amazon DynamoDB table by using the access keys of an IAM user. The keys sit in encrypted environment variables and are rotated every quarter. A security review requires that the function use no long-term credentials, with the LEAST operational overhead from now on. Which solution meets these requirements?`,correct:[`Remove the keys and grant the table permissions to the function's execution role`,`Lambda assumes the execution role automatically and supplies temporary credentials, so nothing is stored or rotated.`],wrong:[[`Store the access keys in AWS Secrets Manager and enable automatic rotation`,`The keys remain long-term credentials, and rotation adds a service to configure and operate.`],[`Make the function code call sts:AssumeRole on its own execution role at start-up`,`Lambda already assumes the role, and AWS says to avoid manually calling sts:AssumeRole in function code.`],[`Encrypt the environment variables with a customer managed AWS KMS key`,`Encryption protects the stored keys, but they are still long-term credentials that must be rotated.`]],slot:0,evidence:[`lambda-exec-role|Lambda automatically assumes your execution role when you invoke your function.`,`lambda-exec-role|You should avoid manually calling sts:AssumeRole to assume the execution role in your function code.`,`iam-best-practices|Applications written using an AWS SDK will discover and use these temporary credentials to access AWS resources, and there is no need to distribute long lived credentials for an IAM user to your workloads running on AWS.`]}),t({id:`identity-keep-018`,building:`identity-keep`,bullets:[`1.1-S2`],d:2,tags:[`placement-eligible`],stem:`A developer creates an IAM role whose permissions policy allows dynamodb:PutItem on the Orders table, and selects it as the execution role of a new AWS Lambda function. The function cannot use the role. The role's trust policy names the Amazon EC2 service as the trusted principal. Which change fixes the problem with the LEAST effort?`,correct:[`Update the trust policy so that it names the Lambda service principal as a trusted service`,`The trust policy decides who can assume the role, and Lambda needs lambda.amazonaws.com listed to assume it.`],wrong:[[`Add sts:AssumeRole to the role's permissions policy`,`The permissions policy says what the role can do once assumed, not who is allowed to assume it.`],[`Create access keys for the role and add them to the function configuration`,`A role has no standard long-term credentials such as access keys; it provides temporary credentials when assumed.`],[`Attach the AWSLambdaBasicExecutionRole managed policy to the role`,`That policy gives basic permissions to log to Amazon CloudWatch Logs and does not change who can assume the role.`]],slot:1,evidence:[`lambda-exec-role|In order for Lambda to properly assume your execution role, the role's trust policy must specify the Lambda service principal (lambda.amazonaws.com) as a trusted service.`,`iam-roles|The trust policy specifies which trusted account members are allowed to assume the role.`,`lambda-exec-role|Specifically, this execution role includes the AWSLambdaBasicExecutionRole managed policy, which gives your function basic permissions to log events to Amazon CloudWatch Logs.`]}),e({id:`identity-keep-019`,building:`identity-keep`,bullets:[`1.1-K4`],d:3,tags:[`placement-eligible`],stem:`An AWS Lambda function's execution role has broad Amazon DynamoDB and Amazon S3 permissions that the team granted during development. The function moves to production next week. Security requires permissions that match what the function actually uses and name specific resources, with the LEAST manual analysis. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Use IAM Access Analyzer to generate a policy template from the role's AWS CloudTrail activity`,`It reviews the CloudTrail logs over the chosen date range and produces a template with only the permissions used.`],[`Create a managed policy from the tested template and attach it to the role in place of the broad permissions`,`The fine-grained policy replaces the broad permissions, so the role keeps only what the function needs.`]],wrong:[[`Keep the broad permissions and create an alarm for unusual API calls from the role`,`It only detects problems later and does not reduce the permissions of the role.`],[`Attach a permissions boundary that allows dynamodb:* and s3:*`,`A boundary that matches the broad permissions does not reduce what the role is allowed to do.`],[`Create an IAM user with access keys that cover the function's observed calls and place them in the function`,`It adds long-term keys, whereas the function should keep using its execution role.`]],slots:[1,3],evidence:[`lambda-exec-role|IAM Access Analyzer reviews your AWS CloudTrail logs over the date range that you specify and generates a policy template with only the permissions that the function used during that time.`,`lambda-exec-role|You can use the template to create a managed policy with fine-grained permissions, and then attach it to the IAM role.`,`lambda-exec-role|Before publishing your function in the production environment, as a best practice, adjust the policy to include only the required permissions.`]}),t({id:`identity-keep-020`,building:`identity-keep`,bullets:[`1.1-S2`],d:2,tags:[`placement-eligible`],stem:`A company runs 12 AWS Lambda functions, each with its own execution role, and all of them need the same read access to one Amazon DynamoDB table. The security team wants to change that access in a single place with the LEAST operational overhead. Which solution meets this requirement?`,correct:[`Create one customer managed policy and attach it to all 12 execution roles`,`A change to a managed policy is applied to every identity it is attached to.`],wrong:[[`Add an inline policy with the same permissions to each of the 12 roles`,`Each role would hold its own copy, so a change has to be made 12 times.`],[`Put the 12 execution roles in an IAM user group and attach the policy to the group`,`User groups can contain only users, so they cannot hold roles.`],[`Attach the AWS managed AmazonDynamoDBReadOnlyAccess policy to each role`,`AWS managed policies cannot be changed and cover read access to more than the one table.`]],slot:2,evidence:[`iam-managed-inline|If a policy could apply to more than one entity, it’s better to use a managed policy.`,`iam-managed-inline|When you update permissions in the policy, the changes are applied to all principal entities that the policy is attached to.`,`iam-managed-inline|Notice that two roles include the same policy (the DynamoDB-books-app policy), but they are not sharing a single policy.`,`iam-groups|User groups can't be nested; they can contain only users, not other IAM groups.`]}),t({id:`identity-keep-021`,building:`identity-keep`,bullets:[`1.1-K4`],d:3,tags:[`placement-eligible`],stem:`Two AWS Lambda functions share one execution role that allows dynamodb:* on all tables. The ingestion function only writes items to the Orders table, and the reporting function only reads items from the Reports table. Security wants least privilege and a limited impact if either function is compromised. Which solution BEST meets these requirements?`,correct:[`Give each function its own execution role with a policy that allows only its actions on its own table`,`Each role grants only the actions that function needs on the specific resource it uses.`],wrong:[[`Keep the shared role and add Deny statements for the actions each function should not use`,`The shared role still holds broad allows, and one role cannot express different needs for each function.`],[`Keep the shared role and attach a permissions boundary that allows dynamodb:*`,`A boundary only caps permissions, and one that allows dynamodb:* removes nothing from the role.`],[`Attach AmazonDynamoDBFullAccess to the ingestion role and the read-only managed policy to the reporting role`,`Both managed policies apply to all tables, so each function can reach tables it does not use.`]],slot:3,evidence:[`iam-best-practices|You do this by defining the actions that can be taken on specific resources under specific conditions, also known as least-privilege permissions.`,`iam-best-practices|Keep in mind that AWS managed policies might not grant least-privilege permissions for your specific use cases because they are available for use by all AWS customers.`,`iam-boundaries|A permissions boundary is an advanced feature for using a managed policy to set the maximum permissions that an identity-based policy can grant to an IAM entity.`]}),t({id:`identity-keep-022`,building:`identity-keep`,bullets:[`1.1-S2`,`1.1-K4`],d:3,tags:[`placement-eligible`,`trap:scp-boundary-identity`],stem:`A platform team wants application teams to create their own IAM roles for AWS Lambda functions without waiting for a ticket. No role that a team creates may ever have more than Amazon DynamoDB, Amazon S3 and Amazon CloudWatch Logs permissions, even if a developer writes a broad policy. The same account also runs workloads that need other services. Which solution meets these requirements with the LEAST platform team involvement?`,correct:[`Let developers create the roles and use a permissions boundary that allows only those three services as the maximum`,`The boundary sets the maximum permissions that are delegated, whatever identity-based policies the developers write.`],wrong:[[`Attach a service control policy that allows only those three services to the account`,`It would limit every principal in the account, including the workloads that need other services.`],[`Give developers full IAM permissions and review each new role once a week`,`It allows over-broad roles to exist until a review catches them, and it adds manual platform work.`],[`Have the platform team create every role on request with a narrow policy`,`It meets the limit but keeps the platform team in the loop for every role, which the teams want to avoid.`]],slot:0,evidence:[`iam-best-practices|When you delegate permissions to others, use permissions boundaries to set the maximum permissions that you delegate.`,`iam-best-practices|For example, you could allow developers to create and manage roles for their workloads.`,`iam-policies|The SCP limits permissions for principals in member accounts, including each AWS account root user.`]}),t({id:`identity-keep-023`,building:`identity-keep`,bullets:[`1.1-S2`],d:3,tags:[`placement-eligible`,`trap:scp-boundary-identity`],stem:`An AWS Lambda execution role has an identity-based policy that allows dynamodb:PutItem on the Orders table and logs:*. Security attached a permissions boundary to the role that allows only s3:* and logs:*. The function now fails with an access denied error on PutItem. What is the MOST appropriate fix that keeps the boundary in place?`,correct:[`Add dynamodb:PutItem on the Orders table to the permissions boundary policy`,`The effective permissions are the intersection of the identity-based policy and the boundary, so both must allow the action.`],wrong:[[`Attach a second identity-based policy that allows dynamodb:PutItem to the role`,`Identity-based policies cannot exceed the boundary, so the boundary still blocks the action.`],[`Add the role ARN as the principal in a resource-based policy on the table`,`When a role ARN is the principal, an explicit allow in the permissions boundary is still required.`],[`Change the role trust policy to name the Lambda service principal again`,`The trust policy decides who can assume the role and does not affect what the role may do.`]],slot:1,evidence:[`iam-boundaries|An entity's permissions boundary allows it to perform only the actions that are allowed by both its identity-based policies and its permissions boundaries.`,`iam-policies|However, if you specify a role ARN in the principal element of a resource-based policy, an explicit allow in the permission boundary is required.`,`iam-roles|The trust policy specifies which trusted account members are allowed to assume the role.`]}),t({id:`identity-keep-024`,building:`identity-keep`,bullets:[`1.1-K4`],d:2,tags:[`mock-reserve`],stem:`A company has accumulated hundreds of IAM users, roles and policies over several years. The security team wants to identify permissions and credentials that are no longer used so it can remove them, with the LEAST effort. What should the team use?`,correct:[`IAM last accessed information`,`It helps identify the users, roles, permissions, policies and credentials that are no longer needed so they can be removed.`],wrong:[[`AWS CloudTrail Event history searched by hand for each identity`,`Event history covers only recent management events, and searching it identity by identity is slow manual work.`],[`Amazon Inspector scans of the account`,`Amazon Inspector looks for software vulnerabilities and does not show which permissions are unused.`],[`AWS Config rules that check the policy version of each role`,`A rule evaluates a configuration setting and does not report which permissions have been used.`]],slot:2,evidence:[`iam-best-practices|IAM provides last accessed information to help you identify the users, roles, permissions, policies, and credentials that you no longer need so that you can remove them.`,`iam-best-practices|You can also use this information to refine your IAM policies to better adhere to least-privilege permissions.`]}),t({id:`identity-keep-025`,building:`identity-keep`,bullets:[`1.1-S2`],d:2,tags:[`mock-reserve`],stem:`A company wants its database administrators to have permissions for their job function, and wants AWS to keep those permissions current as new services and API operations appear. The company wants the LEAST ongoing maintenance. Which solution meets these requirements?`,correct:[`Attach an AWS managed policy for the job function to the administrators`,`AWS maintains and updates job function policies as new services and API operations are introduced.`],wrong:[[`Copy an AWS managed policy into a customer managed policy and attach that`,`The copy is maintained by the company, so it must be updated by hand as new services appear.`],[`Write an inline policy for each database administrator`,`Each inline policy belongs to one identity and must be maintained by the company.`],[`Attach the AdministratorAccess policy to the database administrators`,`It gives full access to every service and is recommended only for the account administrator.`]],slot:3,evidence:[`iam-managed-inline|One key advantage of using job function policies is that they are maintained and updated by AWS as new services and API operations are introduced.`,`iam-managed-inline|We recommend that you use this policy only for the account administrator.`]}),t({id:`identity-keep-026`,building:`identity-keep`,bullets:[`1.1-S1`],d:3,tags:[`mock-reserve`],stem:`A company manages 60 member accounts with AWS Organizations. Every member account keeps its root user sign-in in place. Security wants a preventive guardrail that blocks the root user of every current and future member account from performing actions, even if someone obtains the password and the MFA device, with the LEAST ongoing effort. Which solution meets these requirements?`,correct:[`Attach a service control policy to the organization root that denies all actions for the root user`,`An SCP applies to every member account, including the root user of each one, so one policy covers all 60 accounts.`],wrong:[[`Require a hardware MFA token for the root user of every member account and store the tokens safely`,`MFA protects sign-in but does not stop someone with the factors from using the root user, and it is repeated in 60 accounts.`],[`Create an Amazon CloudWatch alarm on root user sign-in events in each member account`,`An alarm detects use of the root user but does not prevent it.`],[`Add the root user of each member account to an IAM group that has an explicit deny policy`,`The root user is not an IAM user and cannot be added to an IAM group, and this would be repeated in each account.`]],slot:0,evidence:[`orgs-scps|SCPs affect all users and roles in attached accounts, including the root user.`,`orgs-scps|An SCP restricts permissions for IAM users and roles in member accounts, including the member account's root user.`]}),e({id:`identity-keep-027`,building:`identity-keep`,bullets:[`1.1-S1`],d:2,tags:[`mock-reserve`],stem:`A company has a standalone AWS account that is not part of AWS Organizations. Which TWO tasks can be done only by signing in as the root user? (Choose two.)`,correct:[[`Close the AWS account`,`Standalone accounts require root credentials to close the account.`],[`Restore the permissions of the only IAM administrator after the administrator revoked them by mistake`,`The root user can edit policies to restore IAM user permissions.`]],wrong:[[`Update the alternate contacts of the account`,`Alternate contacts do not require root user credentials.`],[`Launch an Amazon EC2 instance in the account`,`An IAM identity with the right permissions can launch instances without the root user.`],[`Create a new IAM user with a console password`,`An administrator IAM identity can create IAM users, so the root user is not required.`]],slots:[1,4],evidence:[`iam-root-user|Standalone AWS accounts that are not part of AWS Organizations require root credentials to close the account.`,`iam-root-user|If the only IAM administrator accidentally revokes their own permissions, you can sign in as the root user to edit policies and restore those permissions.`,`iam-root-user|Other account settings, such as account name, contact information, alternate contacts, payment currency preference, and AWS Regions, don't require root user credentials.`]})],d=[t({id:`key-vault-001`,postGuide:[`s3-default-sse-s3`],building:`key-vault`,bullets:[`1.3-K4`],d:1,stem:`A company encrypts data in several AWS services with keys that it controls. The security team must have full control over each key's lifecycle and permissions, and must be able to audit every use of the keys in AWS CloudTrail logs. Which key option BEST meets these requirements?`,correct:[`Customer managed keys that the team creates in AWS KMS`,`Customer managed keys give full control over lifecycle and usage, and their use can be audited in CloudTrail logs.`],wrong:[[`AWS managed keys that integrated services create in the account`,`The team cannot change the properties of AWS managed keys, rotate them, change their key policies, or schedule them for deletion, so it lacks lifecycle control.`],[`AWS owned keys that each service manages in its own accounts`,`AWS owned keys are controlled by the service and not viewable by the customer, who cannot audit activity on them or delete them.`],[`Amazon S3 managed keys (SSE-S3) that S3 applies to every new object`,`SSE-S3 gives no separate key to view, no control policy to edit and no key usage to follow in CloudTrail.`]],slot:0,evidence:[`kms-concepts|Customer managed keys are recommended for customers who want full control over the lifecycle and usage of their keys.`,`kms-concepts|You can use your customer managed key in cryptographic operations and audit usage in AWS CloudTrail logs.`,`kms-concepts|However, you cannot change any properties of AWS managed keys, rotate them, change their key policies, or schedule them for deletion.`,`kms-concepts|you cannot change their policies, you cannot audit activities on these keys, and you cannot delete them.`]}),t({id:`key-vault-002`,building:`key-vault`,bullets:[`1.3-K4`],d:1,tags:[`trap:kms-vs-cloudhsm`],stem:`A payments company must keep its encryption keys in single-tenant hardware security modules and have full control of the cryptographic algorithms and keys it uses. Which service BEST meets these requirements?`,correct:[`AWS CloudHSM`,`CloudHSM offers single-tenant, standards-compliant HSMs and gives full control of the algorithms and keys.`],wrong:[[`AWS KMS customer managed keys in the standard key store`,`The standard key store is a tenant-agnostic fleet of HSMs, not single-tenant HSMs that the company controls.`],[`AWS Secrets Manager with automatic rotation turned on`,`Secrets Manager manages secrets such as credentials and does not provide HSMs or control over algorithms.`],[`AWS Certificate Manager with private certificates`,`ACM issues and renews certificates and does not provide single-tenant HSMs for general key storage.`]],slot:1,evidence:[`cloudhsm|We offer HSMs that are standards-compliant, single-tenant`,`cloudhsm|AWS CloudHSM gives you full control of the algorithms and keys you use.`,`kms-key-stores|This HSM type can be thought of as a tenant-agnostic fleet of HSMs`]}),t({id:`key-vault-003`,postGuide:[`kms-external-key-store`],building:`key-vault`,bullets:[`1.3-K4`],d:2,tags:[`trap:kms-vs-cloudhsm`],stem:`A company must encrypt data in Amazon S3 and Amazon EBS and show auditors that only named IAM roles can use the encryption keys. The company has no requirement for single-tenant hardware or for key material to be held outside AWS. Which approach meets these requirements with the LEAST operational overhead?`,correct:[`Customer managed KMS keys in the standard key store, with key policies that name the permitted roles`,`The key policy controls who can use the key, which is sufficient for many compliance requirements, and the standard key store has the lowest operational burden.`],wrong:[[`KMS keys in a custom key store backed by an AWS CloudHSM cluster that the company builds and operates`,`This adds cluster operations, cost and reduced performance, and nothing in the requirements calls for a single-tenant HSM.`],[`KMS keys in an external key store that forwards requests to a key manager outside the AWS Cloud`,`This is only for an explicit requirement to keep key material outside AWS, and it adds an XKS proxy to operate.`],[`An AWS CloudHSM cluster with application code that encrypts each file before upload`,`The company would operate HSMs and write encryption code, when the AWS services can use KMS keys directly.`]],slot:2,evidence:[`kms-key-stores|For many compliance requirements, the control you have over key access through the KMS key policy is sufficient.`,`kms-key-stores|Consider creating a custom key store only when your organization has regulatory requirements that explicitly mandate key material protection in a single-tenant HSM or in an HSM that you control outside of AWS.`,`kms-key-stores|lets you take full advantage of the scalability, availability, and durability of AWS KMS with the lowest operational burden and cost of the AWS key stores.`]}),t({id:`key-vault-004`,postGuide:[`kms-external-key-store`],building:`key-vault`,bullets:[`1.3-K4`],d:2,tags:[`trap:kms-vs-cloudhsm`],stem:`A healthcare company's regulator requires that the key material protecting its Amazon EBS volumes sits in a single-tenant HSM that the company owns and manages in AWS. The company wants Amazon EBS to keep using AWS KMS keys. Which solution BEST meets these requirements?`,correct:[`Create a KMS custom key store backed by AWS CloudHSM and create the keys in it`,`An AWS CloudHSM key store is backed by a dedicated, customer-owned cluster, and EBS volume encryption is a suitable low-throughput use.`],wrong:[[`Create customer managed keys in the standard key store and turn on automatic key rotation`,`The standard key store uses shared AWS KMS HSMs, so the key material is not in a single-tenant HSM that the company owns.`],[`Create a KMS external key store that connects to a key manager through an XKS proxy`,`An external key store keeps key material in a system outside the AWS Cloud, not in an HSM that the company manages in AWS.`],[`Use the AWS managed key for Amazon EBS and restrict who can use it with a key policy`,`AWS managed keys live in the standard key store, and the company cannot change their key policies.`]],slot:3,evidence:[`kms-key-stores|There are two types: AWS CloudHSM key stores, backed by a dedicated, customer-owned AWS CloudHSM cluster, and external key stores, backed by an HSM or key management system outside the AWS Cloud.`,`kms-key-stores|Consider creating a custom key store only when your organization has regulatory requirements that explicitly mandate key material protection in a single-tenant HSM or in an HSM that you control outside of AWS.`,`kms-key-stores|They are suitable only for low transactions per second (TPS) workloads such as Amazon Elastic Block Store volume encryption`]}),t({id:`key-vault-005`,building:`key-vault`,bullets:[`1.3-K4`],d:3,tags:[`trap:kms-vs-cloudhsm`],stem:`A company's regulations require that the key material protecting its Amazon EBS volumes be generated and kept in a single-tenant hardware security module (HSM) that the company controls, while the volumes continue to use AWS KMS for encryption. Which solution BEST meets this requirement?`,correct:[`Create a KMS custom key store backed by a dedicated AWS CloudHSM cluster and create the KMS key in it`,`A CloudHSM key store keeps the key material in a dedicated, customer-owned single-tenant HSM cluster while EBS still calls AWS KMS.`],wrong:[[`Create a customer managed key in the standard KMS key store and restrict it with a key policy`,`The key material is generated and protected in the HSMs of AWS KMS, not in a single-tenant HSM that the company controls.`],[`Import the company's own key material into a customer managed key in the standard KMS key store`,`Imported key material is still held and used by AWS KMS in the standard key store, not in a dedicated HSM.`],[`Use the AWS managed key for Amazon EBS in the account`,`An AWS managed key is created and managed by AWS on the company's behalf, so the company does not control the HSM.`]],slot:0,evidence:[`kms-key-stores|Consider creating a custom key store only when your organization has regulatory requirements that explicitly mandate key material protection in a single-tenant HSM or in an HSM that you control outside of AWS.`,`kms-key-stores|Although AWS CloudHSM clusters are hosted within AWS, they provide single-tenant HSM instances that are owned and managed by you.`]}),t({id:`key-vault-006`,building:`key-vault`,bullets:[`1.3-K4`],d:2,stem:`A company generates its encryption keys in its own key ceremony system and wants AWS KMS to use that key material for data in Amazon S3. Policy also requires the ability to remove the key material from AWS on a defined schedule. The company does not want to operate any HSMs. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create a KMS key without key material, then import the material with an expiration time`,`Importing key material lets the company control how it is generated and when it is removed, with the key still in the standard key store.`],wrong:[[`Create a KMS key in a custom key store backed by AWS CloudHSM and generate the material in the cluster`,`The key material would be generated in the cluster rather than in the key ceremony system, and the company would operate HSMs.`],[`Use the AWS managed key for Amazon S3 and delete and re-create it on the required schedule`,`The company cannot manage the lifecycle of an AWS managed key, supply its own material, or schedule it for deletion.`],[`Use the default SSE-S3 encryption and rotate the Amazon S3 managed keys with a custom script`,`SSE-S3 uses keys that Amazon S3 manages, so the company cannot supply its own key material or control its removal.`]],slot:1,evidence:[`kms-key-stores|Importing key material is useful when you need to generate keys using a specific system or source of entropy, retain a backup copy outside AWS, or remove key material on a defined schedule.`,`kms-key-stores|You can set an expiration time on import or call DeleteImportedKeyMaterial to revoke access immediately.`]}),e({id:`key-vault-007`,building:`key-vault`,bullets:[`1.3-K4`],d:2,tags:[`trap:kms-vs-cloudhsm`],stem:`A company runs a payment signing application against an AWS CloudHSM cluster because the application needs single-tenant HSMs. The cluster must stay available if one Availability Zone fails, and throughput must grow as load increases. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Place the HSMs of the cluster in at least two Availability Zones`,`Spreading the HSMs of a cluster across Availability Zones provides redundancy and high availability.`],[`Add more HSMs to the cluster as load grows`,`Adding more HSMs to a cluster provides higher performance.`]],wrong:[[`Create a second cluster in the same Availability Zone as the first one`,`Both clusters would fail together if that Availability Zone failed, so availability is not improved.`],[`Create IAM roles for the HSM users so that AWS recovers the cluster after an outage`,`The company controls its own HSM user management outside of IAM roles, and IAM roles do not add availability.`],[`Replace the cluster with AWS managed KMS keys that provide the same single-tenant HSMs`,`AWS managed keys are in the standard key store and do not provide single-tenant HSMs under the company's control.`]],slots:[1,3],evidence:[`cloudhsm-clusters|Adding more HSMs to a cluster provides higher performance. Spreading clusters across Availability Zones provides redundancy and high availability.`,`cloudhsm|Because your data plane is end-to-end (E2E) encrypted and not visible to AWS, you control your own user management (outside of IAM roles).`]}),t({id:`key-vault-008`,building:`key-vault`,bullets:[`1.3-K4`,`1.3-S2`],d:3,stem:`A company encrypts its Amazon EBS volumes with the default AWS managed key for EBS. It must now share snapshots of those volumes with a partner AWS account that will restore them. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Copy each snapshot with a customer managed key that allows the partner account, then share the copy`,`A copy can be encrypted under a different KMS key, and a customer managed key can be opened to the partner account.`],wrong:[[`Share the existing snapshots with the partner account and add the partner account to the AWS managed key policy`,`The company cannot change the key policy of an AWS managed key, and resources encrypted under one cannot be shared with other accounts.`],[`Change the KMS key of each existing snapshot to a customer managed key and then share the snapshots`,`The KMS key associated with an existing snapshot or volume cannot be changed; only a copy can use a different key.`],[`Make each snapshot public so that the partner account can copy it`,`Public snapshots of encrypted volumes are not supported.`]],slot:2,evidence:[`kms-concepts|You cannot share resources encrypted under an AWS managed key with other accounts.`,`ebs-encryption|You cannot change the KMS key that is associated with an existing snapshot or volume. However, you can associate a different KMS key during a snapshot copy operation so that the resulting copied snapshot is encrypted by the new KMS key.`,`ebs-encryption|Public snapshots of encrypted volumes are not supported, but you can share an encrypted snapshot with specific accounts.`]}),e({id:`key-vault-009`,building:`key-vault`,bullets:[`1.3-K4`],d:2,stem:`A security team compares the customer managed keys it creates with the AWS managed keys that integrated services create in its account. Which TWO actions can the team perform ONLY on the customer managed keys? (Choose two.)`,correct:[[`Change the key policy of the key`,`The team controls the key policy of a customer managed key but cannot change the key policy of an AWS managed key.`],[`Schedule the key for deletion`,`The team can schedule deletion of a customer managed key, but not of an AWS managed key.`]],wrong:[[`View the key policy of the key`,`The team has permission to view the key policies of AWS managed keys as well.`],[`Audit the use of the key in AWS CloudTrail logs`,`The team can audit the use of AWS managed keys in CloudTrail logs as well.`],[`See the key listed in the AWS KMS console`,`AWS managed keys appear in the console on their own page, so this is not exclusive to customer managed keys.`]],slots:[2,4],evidence:[`kms-concepts|You have permission to view the AWS managed keys in your account, view their key policies, and audit their use in AWS CloudTrail logs.`,`kms-concepts|However, you cannot change any properties of AWS managed keys, rotate them, change their key policies, or schedule them for deletion.`,`kms-concepts|AWS managed keys appear on the AWS managed keys page of the AWS Management Console for AWS KMS.`]}),t({id:`key-vault-010`,postGuide:[`s3-default-sse-s3`],postGuideKey:[`s3-default-sse-s3`],building:`key-vault`,bullets:[`1.3-S2`],d:1,tags:[`trap:sse-s3-kms-c`],stem:`A company stores documents in a newly created Amazon S3 bucket. Policy says all objects must be encrypted at rest, and there is no requirement to control the keys. Which action meets this requirement with the LEAST effort?`,correct:[`Do nothing, because SSE-S3 already encrypts every new object`,`Every new object upload is encrypted by default with SSE-S3, at no additional fee.`],wrong:[[`Enable SSE-KMS on the bucket with a new customer managed key`,`This adds a key to manage and an additional cost, when the requirement is already met.`],[`Configure SSE-C and send a key with every upload request`,`The applications would have to supply and track keys, which is more work than the default.`],[`Encrypt each file in the application before it is uploaded`,`This requires custom code and key handling for a requirement that is already met.`]],slot:3,evidence:[`s3-sse-s3|All new object uploads to Amazon S3 buckets are encrypted by default with server-side encryption with Amazon S3 managed keys (SSE-S3).`,`s3-sse-s3|There are no additional fees for using server-side encryption with Amazon S3 managed keys (SSE-S3).`]}),t({id:`key-vault-011`,building:`key-vault`,bullets:[`1.3-S2`],d:2,tags:[`trap:sse-s3-kms-c`],stem:`A company keeps records in an Amazon S3 bucket. Auditors require that a key policy names the roles that may use the encryption key, and that every use of the key is recorded in AWS CloudTrail. Which encryption option meets these requirements with the LEAST operational overhead?`,correct:[`SSE-KMS with a customer managed KMS key`,`A customer managed key has a key policy the company edits, and its use is recorded in CloudTrail logs.`],wrong:[[`SSE-S3 default encryption on the bucket`,`SSE-S3 has no separate key or key policy for the company to edit, and key usage cannot be followed in CloudTrail.`],[`SSE-C with keys supplied on each upload and download`,`The company would manage and track the keys itself, and there is no key policy or KMS audit trail.`],[`SSE-KMS with the AWS managed key for Amazon S3`,`The company cannot change the key policy of an AWS managed key, so it cannot name the permitted roles.`]],slot:0,evidence:[`s3-sse|With AWS KMS, you have more control over your keys. For example, you can view separate keys, edit control policies, and follow the keys in AWS CloudTrail.`,`s3-sse-kms|To audit the usage of your AWS KMS keys for your SSE-KMS encrypted data, you can use AWS CloudTrail logs.`,`kms-concepts|However, you cannot change any properties of AWS managed keys, rotate them, change their key policies, or schedule them for deletion.`]}),t({id:`key-vault-012`,postGuide:[`s3-dsse-kms`],building:`key-vault`,bullets:[`1.3-S2`],d:2,tags:[`trap:sse-s3-kms-c`],stem:`A company stores hundreds of millions of objects in an Amazon S3 bucket that uses SSE-KMS. AWS KMS request charges are high because S3 calls AWS KMS for each object request. The company wants to lower these charges without changing its client applications. Which solution is the MOST cost-effective?`,correct:[`Enable an S3 Bucket Key for SSE-KMS on the bucket`,`A bucket-level key reduces the request traffic from Amazon S3 to AWS KMS, and no client changes are needed.`],wrong:[[`Switch the bucket default encryption to dual-layer server-side encryption (DSSE-KMS)`,`S3 Bucket Keys are not supported for DSSE-KMS, so the request traffic to AWS KMS would not fall.`],[`Turn on automatic key rotation for the customer managed key`,`Rotating key material does not change how many requests S3 sends to AWS KMS.`],[`Create a separate customer managed key for each prefix in the bucket`,`S3 shares a bucket-level key only among objects encrypted by the same key, so more keys means more requests.`]],slot:1,evidence:[`s3-bucket-keys|Using a bucket-level key for SSE-KMS can reduce AWS KMS request costs by up to 99 percent by decreasing the request traffic from Amazon S3 to AWS KMS.`,`s3-bucket-keys|S3 Bucket Keys aren't supported for dual-layer server-side encryption with AWS Key Management Service (AWS KMS) keys (DSSE-KMS).`,`s3-bucket-keys|Amazon S3 will only share an S3 Bucket Key for objects encrypted by the same AWS KMS key.`]}),t({id:`key-vault-013`,building:`key-vault`,bullets:[`1.3-S2`],d:2,stem:`A company changes the default encryption of an Amazon S3 bucket from SSE-S3 to SSE-KMS. The bucket already holds tens of millions of objects, and compliance requires every existing object to be encrypted with the KMS key as well. Which solution meets this requirement with the LEAST operational overhead?`,correct:[`Run an S3 Batch Operations Copy job that rewrites the objects into the same bucket`,`Batch Operations can copy existing objects back to the same bucket as SSE-KMS encrypted objects, at the scale of billions of objects.`],wrong:[[`Wait for Amazon S3 to re-encrypt the existing objects in the background with the new default`,`Changing the default encryption does not change the encryption type of the objects already in the bucket.`],[`Create an S3 Lifecycle rule that transitions the objects to S3 Standard-IA`,`A transition changes the storage class and does not re-encrypt the objects with the KMS key.`],[`Write a script that downloads each object and uploads it again with SSE-C headers`,`This takes custom code and would apply SSE-C, not SSE-KMS.`]],slot:2,evidence:[`s3-sse|When you change the default encryption configuration of your bucket to SSE-KMS, the encryption type of the existing Amazon S3 objects in the bucket is not changed.`,`s3-sse|You can use the Copy objects action to copy existing objects, which writes them back to the same bucket as SSE-KMS encrypted objects.`,`s3-sse|A single Batch Operations job can perform the specified operation on billions of objects.`]}),e({id:`key-vault-014`,building:`key-vault`,bullets:[`1.3-S2`],d:2,stem:`A company will encrypt the objects in an Amazon S3 bucket in eu-west-1 with SSE-KMS and a customer managed key. Which TWO requirements must the KMS key meet? (Choose two.)`,correct:[[`It is a symmetric encryption KMS key`,`Amazon S3 supports only symmetric encryption KMS keys.`],[`It is in the same AWS Region as the bucket`,`With SSE-KMS the KMS keys must be in the same Region as the bucket.`]],wrong:[[`It is an asymmetric RSA KMS key used for encrypt and decrypt`,`Amazon S3 does not support asymmetric KMS keys for SSE-KMS.`],[`It is an HMAC KMS key`,`An HMAC key generates and verifies message authentication codes and is not a symmetric encryption key.`],[`It is in us-east-1 so that every bucket can share it`,`The key must be in the same Region as the bucket, which here is eu-west-1.`]],slots:[0,3],evidence:[`s3-sse-kms|When you use SSE-KMS encryption with an S3 bucket, the AWS KMS keys must be in the same Region as the bucket.`,`s3-sse-kms|Amazon S3 supports only symmetric encryption KMS keys.`]}),t({id:`key-vault-015`,building:`key-vault`,bullets:[`1.3-S2`],d:3,tags:[`trap:sse-s3-kms-c`],stem:`A company must supply its own encryption key with each upload request, and it wants Amazon S3 to perform the encryption and decryption of the objects without the company running encryption code. The objects go to an existing bucket that already accepts SSE-C uploads. Which solution meets these requirements with the LEAST change?`,correct:[`Use server-side encryption with customer-provided keys (SSE-C) and send the key over HTTPS with each request`,`The company provides the key in each request, and Amazon S3 encrypts and decrypts the objects with it.`],wrong:[[`Use server-side encryption with AWS KMS keys (SSE-KMS) with a customer managed key`,`The key is created and held in AWS KMS rather than supplied by the company with each request.`],[`Use server-side encryption with Amazon S3 managed keys (SSE-S3)`,`Amazon S3 manages the keys itself, so the company does not supply a key with each request.`],[`Encrypt the objects in the application with a company-held key before uploading them`,`The company would then run encryption code itself, which fails the requirement that Amazon S3 perform the encryption.`]],slot:3,evidence:[`s3-sse-c|You can use server-side encryption with customer-provided keys (SSE-C) in your general purpose buckets to encrypt your data with your own encryption keys.`,`s3-sse-c|With the encryption key that you provide as part of your request, Amazon S3 manages data encryption as it writes to disks and data decryption when you access your objects.`,`s3-sse-c|You must use HTTPS when specifying SSE-C headers on your requests.`]}),t({id:`key-vault-016`,building:`key-vault`,bullets:[`1.3-S2`],d:1,tags:[`trap:sse-s3-kms-c`],stem:`A company stores objects in Amazon S3 and must control the key policy of the encryption key, be able to disable the key, and track every use of the key in AWS CloudTrail. Which option BEST meets these requirements?`,correct:[`Server-side encryption with AWS KMS keys (SSE-KMS)`,`SSE-KMS gives control over the key policy and lets the company follow key usage in AWS CloudTrail.`],wrong:[[`Server-side encryption with Amazon S3 managed keys (SSE-S3)`,`Amazon S3 manages these keys, so the company has no key policy to edit and no separate key usage to follow.`],[`Server-side encryption with customer-provided keys (SSE-C)`,`The company must supply and manage the key in every request, and there is no KMS key policy to control.`],[`Encryption of the objects in the application before upload with a key held in code`,`It is not server-side encryption and gives no KMS key policy or CloudTrail record of key use.`]],slot:0,evidence:[`s3-sse|With AWS KMS, you have more control over your keys.`,`s3-sse|For example, you can view separate keys, edit control policies, and follow the keys in AWS CloudTrail.`]}),e({id:`key-vault-017`,building:`key-vault`,bullets:[`1.3-S2`],d:2,stem:`A company has an unencrypted Amazon EBS volume attached to a running database instance. It must end up with an encrypted volume that holds the same data. Which TWO steps are part of the solution? (Choose two.)`,correct:[[`Create a snapshot of the unencrypted volume`,`The snapshot is the starting point, because an existing unencrypted volume cannot be encrypted directly.`],[`Create a new volume from the snapshot with encryption enabled`,`A new encrypted volume created from the snapshot holds the same data.`]],wrong:[[`Turn on encryption for the existing volume in its settings`,`Existing unencrypted volumes cannot be encrypted directly.`],[`Attach a KMS key to the existing snapshot so it is encrypted in place`,`Existing unencrypted snapshots cannot be encrypted directly, and the KMS key of a snapshot cannot be changed.`],[`Modify the volume type to an encrypted volume type`,`Encryption is not a volume type, and changing the type does not encrypt the volume.`]],slots:[1,4],evidence:[`ebs-encryption|You can't directly encrypt existing unencrypted volumes or snapshots. To encrypt an unencrypted volume, create a snapshot of that volume, and then use the snapshot to create a new encrypted volume.`,`ebs-encryption|Amazon EBS encryption uses AWS KMS keys when creating encrypted volumes and snapshots.`]}),t({id:`key-vault-018`,building:`key-vault`,bullets:[`1.3-S4`],d:1,stem:`A company wants to define which IAM roles can use a KMS key to encrypt and decrypt data and which roles can only administer the key. Which feature BEST meets this requirement?`,correct:[`The key policy of the KMS key`,`Key policies are the primary way to control access to KMS keys, and their statements say who can use a key and how.`],wrong:[[`A security group that is attached to AWS KMS`,`Security groups filter network traffic for resources in a VPC and do not control permissions on a KMS key.`],[`An S3 bucket policy that names the roles`,`A bucket policy controls access to the bucket and its objects, not to the KMS key.`],[`IAM identity policies alone, with no key policy statement that enables them`,`Without permission from the key policy, IAM policies that allow access have no effect.`]],slot:1,evidence:[`kms-key-policies|Key policies are the primary way to control access to KMS keys.`,`kms-key-policies|The statements in the key policy determine who has permission to use the KMS key and how they can use it.`,`kms-key-policies|Without permission from the key policy, IAM policies that allow permissions have no effect.`]}),t({id:`key-vault-019`,building:`key-vault`,bullets:[`1.3-S4`],d:2,stem:`An engineer creates a customer managed key through the AWS KMS API with a custom key policy that names one application role. IAM policies that allow kms:Decrypt for other roles in the account have no effect. The company wants account administrators to grant key access with IAM policies. Which change meets this requirement with the LEAST effort?`,correct:[`Add a key policy statement that gives the account principal permission to use IAM policies to allow access`,`This statement lets the account use IAM policies to allow access to all KMS operations on the key.`],wrong:[[`Attach an IAM policy that allows kms:PutKeyPolicy to the other roles`,`IAM policies that allow permissions have no effect unless the key policy enables them, so this grant is ignored.`],[`Set a permissions boundary on each of the other roles that includes kms:Decrypt`,`A permissions boundary only limits permissions and does not enable IAM policies for the key.`],[`Convert the key to an AWS managed key so that IAM policies apply automatically`,`A customer managed key cannot be converted, and AWS managed key policies cannot be changed by the company.`]],slot:2,evidence:[`kms-key-policies|Unless the key policy explicitly allows it, you cannot use IAM policies to allow access to a KMS key.`,`kms-default-key-policy|Without this permission, IAM policies that allow access to the key are ineffective, although IAM policies that deny access to the key are still effective.`,`kms-default-key-policy|Unlike other AWS resource policies, an AWS KMS key policy does not automatically give permission to the account or any of its principals.`]}),t({id:`key-vault-020`,building:`key-vault`,bullets:[`1.3-S4`],d:3,stem:`A company wants separation of duties for a customer managed key. A key-management role must administer the key but not be able to decrypt data, and an application role must encrypt and decrypt but not manage the key. The key must also stay manageable if the key-management role is later deleted. Which key policy design meets these requirements?`,correct:[`An account statement enabling IAM policies, an administrators statement for the key-management role, and a users statement for the application role`,`Administrators manage but cannot use the key, users can use it, and the account statement keeps the key manageable.`],wrong:[[`Two statements that give the key-management role administration and the application role use, with no account statement`,`If the only principal with access is deleted, the key becomes unmanageable, so the account statement is missing.`],[`One statement that gives both roles every kms action so that either can recover the key`,`The key-management role could then decrypt data and the application role could manage the key, breaking the separation.`],[`An account statement plus a users statement for the key-management role and an administrators statement for the application role`,`The statements are swapped, so the application role could manage the key and the key-management role could not.`]],slot:3,evidence:[`kms-default-key-policy|Key administrators have permissions to manage the KMS key, but do not have permissions to use the KMS key in cryptographic operations.`,`kms-default-key-policy|Key users have permission to use the KMS key directly in all cryptographic operations supported on the KMS key.`,`kms-default-key-policy|suppose you create a key policy that gives only one user access to the KMS key. If you then delete that user, the key becomes unmanageable and you must contact AWS Support to regain access to the KMS key.`]}),t({id:`key-vault-021`,building:`key-vault`,bullets:[`1.3-S4`],d:3,stem:`A data account owns a customer managed key that encrypts objects in an Amazon S3 bucket. A role in an analytics account must decrypt the objects, and its S3 permissions are already in place. An engineer added a key policy statement that allows the analytics account to use the key, but the role still receives AccessDenied. What is MISSING?`,correct:[`An IAM policy in the analytics account that allows the role to use the key`,`The key policy sets who can have access, and an IAM policy in the external account gives its roles that access.`],wrong:[[`A second key policy in the analytics account for the same KMS key`,`Every KMS key has exactly one key policy, and it lives in the account that owns the key.`],[`A copy of the KMS key created in the analytics account`,`A copy is not needed, because users in another account can use the key once both policies allow it.`],[`An AWS managed key policy in the analytics account that trusts the data account`,`AWS managed keys cannot be shared with other accounts and have no policy that the company can change.`]],slot:0,evidence:[`kms-cross-account|Neither the key policy nor the IAM policy alone is sufficient—you must change both.`,`kms-cross-account|IAM policies in the external account must delegate the key policy permissions to its users and roles.`,`kms-key-policies|Every KMS key must have exactly one key policy.`]}),e({id:`key-vault-022`,building:`key-vault`,bullets:[`1.3-S4`,`1.3-S2`],d:2,stem:`A role must upload objects, including large multipart uploads, to an Amazon S3 bucket that uses SSE-KMS and must also download them. Which TWO KMS permissions must the role have on the key? (Choose two.)`,correct:[[`kms:GenerateDataKey`,`Uploading an object with SSE-KMS requires kms:GenerateDataKey on the key.`],[`kms:Decrypt`,`Downloading an object encrypted with an AWS KMS key requires kms:Decrypt, which a multipart upload also needs.`]],wrong:[[`kms:ScheduleKeyDeletion`,`This permission schedules the deletion of the key and is not needed to read or write encrypted objects.`],[`kms:PutKeyPolicy`,`This permission changes the key policy and is an administrative action, not a use of the key.`],[`kms:CreateAlias`,`This permission creates an alias for the key and does not encrypt or decrypt data.`]],slots:[0,2],evidence:[`s3-sse-kms|To successfully make a PutObject request to encrypt an object with an AWS KMS key to Amazon S3, you need kms:GenerateDataKey permissions on the key.`,`s3-sse-kms|To download an object encrypted with an AWS KMS key, you need kms:Decrypt permissions for the key.`,`s3-sse-kms|To perform a multipart upload to encrypt an object with an AWS KMS key, you must have the kms:GenerateDataKey and kms:Decrypt permissions for the key.`]}),t({id:`key-vault-023`,building:`key-vault`,bullets:[`1.3-S4`],d:3,stem:`A company owns 40 customer managed keys whose key policies enable IAM policies for the account. A contractor's IAM role is compromised and must be blocked from using any KMS key in the account right away. Which solution is the FASTEST and meets this requirement without editing 40 key policies?`,correct:[`Attach an IAM policy to the role that explicitly denies the KMS actions`,`An IAM policy can deny a permission to a KMS key without any permission from a key policy.`],wrong:[[`Remove the role from the key policy statements of all 40 keys`,`This means editing 40 policies, and the role can still get access through IAM policies that the key policies enable.`],[`Turn on automatic rotation for all 40 keys so that the role's access is revoked`,`Rotating key material does not change who is allowed to use a key.`],[`Schedule all 40 keys for deletion and cancel the deletion for the keys that are needed`,`This disrupts every workload that uses the keys and still needs per-key work.`]],slot:1,evidence:[`kms-key-policies|(You can use an IAM policy to deny a permission to a KMS key without permission from a key policy.)`,`kms-key-policies|The default key policy enables IAM policies.`]}),t({id:`key-vault-024`,building:`key-vault`,bullets:[`1.3-K4`],d:2,tags:[`mock-reserve`],stem:`A company wants to stop all use of a customer managed KMS key that it believes no workload needs. A forgotten application might still depend on it, and the company must be able to restore full access later with no time limit. Which action meets these requirements with the LEAST risk of permanent data loss?`,correct:[`Disable the key and re-enable it if an application fails`,`A disabled KMS key can be re-enabled at any time, unlike a deleted key.`],wrong:[[`Schedule deletion of the key with a 30-day waiting period`,`Deletion cannot be canceled after the waiting period ends, so access could not be restored without a time limit.`],[`Delete the key immediately and recreate it if an application fails`,`AWS KMS requires a waiting period of at least 7 days for deletion, and a deleted key cannot be recovered.`],[`Turn off automatic key rotation on the key`,`This does not stop applications from using the key.`]],slot:2,evidence:[`kms-delete-key|If you are not sure, consider disabling the KMS key instead of deleting it.`,`kms-delete-key|You can re-enable a disabled KMS key and cancel the scheduled deletion of a KMS key, but you cannot recover a deleted KMS key.`,`kms-delete-key|After the waiting period ends you cannot cancel key deletion, and AWS KMS deletes the KMS key.`]}),t({id:`key-vault-025`,building:`key-vault`,bullets:[`1.3-S2`],d:2,tags:[`mock-reserve`,`trap:sse-s3-kms-c`],stem:`A company delivers Amazon S3 server access logs to a central bucket whose default encryption is SSE-KMS with a customer managed key. The security team is already allowed by the key policy of that key, yet the log objects that arrive are encrypted with a key the team cannot use. Which change resolves this with the LEAST effort?`,correct:[`Change the default encryption of the destination bucket to SSE-S3`,`A destination bucket for server access logging must use Amazon S3 managed keys.`],wrong:[[`Add the security team's role to the key policy of the customer managed key`,`The delivered log objects may use a key the team cannot access, so editing this key's policy does not fix it.`],[`Enable an S3 Bucket Key on the destination bucket`,`A Bucket Key reduces AWS KMS requests and does not change which key encrypts the log objects.`],[`Switch the destination bucket to SSE-C and have the log service supply the key`,`The logging service cannot supply customer-provided keys with each request.`]],slot:3,evidence:[`s3-sse-kms|If a bucket is used as a destination for Amazon S3 server access logging, the destination bucket must use Amazon S3 managed keys (SSE-S3).`,`s3-sse-kms|If the destination bucket uses SSE-KMS default encryption, Amazon S3 might deliver log objects that are encrypted with a key that you can't access.`]}),t({id:`key-vault-026`,building:`key-vault`,bullets:[`1.3-S4`],d:2,tags:[`mock-reserve`],stem:`A company copies encrypted data to eu-west-1 and encrypts it there with a separate KMS key. Engineers assumed that the key policy of the us-east-1 key also controls the new key. Which statement describes the correct approach?`,correct:[`Define the permitted principals in the key policy of the eu-west-1 key itself`,`A key policy controls access only to a KMS key in the same Region, so each key needs its own policy.`],wrong:[[`Rely on the us-east-1 key policy, because key policies are global like IAM policies`,`Key policies are Regional, unlike IAM policies, which are global.`],[`Copy the us-east-1 key policy to an IAM group so it applies to every Region`,`A key policy has no effect on a KMS key in another Region, and an IAM group does not replace the key policy.`],[`Share the us-east-1 key with eu-west-1 by adding the Region to its key policy`,`A key policy controls access only to a KMS key in the same Region and cannot extend to another Region.`]],slot:0,evidence:[`kms-key-policies|Unlike IAM policies, which are global, key policies are Regional. A key policy controls access only to a KMS key in the same Region. It has no effect on KMS keys in other Regions.`]})],f=[t({id:`wardens-lodge-001`,building:`wardens-lodge`,bullets:[`1.2-K1`],d:1,tags:[`trap:secrets-manager-vs-parameter-store`],stem:`A company's Python application on Amazon EC2 has a database user name and password written directly in its source code. The security team requires that the credentials be removed from the code, retrieved only when the application needs them, and changed automatically on a schedule. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Store the credentials in AWS Secrets Manager, retrieve them at run time, and enable automatic rotation`,`Secrets Manager replaces hard-coded credentials with a run-time call and can rotate the secret on a schedule, which covers all three requirements.`],wrong:[[`Store the credentials in a Systems Manager Parameter Store String parameter and change the value by hand each quarter`,`It keeps the credentials out of the code, but nothing rotates them automatically, and AWS recommends Secrets Manager for credentials.`],[`Encrypt the credentials with an AWS KMS key and embed the ciphertext in the application source code`,`The credentials would still live in the source code, and every change would need a new deployment of the application.`],[`Save the credentials in an Amazon S3 object and add a cron job on each instance that replaces the object every month`,`It needs custom scripts to fetch and change the credentials, so rotation is not automatic and the operational effort is higher.`]],slot:0,evidence:[`secrets-intro|You replace hard-coded credentials with a runtime call to the Secrets Manager service to retrieve credentials dynamically when you need them.`,`secrets-intro|With Secrets Manager, you can configure an automatic rotation schedule for your secrets.`,`ssm-parameter-store|For secrets such as database credentials, API keys, or tokens, we recommend AWS Secrets Manager, which provides purpose built security controls including automatic rotation and cross-region replication.`]}),t({id:`wardens-lodge-002`,building:`wardens-lodge`,bullets:[`1.2-K4`],d:1,stem:`A startup is building a public mobile app. Customers must be able to sign up with an email address, sign in with their Google accounts, and reset forgotten passwords. The startup does not want to build or host its own user directory. Which AWS service should the startup use to meet these requirements with the LEAST development effort?`,correct:[`An Amazon Cognito user pool with Google configured as a social identity provider`,`A user pool is a user directory for web and mobile app sign-up and sign-in, and users can also sign in through social providers such as Google.`],wrong:[[`AWS IAM Identity Center with a permission set created for each customer who signs up`,`IAM Identity Center connects workforce users to AWS accounts and managed applications; it is not a sign-up directory for public customers.`],[`An IAM user with a console password and an access key created for each new customer`,`It creates long-term IAM identities for the public instead of using a user directory, and it has no social sign-in or app sign-up flow.`],[`An Amazon Cognito identity pool that is configured without any user pool or other directory`,`An identity pool exchanges tokens for AWS credentials; it does not store users or provide sign-up, which is the job of a user pool.`]],slot:1,evidence:[`cognito-what-is|(authentication) Use a user pool.`,`cognito-what-is|Users can sign in directly, through social providers like Google and Apple, or through enterprise SAML and OIDC providers.`,`cognito-user-pools|An Amazon Cognito user pool is a user directory for web and mobile app authentication and authorization.`,`sso-what-is|AWS IAM Identity Center is the AWS solution for connecting your workforce users to AWS managed applications`]}),t({id:`wardens-lodge-003`,building:`wardens-lodge`,bullets:[`1.2-K1`],d:2,tags:[`trap:secrets-manager-vs-parameter-store`],stem:`A company runs several microservices in development, test and production. Each service needs configuration values such as endpoint URLs and feature toggles, and a few of those values must be stored encrypted. The company wants the values organized by environment and service in a path-like structure and read by the services at run time. No credential rotation is required. Which solution meets these requirements MOST simply?`,correct:[`Store the values as Parameter Store parameters in a hierarchy and use SecureString for the encrypted ones`,`Parameter Store is a centralized configuration store with parameter hierarchies, and SecureString parameters are encrypted with AWS KMS.`],wrong:[[`Create one AWS Secrets Manager secret for every value and enable automatic rotation on all of the secrets`,`It adds a per-secret service and rotation that the requirements do not ask for, and plain configuration values are what Parameter Store is for.`],[`Keep the values in a JSON file in an Amazon S3 bucket that each service downloads when it starts`,`It gives no path-based hierarchy per environment and service, and the services would need custom code to parse and protect the file.`],[`Set the values as plaintext environment variables in each service's task definition and redeploy on every change`,`The encrypted values would be exposed in plaintext, and each change would need a redeployment instead of a run-time read.`]],slot:2,evidence:[`ssm-parameter-store|Parameter Store is a centralized configuration data store for named values called parameters.`,`ssm-parameter-store|Hierarchical parameter management Use parameter hierarchies to group related parameters, making it easier to discover, manage, and filter them across environments and applications.`,`ssm-parameter-store|SecureString Use SecureString for configuration values that require encryption, such as service endpoints and account identifiers.`,`ssm-parameter-store|Parameter Store encrypts the values using AWS Key Management Service.`]}),t({id:`wardens-lodge-004`,building:`wardens-lodge`,bullets:[`1.2-K4`],d:2,stem:`A company runs a web application on Amazon EC2 instances behind an Application Load Balancer. Employees must sign in with their corporate identities through a SAML 2.0 identity provider before any request reaches the application, and the company does not want to add sign-in code to the application. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Add an authenticate action to the load balancer listener that uses an Amazon Cognito user pool federated with the SAML provider`,`The load balancer can authenticate users through the user pools of Amazon Cognito, including corporate identities from SAML, so the application needs no sign-in code.`],wrong:[[`Attach an AWS WAF web ACL to the load balancer that allows only requests from the corporate network address range`,`It filters by source address and never identifies individual employees through the SAML identity provider.`],[`Configure an HTTPS listener with an AWS Certificate Manager certificate and a security policy that requires the newest TLS version`,`It encrypts traffic between browser and load balancer but does not authenticate employees at all.`],[`Build a sign-in page into the application that checks employee credentials in a user table in Amazon RDS`,`It requires sign-in code in the application, and it ignores the corporate SAML identity provider.`]],slot:3,evidence:[`alb-authenticate|You can configure an Application Load Balancer to securely authenticate users as they access your applications.`,`alb-authenticate|This enables you to offload the work of authenticating users to your load balancer so that your applications can focus on their business logic.`,`alb-authenticate|Authenticate users through corporate identities, using SAML, OpenID Connect (OIDC), or OAuth, through the user pools supported by Amazon Cognito.`]}),t({id:`wardens-lodge-005`,building:`wardens-lodge`,bullets:[`1.2-K1`],d:2,stem:`A company runs containers on Amazon ECS with AWS Fargate. The containers need a database password when they start. The password must stay out of the container image and out of the plain text of the task definition, and it must be rotated automatically. The company does not want to write code in the containers to fetch it. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Store the password in AWS Secrets Manager and reference the secret in the task definition for Amazon ECS to inject`,`Amazon ECS can inject secrets from Secrets Manager into containers at run time, and Secrets Manager adds automatic rotation.`],wrong:[[`Set the password as a plain text environment variable in the task definition and update the definition each month`,`The password would sit in plain text in the task definition, and rotation would be a manual task.`],[`Bake the password into the container image in Amazon ECR and build a new image whenever the password changes`,`The password would be inside the image, and each rotation would need a new image build and deployment.`],[`Store the password in an encrypted Amazon S3 object and add startup code to each container that downloads the object`,`It requires code in the containers to fetch the value, and nothing rotates the password automatically.`]],slot:0,evidence:[`ecs-sensitive-data|Secrets can be seamlessly injected into containers from AWS Secrets Manager and Amazon EC2 Systems Manager Parameter Store.`,`ecs-sensitive-data|Secrets Manager, however, also includes the ability to automatically rotate secrets, generate random secrets, and share secrets across accounts.`,`ecs-sensitive-data|They're referenced as environment variables that use the secrets container definition parameter.`]}),t({id:`wardens-lodge-006`,building:`wardens-lodge`,bullets:[`1.2-K4`],d:2,stem:`A company exposes a REST API through Amazon API Gateway. Customers of its mobile app sign in with an Amazon Cognito user pool. Only signed-in customers may call the API, and the company wants API Gateway to check each customer's token without writing and maintaining authorization code. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an authorizer of the Cognito user pool type in API Gateway and enable it on the API methods`,`API Gateway can use a Cognito user pool as an authorizer, so signed-in customers present a token and no custom authorization code is needed.`],wrong:[[`Write an AWS Lambda authorizer that parses and verifies the token for every request`,`A Lambda authorizer implements a custom authorization scheme, which is code the company would have to write and maintain.`],[`Require an API key on each method and bundle the same key into the mobile app`,`API keys are not meant for authentication or authorization, and a shared key does not identify each signed-in customer.`],[`Turn on IAM authorization for the methods and create an IAM user with access keys for each customer`,`It creates a long-term IAM identity for every customer, whereas the customers already sign in with the user pool.`]],slot:1,evidence:[`apigw-cognito-authorizer|To use an Amazon Cognito user pool with your API, you must first create an authorizer of the COGNITO_USER_POOLS type and then configure an API method to use that authorizer.`,`apigw-lambda-authorizer|Use a Lambda authorizer to implement a custom authorization scheme.`,`apigw-usage-plans|Don't use API keys for authentication or authorization to control access to your APIs.`]}),t({id:`wardens-lodge-007`,building:`wardens-lodge`,bullets:[`1.2-K1`],d:1,stem:`A developer stored the access key ID and secret access key of an IAM user in a configuration file on an Amazon EC2 instance so that the application can read objects from an Amazon S3 bucket. A security review flags these long-term keys. Which change BEST follows AWS guidance for applications running on AWS?`,correct:[`Delete the keys and attach an IAM role with the needed Amazon S3 permissions to the instance`,`Workloads on AWS should use temporary credentials from an IAM role, which the AWS SDK discovers, so no long-term keys have to be distributed.`],wrong:[[`Restrict the configuration file so that only the application's operating system user can read it`,`The keys are still long-term credentials kept on the instance; the guidance is to avoid distributing them at all.`],[`Encrypt the configuration file with an AWS KMS key and leave the access keys in the encrypted file`,`The application would still depend on long-term keys that someone has to distribute, now with extra decryption steps.`],[`Create a second IAM user for the application and swap the keys in the file every year`,`It replaces one long-term key pair with another and still relies on distributing credentials to the instance.`]],slot:2,evidence:[`iam-best-practices|Applications written using an AWS SDK will discover and use these temporary credentials to access AWS resources, and there is no need to distribute long lived credentials for an IAM user to your workloads running on AWS.`,`iam-best-practices|Where possible, we recommend relying on temporary credentials instead of creating long-term credentials such as access keys.`,`ec2-iam-roles|Amazon EC2 uses an instance profile as a container for an IAM role.`]}),t({id:`wardens-lodge-008`,building:`wardens-lodge`,bullets:[`1.2-K4`],d:2,stem:`A photo-sharing web application lets visitors browse public thumbnails stored in Amazon S3 before they create an account. The browser code calls Amazon S3 with AWS credentials. Visitors who have not signed in must receive credentials with a very narrow read-only scope, and signed-in members must receive broader permissions. Which solution meets these requirements with the LEAST custom code?`,correct:[`Use an Amazon Cognito identity pool with guest access and separate IAM roles for guests and members`,`An identity pool generates temporary AWS credentials for users who have not signed in, with a narrow scope, and can map signed-in users to a broader role.`],wrong:[[`Use an Amazon Cognito user pool alone and send the user pool tokens as the credentials to Amazon S3`,`User pool tokens identify the user to the app; Amazon S3 needs AWS credentials, which come from an identity pool.`],[`Place the read-only access keys of one shared IAM user in the browser code and rotate them each month`,`It puts long-term keys in public code, and it gives signed-in members no separate, broader permissions.`],[`Create guest accounts in AWS IAM Identity Center and have visitors sign in to the AWS access portal first`,`IAM Identity Center is for workforce users, and visitors who have not signed in could not use it.`]],slot:3,evidence:[`cognito-identity-pools|For your users who haven’t signed in yet, configure your identity pool to generate AWS credentials with a narrow scope of access.`,`cognito-identity-pools|Identity pools generate temporary AWS credentials for the users of your app, whether they’ve signed in or you haven’t identified them yet.`,`cognito-identity-pools|Assign a single IAM role to all of your authenticated users, or choose the role based on the claims of each user.`]}),e({id:`wardens-lodge-009`,building:`wardens-lodge`,bullets:[`1.2-K1`],d:3,stem:`A company stores database credentials as a secret in AWS Secrets Manager in Account A. The secret is encrypted with the AWS managed key aws/secretsmanager. An application role in Account B must read the secret value. Which THREE actions are required to allow this access? (Choose three.)`,correct:[[`Re-encrypt the secret with a customer managed KMS key and add a key policy that lets the Account B role use the key`,`The AWS managed key cannot be used for cross-account access, so the secret needs a key that the company creates and a key policy for the other account.`],[`Attach a resource-based policy to the secret that allows the Account B role to read the secret value`,`Cross-account access must be allowed in a resource policy attached to the secret.`],[`Attach an identity-based policy to the Account B role that allows it to read the secret`,`Cross-account access must be allowed in an identity policy as well as in the resource policy.`]],wrong:[[`Add the Account B role to the key policy of the AWS managed key aws/secretsmanager`,`The AWS managed key cannot be used for cross-account access, and its key policy is not the way to grant it.`],[`Replicate the secret to a second Region so that Account B can read the replica without any policy`,`Replication copies the secret across Regions; it does not give another account permission to read it.`],[`Create an IAM user in Account A for the application and copy that user's access keys into Account B`,`It adds long-term keys that must be distributed, whereas the resource policy and identity policy grant access to the role.`]],slots:[1,3,5],evidence:[`secrets-cross-account|To allow users in one account to access secrets in another account (cross-account access), you must allow access both in a resource policy and in an identity policy.`,`secrets-cross-account|This is because you can't use the AWS managed key (aws/secretsmanager) for cross-account access.`,`secrets-cross-account|Instead, you must encrypt your secret with a KMS key that you create, and then attach a key policy to it.`]}),t({id:`wardens-lodge-010`,building:`wardens-lodge`,bullets:[`1.2-K1`],d:2,stem:`An AWS Lambda function reads a third-party API key from an environment variable in its configuration. The vendor requires the key to be replaced every 60 days. The company wants the function to pick up each new key without editing the function configuration or deploying new code, and it wants stronger protection than a configuration setting. Which solution meets these requirements MOST effectively?`,correct:[`Store the key in AWS Secrets Manager, let the function's execution role read the secret, and retrieve it at run time`,`AWS recommends Secrets Manager rather than environment variables for API keys, and a run-time lookup picks up a changed secret without redeploying.`],wrong:[[`Encrypt the environment variable with a customer managed AWS KMS key and update the variable whenever the key changes`,`Encryption protects the value, but every new key still means editing the function configuration.`],[`Place the key in a text file inside the deployment package and upload a new package every 60 days`,`It keeps the key in the code package, and each new key needs a new deployment.`],[`Put the key in a Lambda layer shared by the functions and publish a new layer version for each new key`,`Every new key needs a new layer version and an update of each function, and the key sits in a package.`]],slot:0,evidence:[`lambda-envvars|To increase security, we recommend that you use AWS Secrets Manager instead of environment variables to store database credentials and other sensitive information like API keys or authorization tokens.`,`secrets-intro|Since the credentials are no longer stored with the application, rotating credentials no longer requires updating your applications and deploying changes to application clients.`]}),t({id:`wardens-lodge-011`,building:`wardens-lodge`,bullets:[`1.2-K4`],d:3,stem:`Users of a web application sign in through an Amazon Cognito user pool. Members of the editors group must be able to upload objects to an Amazon S3 bucket directly from the browser, while all other signed-in users may only read objects. Each user must receive only the AWS permissions that match their group. Which solution meets these requirements with the LEAST custom code?`,correct:[`Link each user pool group to an IAM role and pass the ID token to a Cognito identity pool to obtain credentials for that role`,`User pool groups appear in the tokens and can be linked to IAM roles, and the identity pool turns the token into temporary credentials for the matching role.`],wrong:[[`Give every authenticated user one IAM role that allows uploads and hide the upload button for users who are not editors`,`Hiding a button in the app does not limit AWS permissions, so any signed-in user could still upload.`],[`Create an IAM user for each editor and give the editors the access keys through the application`,`It creates long-term IAM users and keys instead of using the groups that the user pool already provides.`],[`Sign the Amazon S3 requests with the access token from the user pool and check the group claim in a bucket policy`,`Amazon S3 does not accept user pool tokens as AWS credentials; an identity pool is needed to obtain them.`]],slot:1,evidence:[`cognito-user-pools|After your users sign up, you can add them to groups that Amazon Cognito lists in the access and ID tokens.`,`cognito-user-pools|You can also link user pool groups to IAM roles when you pass the ID token to an identity pool.`,`cognito-identity-pools|Assign a single IAM role to all of your authenticated users, or choose the role based on the claims of each user.`]}),t({id:`wardens-lodge-012`,building:`wardens-lodge`,bullets:[`1.2-K4`],d:3,stem:`A company is launching an internal analytics portal and a public mobile app. Employees already exist in the corporate identity provider and need single sign-on to the company's AWS accounts and to AWS managed applications such as Amazon Quick. Customers of the mobile app must sign up with an email address or an Apple account. Which combination meets these requirements with the LEAST custom development?`,correct:[`AWS IAM Identity Center for the employees and an Amazon Cognito user pool for the customers`,`IAM Identity Center connects workforce users to AWS accounts and managed applications, and a user pool handles sign-up and sign-in for app users.`],wrong:[[`An Amazon Cognito user pool for the employees and AWS IAM Identity Center for the customers`,`The services are reversed: IAM Identity Center is for the workforce and a user pool is for the app's own users.`],[`IAM users with console passwords for the employees and an Amazon Cognito identity pool for the customers`,`IAM users for people are long-term identities, and an identity pool does not provide a customer sign-up directory.`],[`An Amazon Cognito identity pool for the employees and IAM users with access keys for the customers`,`An identity pool issues AWS credentials rather than workforce single sign-on, and IAM users are not a customer sign-up directory.`]],slot:2,evidence:[`sso-what-is|AWS IAM Identity Center is the AWS solution for connecting your workforce users to AWS managed applications such as Kiro and Amazon Quick, and other AWS resources.`,`cognito-user-pools|An Amazon Cognito user pool is a user directory for web and mobile app authentication and authorization.`,`cognito-what-is|Users can sign in directly, through social providers like Google and Apple, or through enterprise SAML and OIDC providers.`]}),t({id:`wardens-lodge-013`,building:`wardens-lodge`,bullets:[`1.2-K1`],d:2,stem:`A company runs its application in us-east-1 and a second copy in eu-west-1. Both copies use database credentials stored in AWS Secrets Manager. The eu-west-1 application must read the credentials in its own Region with low latency, and a credential rotation in the primary Region must reach the second Region. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Configure the secret to replicate to eu-west-1 and have the second application read the replica`,`Secrets Manager can replicate a secret to other Regions for Regional access and low latency, and a rotated value propagates to the replicas.`],wrong:[[`Create a separate secret in eu-west-1 and run a scheduled AWS Lambda function that copies each new value`,`It works, but the company must write, schedule and maintain the copy function instead of using built-in replication.`],[`Have the eu-west-1 application call the Secrets Manager endpoint in us-east-1 for every credential request`,`Every read would cross Regions, which does not meet the requirement to read in its own Region with low latency.`],[`Copy the credentials into Systems Manager Parameter Store in both Regions and update each copy by hand`,`The manual updates are operational work, and rotation in the primary Region would not reach the other copy automatically.`]],slot:3,evidence:[`secrets-replicate|You can replicate your secrets in multiple AWS Regions to support applications spread across those Regions to meet Regional access and low latency requirements.`,`secrets-replicate|If you turn on rotation for your primary secret, Secrets Manager rotates the secret in the primary Region, and the new secret value propagates to all of the associated replica secrets.`]}),e({id:`wardens-lodge-014`,building:`wardens-lodge`,bullets:[`1.2-K4`],d:2,stem:`A company uses an Amazon Cognito user pool for the sign-in of its public web application. The security team sees password-guessing attempts and automated sign-up abuse against the user pool. Which TWO actions will MOST directly strengthen protection of the sign-in? (Choose two.)`,correct:[[`Turn on multi-factor authentication for the user pool`,`A user pool can require a second factor, such as a one-time password, after the password.`],[`Associate an AWS WAF web ACL with the user pool`,`AWS WAF web ACLs help protect a user pool against malicious traffic, such as automated abuse.`]],wrong:[[`Add an identity pool with guest access in front of the user pool`,`An identity pool issues AWS credentials; it does not defend the sign-in of the user pool.`],[`Apply an IAM account password policy for the application's customers`,`An IAM password policy applies to IAM users, not to the customers stored in a user pool.`],[`Attach a network ACL to the user pool to block suspicious source addresses`,`Network ACLs control traffic for subnets in a VPC, and a user pool is not placed in a subnet.`]],slots:[0,2],evidence:[`cognito-user-pools|Protect your users against password guessing, account takeover, and malicious traffic with multi-factor authentication (MFA), adaptive authentication, and AWS WAF web ACLs.`,`cognito-what-is|Amazon Cognito supports time-based one-time password (TOTP) and SMS message MFA.`]}),e({id:`wardens-lodge-015`,postGuide:[`secrets-manager-managed-external-secrets`],building:`wardens-lodge`,bullets:[`1.2-K1`],d:3,stem:`A company keeps the API key of a third-party payment provider in AWS Secrets Manager. The provider is not an AWS Secrets Manager partner and offers only an API to create a new key. The security policy requires the key to change every 30 days with no manual steps, and the application must keep reading the secret at run time. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Write a rotation function in AWS Lambda that creates the new key at the provider and stores it in the secret`,`For other types of secrets, Secrets Manager rotation uses a Lambda function to update the secret and the service; this provider is neither a managed secret nor a Secrets Manager partner.`],[`Turn on automatic rotation for the secret with a 30-day schedule that uses the rotation function`,`Secrets Manager can rotate a secret automatically on a schedule, and the rotation function does the update.`]],wrong:[[`Enable managed rotation so that Secrets Manager rotates the key at the provider without a Lambda function`,`Managed rotation covers managed secrets, and managed external secrets rotation covers secrets of Secrets Manager partners; a key at a provider that is neither needs a Lambda rotation function.`],[`Add a Systems Manager Parameter Store expiration notification policy and have an administrator replace the key when the notification arrives`,`Parameter Store policies only notify or expire parameters; they do not create a new key at the provider, and the administrator step is manual.`],[`Publish a reminder to an Amazon SNS topic every 30 days so that an administrator replaces the key`,`The administrator performs the change, which breaks the requirement for no manual steps.`]],slots:[2,4],evidence:[`secrets-rotation|Rotation by Lambda function – For other types of secrets, Secrets Manager rotation uses a Lambda function to update the secret and the database or service.`,`secrets-rotation|Rotate Secrets Manager managed external secrets – For secrets held by Secrets Manager partners, you use managed external secrets rotation to update the secret on the partner's system.`,`secrets-rotation|In Secrets Manager, you can set up automatic rotation for your secrets.`,`ssm-parameter-policies|Parameter Store offers the following types of policies: Expiration, ExpirationNotification, and NoChangeNotification.`]}),t({id:`wardens-lodge-016`,building:`wardens-lodge`,bullets:[`1.2-K1`],d:2,tags:[`mock-reserve`],stem:`An application runs on Amazon EC2 instances in private subnets of a VPC that has no internet gateway and no NAT device. The application must retrieve database credentials from AWS Secrets Manager without the traffic crossing the public internet. Which solution meets these requirements MOST simply?`,correct:[`Create an interface VPC endpoint for Secrets Manager in the VPC`,`An interface endpoint, powered by AWS PrivateLink, lets resources reach Secrets Manager privately without an internet gateway or NAT device.`],wrong:[[`Create a gateway VPC endpoint for Secrets Manager and add it to the route tables`,`Gateway endpoints cover only Amazon S3 and DynamoDB, so Secrets Manager needs an interface endpoint.`],[`Add a NAT gateway in a public subnet and route the private subnets through it`,`The traffic would then leave through the internet, which the requirement rules out.`],[`Copy the credentials into the user data of each instance when it launches`,`The credentials would be copied to every instance, and they would no longer be retrieved from Secrets Manager at run time.`]],slot:1,evidence:[`secrets-vpc-endpoint|You can establish a private connection between your VPC and Secrets Manager by creating an interface VPC endpoint.`,`secrets-vpc-endpoint|Interface endpoints are powered by AWS PrivateLink, a technology that enables you to privately access Secrets Manager APIs without an internet gateway, NAT device, VPN connection, or Direct Connect connection.`,`vpce-gateway|Gateway VPC endpoints provide reliable connectivity to Amazon S3 and DynamoDB without requiring an internet gateway or a NAT device for your VPC.`]}),t({id:`wardens-lodge-017`,building:`wardens-lodge`,bullets:[`1.2-K4`],d:1,tags:[`mock-reserve`],stem:`A company's web application authenticates customers with an Amazon Cognito user pool. The security team wants customers to enter a one-time code from an authenticator app after they type their password. Which solution meets this requirement with the LEAST effort?`,correct:[`Turn on multi-factor authentication in the user pool and allow time-based one-time passwords`,`Cognito supports time-based one-time password and SMS message MFA, and user pools can add multi-factor authentication after sign-in.`],wrong:[[`Create an IAM user with a virtual MFA device for every customer and have them sign in with those users`,`It moves the customers out of the user pool into IAM users, which is the wrong identity type for app customers.`],[`Configure the Cognito identity pool to require a second factor before it issues AWS credentials`,`An identity pool exchanges identities for AWS credentials; the sign-in factors are set in the user pool.`],[`Add an AWS WAF rule that blocks sign-in requests that do not include a one-time code header`,`AWS WAF inspects web requests but does not generate or verify one-time codes for users.`]],slot:2,evidence:[`cognito-what-is|Amazon Cognito supports time-based one-time password (TOTP) and SMS message MFA.`,`cognito-user-pools|Managed login is a set of web pages for sign-up, sign-in, multi-factor authentication (MFA), and password reset.`]}),e({id:`wardens-lodge-018`,building:`wardens-lodge`,bullets:[`1.2-K4`],d:2,tags:[`mock-reserve`],stem:`A software-as-a-service company runs a web application whose users sign in through an Amazon Cognito user pool. Some business customers want their employees to sign in with their own SAML 2.0 identity provider, and consumer users want to sign in with their Google accounts. The application must receive one consistent kind of token from the user pool. Which TWO configurations meet these requirements? (Choose two.)`,correct:[[`Add each customer's SAML 2.0 identity provider to the user pool as an enterprise identity provider`,`A user pool turns SAML 2.0 assertions into user profiles and tokens, so the application sees one token format.`],[`Add Google to the user pool as a social identity provider`,`A user pool lets users sign in through social providers such as Google and issues its own tokens to the application.`]],wrong:[[`Create an IAM user in the company's account for every employee of every business customer`,`It creates a large number of long-term IAM identities and bypasses the user pool and the customers' own identity providers.`],[`Create an IAM role for each customer and give the customers' employees console access to it`,`It gives employees access to the AWS Management Console, which is not application sign-in with the user pool.`],[`Create AWS IAM Identity Center permission sets for each customer's employees`,`IAM Identity Center is for the company's own workforce and AWS accounts, not for the application's external users.`]],slots:[1,4],evidence:[`cognito-user-pools|Amazon Cognito processes OIDC id tokens, OAuth 2.0 userInfo data, and SAML 2.0 assertions into user profiles in your user pool.`,`cognito-what-is|Users can sign in directly, through social providers like Google and Apple, or through enterprise SAML and OIDC providers.`]})],p=[t({id:`watchtower-001`,building:`watchtower`,bullets:[`1.2-K5`],d:1,stem:`A company keeps customer documents in Amazon S3 buckets. The security team must discover which objects contain personal data such as names and card numbers. Which AWS service BEST meets this requirement?`,correct:[`Amazon Macie`,`Macie discovers sensitive data in Amazon S3 by using machine learning and pattern matching.`],wrong:[[`Amazon GuardDuty`,`GuardDuty detects suspicious activity in logs and accounts, and it does not classify the contents of S3 objects.`],[`Amazon Inspector`,`Inspector scans workloads for software vulnerabilities and unintended network exposure, not for personal data.`],[`AWS Shield`,`Shield protects applications against DDoS attacks and does not look inside stored objects.`]],slot:0,evidence:[`macie|Amazon Macie is a data security service that discovers sensitive data by using machine learning and pattern matching, provides visibility into data security risks, and enables automated protection against those risks.`]}),t({id:`watchtower-002`,building:`watchtower`,bullets:[`1.2-K6`],d:2,tags:[`placement-eligible`,`trap:shield-vs-waf`],stem:`A company serves its web application through an Amazon CloudFront distribution. A small set of client IP addresses now sends a flood of HTTP requests that look valid and slows the origin. The company wants to rate limit those clients with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Associate an AWS WAF web ACL that contains a rate-based rule with the distribution`,`A rate-based rule counts incoming requests and rate limits them when they arrive too fast, and a web ACL can be associated with a CloudFront distribution.`],wrong:[[`Rely on AWS Shield Standard, which already blocks floods of web requests`,`Shield Standard defends against network and transport layer attacks, and a flood of valid-looking web requests is an application layer attack.`],[`Deploy AWS Network Firewall in the VPC of the origin to rate limit the HTTP requests`,`Network Firewall filters traffic at the perimeter of a VPC and is not a way to rate limit by client on a CloudFront distribution.`],[`Enable Amazon GuardDuty and review its findings about the clients`,`GuardDuty detects threats and generates findings, and it does not rate limit or block requests.`]],slot:1,evidence:[`waf-rate-based|A rate-based rule counts incoming requests and rate limits requests when they are coming at too fast a rate.`,`waf-cloudfront|When you create a protection pack (web ACL), you can specify one or more CloudFront distributions that you want AWS WAF to inspect.`,`shield-overview|Application layer attacks (layer 7) – This category of attack vector attempts to deny service to legitimate users by flooding an application with queries that are valid for the target, such as web request floods.`]}),t({id:`watchtower-003`,building:`watchtower`,bullets:[`1.2-K5`],d:2,stem:`A company runs Amazon EC2 instances, stores container images in Amazon ECR, and deploys AWS Lambda functions. The security team wants these workloads discovered and continually scanned for software vulnerabilities without scheduling any scans. Which service BEST meets these requirements?`,correct:[`Amazon Inspector`,`Inspector automatically discovers workloads and continually scans EC2 instances, container images in ECR, and Lambda functions.`],wrong:[[`Amazon GuardDuty`,`GuardDuty analyzes logs and data sources for threats and does not scan workloads for software vulnerabilities.`],[`Amazon Macie`,`Macie discovers sensitive data in Amazon S3 and does not scan compute workloads for vulnerabilities.`],[`Amazon Detective`,`Detective helps investigate findings after the fact and does not scan workloads.`]],slot:2,evidence:[`inspector|Amazon Inspector is a vulnerability management service that automatically discovers workloads and continually scans them for software vulnerabilities and unintended network exposure.`,`inspector|Amazon Inspector discovers and scans Amazon EC2 instances, container images in Amazon ECR, and Lambda functions.`,`inspector|With Amazon Inspector, you don't need to manually schedule or configure assessment scans.`]}),t({id:`watchtower-004`,building:`watchtower`,bullets:[`1.2-K6`,`1.2-S3`],d:3,tags:[`placement-eligible`],stem:`A company exposes a public REST API with Amazon API Gateway in one Region. The security team needs requests that carry malicious SQL code and requests from specific countries blocked before any other access control logic runs, with the LEAST custom code. Which solution meets these requirements?`,correct:[`Associate a same-Region AWS WAF web ACL that has SQL injection and geographic rules with the API stage`,`AWS WAF rules are evaluated before other access controls, and a web ACL can block malicious SQL code and requests from a specific country.`],wrong:[[`Create the AWS WAF web ACL with the same rules in a different Region and associate it with the API stage`,`The web ACL and the AWS WAF resources it uses must be located in the same Region as the API.`],[`Write an AWS Lambda authorizer that inspects each request for SQL code and the country of origin`,`This needs custom code to build and maintain, and AWS WAF already provides these rule types.`],[`Subscribe to AWS Shield Advanced and add protection for the API Gateway REST API`,`Shield Advanced does not list API Gateway among its protected resource types and does not inspect requests for SQL code.`]],slot:3,evidence:[`apigw-waf|You can use AWS WAF to protect your API Gateway REST API from common web exploits, such as SQL injection and cross-site scripting (XSS) attacks.`,`apigw-waf|The web ACL and any other AWS WAFV2 resources that it uses must be located in the same Region as your API.`,`apigw-waf|When AWS WAF is enabled on an API, AWS WAF rules are evaluated before other access control features, such as resource policies, IAM policies, Lambda authorizers, and Amazon Cognito authorizers.`,`shield-protected-resources|You can use Shield Advanced for advanced monitoring and protection with the following resource types:`]}),t({id:`watchtower-005`,building:`watchtower`,bullets:[`1.2-K6`],d:1,stem:`A company hosts a web application behind an Application Load Balancer. Attackers send web requests that contain malicious SQL code to modify the database. Which solution BEST protects the application from these requests?`,correct:[`An AWS WAF web ACL with a SQL injection rule statement on the load balancer`,`A SQL injection rule statement inspects requests for malicious SQL code, and a web ACL can protect an Application Load Balancer.`],wrong:[[`AWS Shield Standard enabled on the Application Load Balancer`,`Shield Standard defends against network and transport layer DDoS attacks and does not inspect requests for SQL code.`],[`Amazon Inspector scheduled scans of the load balancer and the instances behind it every night`,`Inspector scans EC2 instances, container images, and Lambda functions for vulnerabilities and does not filter web requests.`],[`Amazon Macie on the database backups stored in Amazon S3`,`Macie discovers sensitive data in Amazon S3 and does not block malicious requests.`]],slot:0,evidence:[`waf-sqli|An SQL injection rule statement inspects for malicious SQL code. Attackers insert malicious SQL code into web requests in order to do things like modify your database or extract data from it.`,`waf-what-is|You can protect the following resource types: Amazon CloudFront distributionAmazon API Gateway REST APIApplication Load Balancer`]}),e({id:`watchtower-006`,building:`watchtower`,bullets:[`1.2-K5`],d:2,stem:`A security team enables Amazon GuardDuty in an account and turns on no optional protection plans. Which THREE data sources does GuardDuty analyze automatically? (Choose three.)`,correct:[[`AWS CloudTrail management events`,`CloudTrail management events are one of the foundational data sources that GuardDuty ingests when it is enabled.`],[`VPC Flow Logs`,`VPC Flow Logs are a foundational data source that GuardDuty ingests automatically.`],[`DNS logs`,`DNS logs are a foundational data source that GuardDuty ingests automatically.`]],wrong:[[`Application Load Balancer access logs`,`They are not one of the foundational data sources that GuardDuty ingests when enabled.`],[`Amazon S3 server access logs`,`They are not one of the foundational data sources that GuardDuty ingests when enabled.`],[`AWS Config configuration snapshots`,`They are not one of the foundational data sources that GuardDuty ingests when enabled.`]],slots:[0,2,4],evidence:[`guardduty|When you enable GuardDuty in an AWS account, GuardDuty automatically starts ingesting the foundational data sources associated with that account. These data sources include AWS CloudTrail management events, VPC flow logs (from Amazon EC2 instances), and DNS logs.`,`guardduty|You don't need to enable anything else for GuardDuty to start analyzing and processing these data sources to generate associated security findings.`]}),t({id:`watchtower-007`,building:`watchtower`,bullets:[`1.2-S3`],d:3,tags:[`placement-eligible`,`trap:shield-vs-waf`],stem:`An online retailer serves its site through Amazon CloudFront with an Application Load Balancer as the origin. The company wants expanded DDoS protection, some protection against scaling charges that a DDoS attack could cause, and direct access to DDoS specialists during an attack. The company has an Enterprise Support plan. Which solution BEST meets these requirements?`,correct:[`Subscribe to AWS Shield Advanced and add protection to the distribution and the load balancer`,`Shield Advanced offers cost protection and access to the Shield Response Team, and it protects only the resources that you add.`],wrong:[[`Keep AWS Shield Standard, which already protects every AWS customer automatically`,`Shield Standard protects against common network and transport layer attacks and does not provide cost protection or the Shield Response Team.`],[`Subscribe to AWS Shield Advanced and rely on it to protect all resources in the account automatically`,`Shield Advanced does not protect resources automatically, so each resource must be added.`],[`Associate an AWS WAF web ACL with rate-based rules with the distribution`,`AWS WAF filters web requests and is not the offering with DDoS cost protection and the Shield Response Team.`]],slot:1,evidence:[`shield-capabilities|Cost protection opportunities – Shield Advanced offers some cost protection against spikes in your AWS bill that might result from a DDoS attack against your protected resources.`,`shield-capabilities|To use the services of the SRT, you must also be subscribed to the Business Support plan or the Enterprise Support plan.`,`shield-protected-resources|Shield Advanced doesn't automatically protect your resources.`]}),t({id:`watchtower-008`,building:`watchtower`,bullets:[`1.2-K5`],d:2,stem:`A company runs Amazon GuardDuty, Amazon Inspector, and Amazon Macie in several accounts. The security team wants a single pane of glass that collects these findings and also runs checks against security standards. Which service BEST meets these requirements?`,correct:[`AWS Security Hub`,`Security Hub receives findings from services such as GuardDuty, Inspector, and Macie and runs checks against security controls.`],wrong:[[`Amazon Detective`,`Detective helps investigate a finding by showing related activity and is not the central place for findings and standards checks.`],[`AWS Firewall Manager`,`Firewall Manager applies protections such as AWS WAF rules across accounts and does not collect these findings.`],[`Amazon CloudWatch dashboards`,`Dashboards visualize metrics and logs and do not run checks against security standards.`]],slot:2,evidence:[`security-hub|This gives you a single pane of glass into a variety of security-related issues.`,`security-hub|Security Hub CSPM runs checks against security controls and generates control findings to help you assess your compliance against security best practices.`,`securityhub-ga|Security Hub automatically aggregates and correlates signals from Amazon GuardDuty, Amazon Inspector, AWS Security Hub Cloud Security Posture Management (AWS Security Hub CSPM), and Amazon Macie`]}),t({id:`watchtower-009`,building:`watchtower`,bullets:[`1.2-K6`],d:2,tags:[`trap:shield-vs-waf`],stem:`A company runs a web application behind an Application Load Balancer. The security team wants protection against common web exploits, including some of the OWASP Top 10 vulnerabilities, without writing and maintaining its own rules. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`An AWS WAF web ACL on the load balancer that uses the AWS Managed Rules core rule set`,`The core rule set is a managed rule group that AWS writes and maintains, and it protects against a wide range of web vulnerabilities, including OWASP Top 10 risks.`],wrong:[[`AWS Shield Advanced protection on the load balancer`,`Shield Advanced is a DDoS protection service and does not supply rules against the exploitation of web application vulnerabilities.`],[`An AWS WAF web ACL with string match rules that the team writes for each known exploit`,`It works, but the team must write and maintain every rule itself, which is the overhead the company wants to avoid.`],[`Amazon Inspector scans of the instances behind the load balancer`,`Amazon Inspector scans workloads for software vulnerabilities and does not inspect or block web requests.`]],slot:3,evidence:[`waf-managed-groups|Managed rule groups are collections of predefined, ready-to-use rules that AWS and AWS Marketplace sellers write and maintain for you.`,`waf-crs|This provides protection against exploitation of a wide range of vulnerabilities, including some of the high risk and commonly occurring vulnerabilities described in OWASP publications such as OWASP Top 10.`]}),e({id:`watchtower-010`,building:`watchtower`,bullets:[`1.2-K6`,`1.2-S3`],d:3,tags:[`placement-eligible`,`trap:shield-vs-waf`],stem:`A company serves a search application through Amazon CloudFront. Attackers put malicious SQL code in query strings, and a list of known abusive IP addresses keeps sending requests. The company wants both blocked with the LEAST operational overhead. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Add a SQL injection rule statement that inspects the query string to a web ACL associated with the distribution`,`The SQL injection rule statement inspects requests for malicious SQL code, and the web ACL protects the distribution.`],[`Add an IP set match rule that blocks the abusive addresses to the same web ACL`,`An IP set match rule statement lets you block web requests based on the IP addresses that the requests originate from.`]],wrong:[[`Enable AWS Shield Standard on the distribution for the SQL injection requests`,`Shield Standard protects against network and transport layer DDoS attacks and does not inspect query strings.`],[`Add deny rules for the abusive addresses to the security group of the origin`,`A security group can hold allow rules only, so it cannot hold deny rules.`],[`Run Amazon GuardDuty to block the abusive addresses`,`GuardDuty detects suspicious activity and generates findings but does not block requests.`]],slots:[1,3],evidence:[`waf-sqli|An SQL injection rule statement inspects for malicious SQL code.`,`waf-ipset|Use this to allow or block web requests based on the IP addresses that the requests originate from.`,`waf-cloudfront|When you create a protection pack (web ACL), you can specify one or more CloudFront distributions that you want AWS WAF to inspect.`,`vpc-sg-rules|You can specify allow rules, but not deny rules.`]}),t({id:`watchtower-011`,building:`watchtower`,bullets:[`1.2-K5`],d:1,stem:`A company wants a managed service that continuously monitors its AWS account and log data and alerts it to suspicious activity such as compromised AWS credentials. Which service is the BEST fit for the company?`,correct:[`Amazon GuardDuty`,`GuardDuty continuously monitors AWS data sources and logs and detects threats such as compromised credentials.`],wrong:[[`Amazon Macie`,`Macie discovers sensitive data in Amazon S3 and is not the service that monitors the account for compromised credentials.`],[`AWS WAF`,`AWS WAF filters web requests to protected resources and does not analyze account activity.`],[`AWS Secrets Manager`,`Secrets Manager stores and rotates secrets and does not detect threats.`]],slot:0,evidence:[`guardduty|Amazon GuardDuty is a threat detection service that continuously monitors, analyzes, and processes AWS data sources and logs in your AWS environment.`,`guardduty|Compromised and exfiltrated AWS credentials.`]}),t({id:`watchtower-012`,building:`watchtower`,bullets:[`1.2-S3`],d:3,tags:[`placement-eligible`],stem:`A public REST API on Amazon API Gateway is overused by a few client IP addresses. The company wants to cap the requests that each client IP address may send in a rolling five-minute period and block addresses over the cap, with other clients unaffected. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`An AWS WAF rate-based rule in a web ACL associated with the API stage`,`A rate-based rule can set the number of requests allowed by each client IP address in a trailing five-minute period.`],wrong:[[`An API Gateway usage plan with a throttling rate for the API`,`A usage plan sets limits for the clients that hold its API keys and does not work by client IP address.`],[`AWS Shield Advanced protection on the API Gateway REST API`,`API Gateway is not among the resource types that Shield Advanced lists, and Shield does not cap requests by client IP address.`],[`An AWS Lambda authorizer that counts requests per client IP address`,`It needs custom code and a store for the counts, which is more work than a managed rule.`]],slot:1,evidence:[`apigw-waf|For example, you can use rate-based rules to specify the number of web requests that are allowed by each client IP in a trailing, continuously updated, 5-minute period.`,`apigw-usage-plans|A usage plan specifies who can access one or more deployed API stages and methods—and optionally sets the target request rate to start throttling requests.`]}),e({id:`watchtower-013`,building:`watchtower`,bullets:[`1.2-S3`],d:2,stem:`Applications in a VPC must reach only approved internet domains. A company wants to block a custom list of known bad domains and to pass traffic only from known AWS service domains such as Amazon S3. Which TWO capabilities meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`An AWS Network Firewall rule that uses a custom list of known bad domains`,`Network Firewall can use custom lists of known bad domains to limit the domain names that applications can access.`],[`An AWS Network Firewall rule that passes traffic only from known AWS service domains or IP address endpoints`,`Network Firewall can pass traffic through only from known AWS service domains or IP address endpoints, such as Amazon S3.`]],wrong:[[`A security group rule that denies the bad domain names`,`A security group can hold allow rules only, and its rules name addresses, not domains.`],[`Amazon Inspector findings about network exposure`,`Inspector reports vulnerabilities and unintended network exposure and does not filter traffic by domain.`],[`Amazon GuardDuty findings that block the domains`,`GuardDuty detects threats and generates findings and does not filter traffic.`]],slots:[2,4],evidence:[`network-firewall|Pass traffic through only from known AWS service domains or IP address endpoints, such as Amazon S3.`,`network-firewall|Use custom lists of known bad domains to limit the types of domain names that your applications can access.`,`vpc-sg-rules|You can specify allow rules, but not deny rules.`]}),t({id:`watchtower-014`,building:`watchtower`,bullets:[`1.2-K5`],d:2,stem:`Amazon GuardDuty reports unusual API activity from an IAM role. The security team wants to investigate the related user and resource interactions to find the root cause. Which service is the BEST choice for the team?`,correct:[`Amazon Detective`,`Detective builds a dataset from log data with machine learning, statistical analysis, and graph theory to support security investigations.`],wrong:[[`Amazon Macie`,`Macie discovers sensitive data in Amazon S3 and does not investigate API activity.`],[`Amazon Inspector`,`Inspector scans workloads for vulnerabilities and does not investigate the cause of a finding.`],[`AWS Shield Advanced`,`Shield Advanced protects against DDoS attacks and does not investigate account activity.`]],slot:2,evidence:[`detective|Amazon Detective automatically collects log data from your AWS resources and uses machine learning (ML), statistical analysis, and graph theory to build a dataset that you can use to conduct more efficient security investigations.`,`detective|Determine potential security issues through a unified view of user and resource interactions.`]}),t({id:`watchtower-015`,building:`watchtower`,bullets:[`1.2-S3`],d:3,tags:[`placement-eligible`],stem:`An Amazon API Gateway REST API has a resource policy that allows requests from a partner CIDR block. A security engineer associates an AWS WAF web ACL with the API stage, and the web ACL has a rule that blocks that same CIDR block. What happens to a request from the partner CIDR block?`,correct:[`AWS WAF blocks the request, and the resource policy is not evaluated`,`AWS WAF rules are evaluated before resource policies, so the block takes precedence over the allow.`],wrong:[[`The resource policy allows the request, because an explicit allow overrides a block rule`,`AWS WAF is evaluated first, and its block takes precedence over the resource policy.`],[`API Gateway evaluates both and allows the request if either one allows it`,`The resource policy is not evaluated when AWS WAF has already blocked the request.`],[`The request goes to a Lambda authorizer, which makes the final decision`,`AWS WAF rules are evaluated before Lambda authorizers.`]],slot:3,evidence:[`apigw-waf|For example, if AWS WAF blocks access from a CIDR block that a resource policy allows, AWS WAF takes precedence and the resource policy isn't evaluated.`,`apigw-waf|When AWS WAF is enabled on an API, AWS WAF rules are evaluated before other access control features, such as resource policies, IAM policies, Lambda authorizers, and Amazon Cognito authorizers.`]}),t({id:`watchtower-016`,building:`watchtower`,bullets:[`1.2-K5`],d:1,stem:`A company is building a mobile app and needs a managed user directory where customers can sign up and sign in, including with social identity providers such as Google. Which service meets these requirements with the LEAST effort?`,correct:[`An Amazon Cognito user pool`,`A user pool is a user directory that authenticates users who sign in directly or through social providers.`],wrong:[[`AWS IAM Identity Center`,`IAM Identity Center connects workforce users to AWS accounts and applications and is not the directory for app customers.`],[`AWS Secrets Manager`,`Secrets Manager stores and rotates secrets and is not a user directory.`],[`Amazon GuardDuty`,`GuardDuty detects threats and does not authenticate users.`]],slot:0,evidence:[`cognito-what-is|Amazon Cognito is an identity platform for web and mobile apps. It’s a user directory, an authentication server, and an authorization service for OAuth 2.0 access tokens and AWS credentials.`,`sso-what-is|AWS IAM Identity Center is the AWS solution for connecting your workforce users to AWS managed applications such as Kiro and Amazon Quick, and other AWS resources.`]}),t({id:`watchtower-017`,building:`watchtower`,bullets:[`1.2-K6`],d:3,tags:[`placement-eligible`,`trap:shield-vs-waf`],stem:`A company runs an internet-facing Application Load Balancer. It wants application layer (layer 7) DDoS attacks against the load balancer to be mitigated automatically as they are detected, without the team writing and tuning rules. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Subscribe to AWS Shield Advanced, protect the load balancer, and enable automatic layer 7 mitigation`,`Shield Advanced can respond automatically to layer 7 attacks against protected resources by managing AWS WAF protections.`],wrong:[[`Rely on AWS Shield Standard, which defends all AWS customers automatically at the network layer`,`Shield Standard covers network and transport layer attacks, not automatic layer 7 mitigation.`],[`Write an AWS WAF rate-based rule and keep tuning its limit each time a new attack pattern occurs`,`It needs the team to write and tune rules, which the company wants to avoid.`],[`Deploy AWS Network Firewall with a stateful rule group in front of the load balancer and update the rules during each attack`,`Network Firewall filters traffic at the VPC perimeter and is not the automatic layer 7 mitigation of Shield Advanced.`]],slot:1,evidence:[`shield-capabilities|You can configure Shield Advanced to respond automatically to mitigate application layer (layer 7) attacks against your protected resources.`,`shield-capabilities|With automatic mitigation, Shield Advanced enforces AWS WAF rate limiting on requests from known DDoS sources, and it automatically adds and manages custom AWS WAF protections in response to detected DDoS attacks.`,`shield-protected-resources|Application Load Balancers.`]}),e({id:`watchtower-018`,building:`watchtower`,bullets:[`1.2-K5`],d:2,stem:`A company stores customer files in Amazon S3 and runs workloads in several accounts. The security team must discover personal data in the S3 buckets and must detect compromised AWS credentials in the accounts. Which TWO services meet these requirements? (Choose two.)`,correct:[[`Amazon Macie`,`Macie discovers sensitive data in Amazon S3 by using machine learning and pattern matching.`],[`Amazon GuardDuty`,`GuardDuty can detect compromised and exfiltrated AWS credentials.`]],wrong:[[`Amazon Inspector`,`Inspector scans workloads for software vulnerabilities and unintended network exposure.`],[`Amazon Detective`,`Detective helps investigate findings and does not discover sensitive data or detect threats.`],[`AWS Shield Advanced`,`Shield Advanced protects resources against DDoS attacks.`]],slots:[0,3],evidence:[`macie|Amazon Macie is a data security service that discovers sensitive data by using machine learning and pattern matching, provides visibility into data security risks, and enables automated protection against those risks.`,`guardduty|Compromised and exfiltrated AWS credentials.`]}),t({id:`watchtower-019`,building:`watchtower`,bullets:[`1.2-K6`],d:2,tags:[`trap:shield-vs-waf`],stem:`A small company serves a static website through Amazon CloudFront and wants protection from common network and transport layer DDoS attacks. The company does not want an additional subscription or setup. What is the SIMPLEST way to protect the site?`,correct:[`Use AWS Shield Standard, which already covers CloudFront distributions at no extra charge`,`Shield Standard gives all AWS customers automatic protection, and CloudFront distributions get comprehensive availability protection from it.`],wrong:[[`Subscribe to AWS Shield Advanced and add protection to the CloudFront distribution for the network layers`,`It is an extra subscription, and the company only needs protection that is already included.`],[`Create an AWS WAF web ACL with a rate-based rule and associate it with the distribution`,`A rate-based rule limits request floods at the application layer and needs setup, and Shield Standard already covers the network and transport layers.`],[`Deploy AWS Network Firewall in a VPC in front of the distribution to filter the traffic`,`Network Firewall protects a VPC and is extra setup that a CloudFront distribution does not need for this.`]],slot:2,evidence:[`shield-standard|All AWS customers benefit from the automatic protection of Shield Standard, at no additional charge.`,`shield-standard|While Shield Standard helps protect all AWS customers, you get particular benefit with Amazon Route 53 hosted zones, Amazon CloudFront distributions, and AWS Global Accelerator standard accelerators. These resources receive comprehensive availability protection against all known network and transport layer attacks.`]}),e({id:`watchtower-020`,building:`watchtower`,bullets:[`1.2-S3`],d:2,tags:[`trap:secrets-manager-vs-parameter-store`],stem:`An application on Amazon EC2 has a database password hard coded in its source code. The security team wants the hard-coded credential removed and the password rotated automatically on a schedule, with no application redeployment for each rotation. Which TWO actions meet these requirements in the MOST secure way? (Choose two.)`,correct:[[`Store the credential in AWS Secrets Manager and configure an automatic rotation schedule`,`Secrets Manager can rotate credentials on an automatic schedule, so rotating no longer needs changes to the application.`],[`Change the application to retrieve the credential from Secrets Manager at runtime`,`Replacing hard-coded credentials with a runtime call lets the application get credentials dynamically when it needs them.`]],wrong:[[`Store the password in an environment variable of the instance and change it each quarter`,`It keeps a long-term secret outside a managed rotation, and every change needs manual effort.`],[`Store the password as a plain string parameter in AWS Systems Manager Parameter Store`,`AWS recommends Secrets Manager for credentials that need rotation.`],[`Encrypt the password in a file in Amazon S3 and download it at startup`,`It adds custom work and has no rotation schedule.`]],slots:[1,4],evidence:[`secrets-intro|With Secrets Manager, you can configure an automatic rotation schedule for your secrets.`,`secrets-intro|You replace hard-coded credentials with a runtime call to the Secrets Manager service to retrieve credentials dynamically when you need them.`,`ssm-parameter-store|If you manage credentials such as usernames, passwords, or any other secrets, we recommend using AWS Secrets Manager.`]}),t({id:`watchtower-021`,building:`watchtower`,bullets:[`1.2-S3`],d:1,stem:`A company wants to give its workforce users single sign-on access to several AWS accounts and AWS managed applications, managed centrally. Which AWS service BEST meets these requirements?`,correct:[`AWS IAM Identity Center`,`IAM Identity Center connects workforce users to AWS accounts and AWS managed applications and manages their access centrally.`],wrong:[[`Amazon Cognito user pools`,`User pools are a directory for the customers of a web or mobile app and not the service for workforce access to AWS accounts.`],[`AWS Secrets Manager`,`Secrets Manager stores and rotates secrets and does not provide sign-on.`],[`AWS Firewall Manager`,`Firewall Manager applies firewall protections across accounts and does not provide sign-on.`]],slot:3,evidence:[`sso-what-is|AWS IAM Identity Center is the AWS solution for connecting your workforce users to AWS managed applications such as Kiro and Amazon Quick, and other AWS resources.`,`sso-what-is|IAM Identity Center streamlines and simplifies workforce user access to applications or AWS accounts, or both, through the following key capabilities.`]}),t({id:`watchtower-022`,building:`watchtower`,bullets:[`1.2-K5`],d:2,stem:`A company stores data in hundreds of Amazon S3 buckets across several accounts. The security team wants continuous, broad visibility into where sensitive data might be across all of the buckets, without defining a job for each bucket. Separately, the compliance team needs one bucket that received a data migration yesterday analyzed one time, with a sampling depth that the team chooses. Which combination of Amazon Macie features meets these requirements?`,correct:[`Automated sensitive data discovery for the accounts, plus a one-time sensitive data discovery job for the migrated bucket`,`Automated discovery continually evaluates the bucket inventory without jobs, and a job lets the team pick the bucket and sampling depth and run it once.`],wrong:[[`Recurring sensitive data discovery jobs that list every bucket in every account, with no automated discovery`,`Each job analyzes only the buckets that the team defines, so the team must keep defining jobs instead of getting continuous visibility without them.`],[`Automated sensitive data discovery for the accounts only, relying on its sampling for the migrated bucket`,`Automated discovery selects representative objects on its own, so the team cannot choose the sampling depth or run a one-time analysis of one bucket.`],[`The bucket inventory and policy findings for all buckets, plus a one-time discovery job for the migrated bucket`,`The inventory and policy findings evaluate the security and access control of the buckets and do not show where sensitive data might be across all of them.`]],slot:0,evidence:[`macie|With this option, Macie continually evaluates your S3 bucket inventory and uses sampling techniques to identify and select representative S3 objects from your buckets.`,`macie|With this option, you define the breadth and depth of the analysis—the S3 buckets to analyze, the sampling depth, and custom criteria that derive from properties of S3 objects.`,`macie|You can also configure a job to run only once for on-demand analysis and assessment, or on a recurring basis for periodic analysis, assessment, and monitoring.`]}),t({id:`watchtower-023`,building:`watchtower`,bullets:[`1.2-S3`],d:2,tags:[`placement-eligible`],stem:`A company uses AWS Organizations and runs Amazon CloudFront distributions in many accounts. The security team wants an AWS WAF web ACL applied to every CloudFront distribution in every account, including distributions created later, managed from one place with the LEAST effort. Which solution meets these requirements?`,correct:[`Use AWS Firewall Manager with an AWS WAF policy for all CloudFront distributions in the organization`,`Firewall Manager protects all resources of a type, such as all CloudFront distributions, and adds protection to new resources automatically.`],wrong:[[`Create and associate a web ACL by hand in each account, and repeat that step whenever a distribution is added`,`It repeats manual work in every account and leaves new distributions unprotected until someone acts.`],[`Subscribe each account to AWS Shield Advanced and rely on it to apply the web ACL`,`Shield Advanced protects resources that you add and is not the service that applies a web ACL across accounts.`],[`Enable Amazon GuardDuty in every account to block requests to the distributions`,`GuardDuty detects threats and generates findings and does not apply a web ACL.`]],slot:1,evidence:[`firewall-manager|Helps to protect all resources of a particular type, such as all Amazon CloudFront distributions`,`firewall-manager|Automatically adds protection to resources that are added to your account`]}),t({id:`watchtower-024`,building:`watchtower`,bullets:[`1.2-K5`],d:2,tags:[`mock-reserve`],stem:`Users of a mobile app sign in with an Amazon Cognito user pool. After sign-in, the app must upload files directly to Amazon S3 using temporary, limited-privilege AWS credentials. What should the architect add to meet this requirement?`,correct:[`An Amazon Cognito identity pool that exchanges the user pool token for AWS credentials`,`An identity pool exchanges a trusted token for temporary, limited-privilege AWS credentials.`],wrong:[[`An IAM user for every app user, with long-term access keys stored in the app`,`It would put long-term credentials in the app and does not use the sign-in token.`],[`An AWS WAF web ACL on the user pool that issues the credentials`,`AWS WAF filters web requests and does not issue AWS credentials.`],[`An AWS Secrets Manager secret that the app reads before each upload`,`A shared secret does not give each signed-in user temporary, limited-privilege credentials.`]],slot:2,evidence:[`cognito-what-is|An identity pool exchanges a trusted token (from a user pool, a social provider, or a SAML or OIDC provider) for temporary, limited-privilege AWS credentials so that your app can call services like Amazon S3 and Amazon DynamoDB on the user’s behalf.`]}),t({id:`watchtower-025`,building:`watchtower`,bullets:[`1.2-K6`],d:3,tags:[`mock-reserve`,`trap:shield-vs-waf`],stem:`A game backend runs behind a Network Load Balancer that uses Elastic IP addresses. The company wants expanded DDoS protection for the backend. Which solution meets this requirement?`,correct:[`Subscribe to AWS Shield Advanced and add protection to the load balancer Elastic IP addresses`,`Shield Advanced protects Network Load Balancers through their association with Elastic IP addresses that you add.`],wrong:[[`Rely on AWS Shield Standard because it provides expanded protection for all resources in the account`,`Shield Standard gives the baseline protection, and expanded protection needs a Shield Advanced subscription.`],[`Subscribe to AWS Shield Advanced and expect it to protect every resource automatically`,`Shield Advanced does not protect resources automatically, so each resource must be added.`],[`Associate an AWS WAF web ACL with the Network Load Balancer`,`AWS WAF lists Application Load Balancers among its protected resource types, not Network Load Balancers.`]],slot:3,evidence:[`shield-protected-resources|Network Load Balancers, through associations to Amazon EC2 Elastic IP addresses.`,`shield-protected-resources|Shield Advanced doesn't automatically protect your resources.`,`shield-advanced|When you subscribe to Shield Advanced and add protection to your resources, Shield Advanced provides expanded DDoS attack protection for those resources.`]}),t({id:`watchtower-026`,building:`watchtower`,bullets:[`1.2-S3`],d:2,tags:[`mock-reserve`],stem:`A company must inspect the traffic that enters and leaves its VPC subnets, using intrusion prevention rules that are compatible with Suricata. The company wants a managed service. Which solution BEST meets these requirements?`,correct:[`AWS Network Firewall`,`Network Firewall is a managed, stateful firewall with intrusion detection and prevention that supports Suricata compatible rules.`],wrong:[[`AWS WAF`,`AWS WAF monitors HTTP(S) requests to protected web application resources and is not a VPC traffic firewall.`],[`Security groups on the instances`,`Security groups allow traffic by protocol, port, and source and do not provide intrusion prevention rules.`],[`AWS Shield Standard`,`Shield Standard defends against DDoS attacks and does not apply Suricata rules.`]],slot:0,evidence:[`network-firewall|AWS Network Firewall is a stateful, managed, network firewall and intrusion detection and prevention service for your virtual private cloud (VPC) that you create in Amazon Virtual Private Cloud (Amazon VPC).`,`network-firewall|Network Firewall uses the open source intrusion prevention system (IPS), Suricata, for stateful inspection, and supports Suricata compatible rules.`]})],m=Object.values(Object.assign({"../../content/questions/citadel/archive-annex.ts":n,"../../content/questions/citadel/certificate-office.ts":r,"../../content/questions/citadel/charter-hall.ts":i,"../../content/questions/citadel/compliance-registry.ts":a,"../../content/questions/citadel/customs-house.ts":o,"../../content/questions/citadel/embassy-row.ts":s,"../../content/questions/citadel/federation-bridge.ts":c,"../../content/questions/citadel/gatehouse.ts":l,"../../content/questions/citadel/identity-keep.ts":u,"../../content/questions/citadel/key-vault.ts":d,"../../content/questions/citadel/wardens-lodge.ts":f,"../../content/questions/citadel/watchtower.ts":p})).flat();export{m as questions};